package com.rsbingo;

import java.util.ArrayList;
import java.util.List;

/**
 * The shape of plugin_board.php's response. Field names match the JSON exactly so
 * Gson can map it with no annotations.
 *
 * Note what is NOT here: no scoring inputs, no snapshots, no submissions. The
 * server decides what is complete and how many points a team has; this plugin only
 * draws the answer. That keeps one scoring implementation instead of adding a
 * sixth in a language the rest of the project doesn't use.
 */
public class BoardModels
{
	public static class Board
	{
		public String eventId;
		public String name;
		public String format;
		public int cols;
		public int rows;
		public int numTiers;
		public String startDate;
		public String endDate;
		public List<TeamSummary> teams = new ArrayList<>();

		/**
		 * The board's named areas, in the order the server lists them — which is the
		 * order they first appear in the event's tile definitions, not board order.
		 *
		 * A region's colour is derived from its index here, so this ordering is what
		 * keeps the panel painting a region the same colour the website does. Working
		 * it out from {@link #board} instead would order by position and drift.
		 *
		 * Empty when the event has regions switched off.
		 */
		public List<String> regions = new ArrayList<>();

		public boolean hasRegions()
		{
			return regions != null && !regions.isEmpty();
		}

		/** Where a region sits in {@link #regions}, or -1 when it is not one. */
		public int regionIndex(String region)
		{
			if (region == null || region.isEmpty() || regions == null)
			{
				return -1;
			}
			return regions.indexOf(region);
		}

		/** The region on a 1-based board position, or "" for none. */
		public String regionAt(int pos)
		{
			for (BoardTile t : board)
			{
				if (t.pos == pos)
				{
					return t.region == null ? "" : t.region;
				}
			}
			return "";
		}

		/**
		 * The event's codeword, sent only once the site itself would show it. Stamped
		 * onto submission screenshots and used to authorise the submission, so the
		 * player never has to type it anywhere. Null while still withheld.
		 */
		public String codeword;

		/** Only present when a team was requested. */
		public String team;
		public List<BoardTile> board = new ArrayList<>();
		public boolean hiddenTiles;

		/**
		 * When withheld tiles become visible, ISO 8601. Null when the organiser set
		 * no release time, in which case they stay hidden until the setting changes.
		 */
		public String tilesReleaseAt;

		/** How the viewed team's total was arrived at. Null until a team is chosen. */
		public Points points;

		public boolean isShowdown()
		{
			return "Showdown".equals(format);
		}

		/**
		 * A board that mixes both kinds of tile. Its showdown tiles have no tier
		 * ladder: each one is complete or not and pays its own flat points, so the
		 * board is scored like a Blackout one — which is why {@link #isShowdown()}
		 * is deliberately false here. Only the per-tile presentation differs.
		 */
		public boolean isHybrid()
		{
			return "Hybrid".equals(format);
		}

		/** Submissions are only open between the start and end dates. */
		public boolean submissionsOpen()
		{
			return Text.withinEventWindow(startDate, endDate, java.time.Instant.now());
		}

		/** Why submissions are shut, or null when they are open. */
		public String submissionsClosedReason()
		{
			final java.time.Instant now = java.time.Instant.now();
			if (Text.withinEventWindow(startDate, endDate, now))
			{
				return null;
			}
			// Outside the window is one of exactly two things, and the countdown line
			// above already tells them which; this names it in the submit box too.
			return Text.startsAfter(startDate, now)
				? "This event has not started yet."
				: "This event has ended.";
		}
	}

	/** plugin_events.php: the events a linked account belongs to. */
	public static class EventList
	{
		public String username;
		public List<EventSummary> events = new ArrayList<>();
	}

	public static class EventSummary
	{
		public String eventId;
		public String name;
		public String role;
		public String format;
		public String startDate;
		public String endDate;

		@Override
		public String toString()
		{
			// The event dropdown renders this directly. The code is worth showing:
			// it is what someone reads out to a teammate who has not linked an account.
			return (name == null || name.isEmpty() ? eventId : name) + "  (" + eventId + ")";
		}
	}

	/** plugin_themes.php: the site's colour themes. */
	public static class ThemeList
	{
		public String defaultKey;
		public List<Theme> themes = new ArrayList<>();
	}

	public static class Theme
	{
		public String key;
		public String label;
		/** CSS custom properties, e.g. "--accent" -> "#d8a830". */
		public java.util.Map<String, String> vars = new java.util.HashMap<>();

		@Override
		public String toString()
		{
			// The theme dropdown renders this directly.
			return label == null ? (key == null ? "" : key) : label;
		}
	}

	/**
	 * The itemised points for one team, as the website's points tooltip shows them.
	 * Computed by the server — sc_computeAllTeamPointsBreakdown() — which is also
	 * where the total on the standings comes from, so the two cannot disagree.
	 */
	public static class Points
	{
		public boolean isShowdown;
		public int tilePts;
		public int rowPts;
		public int colPts;
		public int diagPts;
		public int clogPts;

		/** Completed line counts. Only meaningful off Showdown, where the site
		 *  labels the rows "Rows (x2)" rather than naming a flat bonus. */
		public int rows;
		public int cols;
		public int diags;

		public int total;

		/** Per-tile contributions, already sorted high to low by the server. */
		public List<PointsTile> tiles = new ArrayList<>();

		/** True when any bonus applies; the site only prints a Total line then. */
		public boolean hasBonuses()
		{
			return rowPts != 0 || colPts != 0 || diagPts != 0 || clogPts != 0;
		}
	}

	public static class PointsTile
	{
		public String label;
		public int pts;
	}

	public static class TeamSummary
	{
		/**
		 * The event's own team number, 1-8, which names the organiser's team badge.
		 * 0 on an event that never set one.
		 */
		public int number;

		public String name;
		public int points;
		public List<String> players = new ArrayList<>();

		@Override
		public String toString()
		{
			// The team dropdown renders this directly.
			return name == null ? "" : name;
		}
	}

	public static class BoardTile
	{
		public int pos;
		public int id;
		public String title;
		public String description;
		public String img;
		public int points;
		public int goal;
		public boolean done;
		public boolean empty;
		public List<String> tags = new ArrayList<>();
		public List<TileItem> items = new ArrayList<>();
		public List<TileGroup> groups = new ArrayList<>();

		/**
		 * Which rules score this tile: "showdown" (accumulate a score toward a
		 * threshold) or "blackout" (collect the items listed). Sent per tile because a
		 * Hybrid board mixes both. Null from a server that predates it, where the
		 * board's format decides for every tile — see {@link #scoredByShowdownRules}.
		 */
		public String tileType;

		/** The named board area this tile belongs to; "" when it has none, and always
		 *  "" while the event has regions switched off. */
		public String region;

		/** Showdown only; absent on Hybrid, whose showdown tiles do not tier. */
		public Integer tier;
		public Integer maxTier;

		/**
		 * Showdown only, and only on tiles that actually have uimTags: the raw tile
		 * score and the points one tier costs. The server derives {@link #tier} from
		 * exactly these two, so the "x% to T3" line below cannot disagree with it.
		 */
		public Double score;
		public Integer tierThreshold;

		/**
		 * What each boss/skill/activity/item on this tile is worth — the site's
		 * "Point Rates" card. Present on every Showdown tile; it is small and static.
		 */
		public List<Rate> rates = new ArrayList<>();

		/**
		 * Who earned what, the site's "Player Progress" card. Only sent for the tile
		 * the panel asked about (`&tile=N`), because it is the bulk of the response —
		 * so this is empty on every other tile and null-safe to iterate.
		 */
		public List<PlayerProgress> players = new ArrayList<>();

		/**
		 * Set only on XP tiles, which are judged on snapshot XP rather than items —
		 * their checklist is always empty, so without this the panel had nothing to
		 * show for them.
		 */
		public XpProgress xp;

		/**
		 * Everything on this tile a player could submit, with the array indices
		 * submit_item.php expects. Empty when the tile takes no submissions, which is
		 * what hides the submit controls.
		 */
		public List<SubmitOption> submitItems = new ArrayList<>();

		public boolean hasTierProgress()
		{
			return score != null && tierThreshold != null && tierThreshold > 0;
		}

		/**
		 * Whether this tile is judged on an accumulated score rather than on a
		 * checklist of items — which decides what collected/required are counted in,
		 * and so whether they may be labelled "items".
		 *
		 * Asked of the tile and the board together: on a Showdown board every tile is
		 * scored this way and older servers send no tileType at all, while on a Hybrid
		 * board only the tiles authored as showdown tiles are.
		 */
		public boolean scoredByShowdownRules(Board board)
		{
			return (board != null && board.isShowdown()) || "showdown".equals(tileType);
		}

		/**
		 * Progress as the server counted it, with its unit — "3/4 items" for a tile
		 * that collects drops, "600/500 pts" for one that accumulates a score. Getting
		 * this wrong reads as a tile needing six hundred of something.
		 */
		public String progressTextWithUnit(Board board)
		{
			return progressText() + (scoredByShowdownRules(board) ? " pts" : " items");
		}

		/** True once every tier is banked — the site labels this "MAX". */
		public boolean tierMaxed()
		{
			return tier != null && maxTier != null && maxTier > 0 && tier >= maxTier;
		}

		/** Score at which the next tier lands. Meaningless once maxed. */
		public double nextTierAt()
		{
			if (!hasTierProgress())
			{
				return 0;
			}
			return ((tier == null ? 0 : tier) + 1) * (double) tierThreshold;
		}

		/** 0..100 toward the next tier. */
		public double pctToNextTier()
		{
			final double target = nextTierAt();
			if (target <= 0)
			{
				return 0;
			}
			return Math.max(0, Math.min(100, (score / target) * 100.0));
		}

		public String displayTitle()
		{
			if (empty)
			{
				return "";
			}
			return (title == null || title.isEmpty()) ? ("Tile " + pos) : title;
		}

		/**
		 * The counts the server judged completion on. Not derivable here: a group
		 * capped by "any 1" contributes once no matter how many options it lists, so
		 * summing the checklist gives a different — and wrong — answer. A Godsword
		 * tile needing 3 shards plus any 1 of 5 hilts is 1/4 done, not 1/8.
		 *
		 * Null when talking to a server that predates these fields; callers fall back
		 * to the checklist sums below.
		 */
		public Integer collected;
		public Integer required;

		public boolean hasCounts()
		{
			return collected != null && required != null && required > 0;
		}

		/** 0..100 for a non-Showdown tile, from the server's counts where available. */
		public double itemsPercent()
		{
			if (done)
			{
				return 100;
			}
			if (hasCounts())
			{
				return Math.max(0, Math.min(100, (collected * 100.0) / required));
			}
			final int needed = neededCount();
			return needed <= 0 ? 0 : Math.max(0, Math.min(100, (approvedCount() * 100.0) / needed));
		}

		/** "1/4" as the server counts it, else the checklist's own tally. */
		public String progressText()
		{
			return hasCounts()
				? (collected + "/" + required)
				: (approvedCount() + "/" + neededCount());
		}

		/** Approved / needed across the flat item list, for the grid's progress line. */
		public int approvedCount()
		{
			int n = 0;
			for (TileItem i : items)
			{
				n += i.approved;
			}
			for (TileGroup g : groups)
			{
				for (TileGroupItem gi : g.items)
				{
					if (gi.approved)
					{
						n++;
					}
				}
			}
			return n;
		}

		public int neededCount()
		{
			int n = 0;
			for (TileItem i : items)
			{
				n += i.need;
			}
			for (TileGroup g : groups)
			{
				n += g.items.size();
			}
			return n;
		}
	}

	/** An XP tile's team total against its goal, and who contributed. */
	public static class XpProgress
	{
		public String skill;
		public double collected;
		public double required;
		public List<XpPlayer> players = new ArrayList<>();

		/** 0..100 toward the goal. */
		public double percent()
		{
			if (required <= 0)
			{
				return 0;
			}
			return Math.max(0, Math.min(100, (collected / required) * 100.0));
		}
	}

	public static class XpPlayer
	{
		public String name;
		public double xp;
	}

	/** One submittable item, carrying the indices the submission endpoint wants. */
	public static class SubmitOption
	{
		public String label;
		public String type;
		public int index;
		public int groupIndex;
		public int itemIndex;
		public boolean approved;
		public boolean pending;

		/** Already approved or awaiting review, so there is nothing to file again. */
		public boolean alreadySubmitted()
		{
			return approved || pending;
		}

		@Override
		public String toString()
		{
			// The submit dropdown renders this directly.
			return label == null ? "" : label;
		}
	}

	/** One row of the point-rates table: "Boss: Nex" / "6000 pts/KC". */
	public static class Rate
	{
		public String label;
		public String rate;
	}

	public static class PlayerProgress
	{
		public String name;
		public double points;
		public List<ProgressLine> lines = new ArrayList<>();
	}

	/** One earning: "Nex", +163, "KC", 978000 points. */
	public static class ProgressLine
	{
		public String label;
		public double gain;
		public String unit;
		public double points;

		/** Items are counted ("x3"); everything else is a gain ("+163 KC"). */
		public String gainText()
		{
			if ("item".equals(unit))
			{
				return "x" + Text.compact(gain);
			}
			return "+" + Text.compact(gain) + (unit == null || unit.isEmpty() ? "" : " " + unit);
		}
	}

	public static class TileItem
	{
		public String label;
		public int need;
		public int approved;
		/** Submitted and awaiting review — the site's "?" state. */
		public int pending;
		/** Who sent it. Empty when nobody has, or the submission recorded no player. */
		public String player;
	}

	public static class TileGroup
	{
		public String name;
		public String logic;
		public List<TileGroupItem> items = new ArrayList<>();
	}

	public static class TileGroupItem
	{
		public String label;
		public boolean approved;
		/** Submitted and awaiting review — the site's "?" state. */
		public boolean pending;
		/** Who sent it. Empty when nobody has, or the submission recorded no player. */
		public String player;
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JTextArea;
import javax.swing.text.DefaultCaret;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * The site's look, in Swing.
 *
 * Colours are the "Obsidian Gold" theme from js/themes.js — the project's default
 * and the one every screenshot is taken in — rather than anything invented here.
 * The names map one-to-one onto the CSS custom properties so the two can be
 * compared: {@code --bg-well} is {@link #BG_WELL}, {@code --accent} is
 * {@link #ACCENT}, and so on.
 *
 * The visual grammar is the same as the modal's: gold uppercase section labels
 * above near-black rounded "wells" that hold the content.
 */
final class Brand
{
	// The live palette. Not final: the panel can be switched to any of the site's
	// themes at runtime. These starting values are Obsidian Gold, the site's default,
	// and are what the panel falls back to if the theme endpoint can't be reached —
	// so a missing server means "looks as shipped", never "loses its styling".
	/** --bg-tile: the panel itself. */
	static Color BG_TILE = new Color(0x141410);
	/** --bg-well: recessed boxes inside it. */
	static Color BG_WELL = new Color(0x040404);
	/** --bg-completed-well: the same box on a finished tile. */
	static Color BG_COMPLETED_WELL = new Color(0x1A1408);

	/**
	 * The background the site gives a finished tile — a lifted, accent-tinted
	 * version of the plain tile colour, not merely a lighter grey. Board cells
	 * blend towards it as a Showdown tile climbs its tiers.
	 */
	static Color BG_COMPLETED = new Color(0x282010);
	/** --border-main */
	static Color BORDER = new Color(0x2A2820);
	/** --accent */
	static Color ACCENT = new Color(0xD8A830);
	/** --text-main */
	static Color TEXT_MAIN = new Color(0xC09828);
	/** --text-bright */
	static Color TEXT_BRIGHT = new Color(0xF0D888);
	/** --text-dim */
	static Color TEXT_DIM = new Color(0x706858);
	/** --text-completed */
	static Color COMPLETED = new Color(0xD8A830);

	/**
	 * Repaints the palette from one of the site's themes.
	 *
	 * Keys are the CSS custom properties as js/themes.js writes them, so the mapping
	 * below is the whole translation layer between the website's styling and this
	 * panel's. Anything absent keeps its current value rather than defaulting to
	 * black, which is what a partial theme would otherwise produce.
	 */
	static void applyPalette(java.util.Map<String, String> vars)
	{
		if (vars == null || vars.isEmpty())
		{
			return;
		}

		BG_TILE = parse(vars.get("--bg-tile"), BG_TILE);
		BG_WELL = parse(vars.get("--bg-well"), BG_WELL);
		BG_COMPLETED_WELL = parse(vars.get("--bg-completed-well"), BG_COMPLETED_WELL);
		BG_COMPLETED = parse(vars.get("--bg-completed"), BG_COMPLETED);
		BORDER = parse(vars.get("--border-main"), BORDER);
		ACCENT = parse(vars.get("--accent"), ACCENT);
		TEXT_MAIN = parse(vars.get("--text-main"), TEXT_MAIN);
		TEXT_BRIGHT = parse(vars.get("--text-bright"), TEXT_BRIGHT);
		TEXT_DIM = parse(vars.get("--text-dim"), TEXT_DIM);
		COMPLETED = parse(vars.get("--text-completed"), COMPLETED);
	}

	/**
	 * A region's colour: the theme accent's own hue, rotated by the golden angle once
	 * per region, at a fixed saturation and lightness.
	 *
	 * Deliberately the same formula the website uses —
	 * {@code hsl(calc(var(--accent-h) + index * 137.508) 70% 60%)} — so a region is
	 * the same colour in the panel as on the board a player is looking at beside it.
	 * The golden angle is what keeps the colours apart at any number of regions;
	 * stepping by a round number like 90 would land the fifth region back on the first.
	 *
	 * @param index the region's position in {@link BoardModels.Board#regions}
	 */
	/** What themes.js falls back to for a colour with no hue: the default gold. */
	private static final double ACCENT_HUE_FALLBACK = 42;

	static Color regionColor(int index)
	{
		if (index < 0)
		{
			return TEXT_DIM;
		}
		final float[] hsb = Color.RGBtoHSB(ACCENT.getRed(), ACCENT.getGreen(), ACCENT.getBlue(), null);
		// Hue is the same angle in HSB and HSL, so it carries over; saturation and
		// lightness do not, which is why the conversion below is HSL and not
		// Color.getHSBColor(). Using HSB there gives visibly different colours.
		//
		// Rounded to a whole degree because themes.js publishes --accent-h that way,
		// and the website's colours are computed from that rounded value. Carrying the
		// extra precision here put the panel a shade off the board it sits beside.
		//
		// A greyscale accent has no hue to rotate away from, and the two sides have to
		// agree on what to do about that. themes.js substitutes the default gold;
		// RGBtoHSB reports 0, which is red. Two of the thirty themes ship a greyscale
		// accent (#ffffff and #cccccc), and on those the panel drew a red-based set of
		// regions against the site's gold-based one.
		final double base = (hsb[1] == 0f) ? ACCENT_HUE_FALLBACK : Math.round(hsb[0] * 360.0);
		final double hue = (base + index * 137.508) % 360.0;
		return hsl(hue, 0.70, 0.60);
	}

	/** CSS hsl() -> Color. Java ships HSB (HSV) only, and the two are not the same. */
	private static Color hsl(double hDegrees, double s, double l)
	{
		final double h = ((hDegrees % 360) + 360) % 360;
		final double c = (1 - Math.abs(2 * l - 1)) * s;
		final double x = c * (1 - Math.abs(((h / 60.0) % 2) - 1));
		final double m = l - c / 2;

		double r = 0, g = 0, b = 0;
		if (h < 60)       { r = c; g = x; }
		else if (h < 120) { r = x; g = c; }
		else if (h < 180) { g = c; b = x; }
		else if (h < 240) { g = x; b = c; }
		else if (h < 300) { r = x; b = c; }
		else              { r = c; b = x; }

		return new Color(
			(int) Math.round((r + m) * 255),
			(int) Math.round((g + m) * 255),
			(int) Math.round((b + m) * 255));
	}

	/** "#d8a830" -> Color, keeping the old value on anything unparseable. */
	private static Color parse(String hex, Color fallback)
	{
		if (hex == null)
		{
			return fallback;
		}
		final String v = hex.trim().replace("#", "");
		if (v.length() != 6)
		{
			return fallback;
		}
		try
		{
			return new Color(Integer.parseInt(v, 16));
		}
		catch (NumberFormatException e)
		{
			return fallback;
		}
	}

	private static final int RADIUS = 6;

	/** RuneLite's fixed side-panel width. */
	static final int PANEL_WIDTH = 225;
	/** Outer insets used by both cards, per side. */
	static final int PAD = 4;
	/** The vertical scrollbar, which is always allowed for so text never reflows. */
	static final int SCROLLBAR = 8;

	/** Full width for a standalone block: the panel less padding and the scrollbar. */
	static final int CONTENT_WIDTH = PANEL_WIDTH - (PAD * 4) - SCROLLBAR;

	/** The same less a row's own padding. */
	static final int ROW_WIDTH = CONTENT_WIDTH - (PAD * 2);
	static final int ROW_GAP = 4;

	/**
	 * Below this, a row's name and value stop sharing a line and stack instead.
	 * Roughly a dozen characters of the small font — narrower than this and the name
	 * wraps into an unreadable column.
	 */
	static final int MIN_LABEL_WIDTH = 60;

	private Brand()
	{
	}

	/**
	 * A label that wraps: read-only, transparent, no border — styled to look like a
	 * JLabel but able to break across lines.
	 *
	 * A JTextArea rather than an HTML JLabel because Swing treats {@code width:Npx}
	 * as a hint, not a constraint, and long text rendered past the panel and lost its
	 * right edge mid-word. Plain text also can't be tripped up by markup in an
	 * organiser's tile description.
	 */
	static JTextArea wrapping(Font font, Color foreground)
	{
		final JTextArea ta = new JTextArea();
		ta.setLineWrap(true);
		ta.setWrapStyleWord(true);
		ta.setEditable(false);
		ta.setFocusable(false);
		ta.setOpaque(false);
		ta.setBorder(null);
		ta.setFont(font);
		ta.setForeground(foreground);
		ta.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Without this, setText() moves the caret and the text area drags the
		// enclosing scroll pane down to follow it.
		if (ta.getCaret() instanceof DefaultCaret)
		{
			((DefaultCaret) ta.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		}
		return ta;
	}

	/**
	 * Sets a wrapping block's text and tells it the width it will be laid out at.
	 * Without the width it reports the height of a single line and everything past
	 * the first wrap is clipped — the more so once a scrollbar takes another 8px.
	 */
	static void setWrapped(JTextArea area, String text)
	{
		area.setText(text);
		area.setSize(CONTENT_WIDTH, Short.MAX_VALUE);
	}

	/**
	 * A label/value row. The value keeps its natural width on the right and the label
	 * takes what's left and wraps into it — at this width "Boss: Corrupted Gauntlet"
	 * and "12000 pts/KC" do not fit on one line, and the alternative is one of them
	 * being clipped.
	 */
	static JPanel valueRow(String left, String right, Color leftColor, Color rightColor, Color background)
	{
		final JPanel row = new JPanel(new java.awt.BorderLayout(ROW_GAP, 0))
		{
			@Override
			public Dimension getMaximumSize()
			{
				// Height follows the wrapped label; without this BoxLayout stretches
				// the row to soak up leftover vertical space.
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		row.setBackground(background);
		row.setOpaque(background != null);
		row.setBorder(BorderFactory.createEmptyBorder(2, PAD, 2, PAD));
		row.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JTextArea label = wrapping(FontManager.getRunescapeSmallFont(), leftColor);
		label.setText(left);

		final JLabel value = new JLabel(right);
		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(rightColor);
		value.setVerticalAlignment(javax.swing.SwingConstants.TOP);

		// Some values are longer than the whole panel — a raid tile's purple rate is
		// "125000 pts/item <=5 / 62500 pts/item >5". Side by side, BorderLayout gives
		// EAST its full preferred width and leaves the label nothing, so the label
		// wrapped to one character per line and neither half could be read. Past that
		// point the two stack instead: name on its own line, rate wrapped beneath it.
		final int labelWidth = ROW_WIDTH - value.getPreferredSize().width - ROW_GAP;
		if (labelWidth < MIN_LABEL_WIDTH)
		{
			row.setLayout(new BoxLayout(row, BoxLayout.Y_AXIS));

			// Sized to ROW_WIDTH rather than through setWrapped(), which assumes the
			// full content width; these sit inside a row that is already padded.
			label.setSize(ROW_WIDTH, Short.MAX_VALUE);

			final JTextArea wrappedValue = wrapping(FontManager.getRunescapeSmallFont(), rightColor);
			wrappedValue.setText(right);
			wrappedValue.setSize(ROW_WIDTH, Short.MAX_VALUE);

			row.add(label);
			row.add(wrappedValue);
			return row;
		}

		// A JTextArea works out its wrapped height from its current width, and inside
		// a BorderLayout it is asked for that height before it has been given one — so
		// it answers "one line" and the rest of the label is cut off. Tell it the
		// width it is going to get.
		label.setSize(labelWidth, Short.MAX_VALUE);

		row.add(label, java.awt.BorderLayout.CENTER);
		row.add(value, java.awt.BorderLayout.EAST);
		return row;
	}

	/** A vertical stack of rows. Transparent, so a well behind it shows through. */
	static JPanel section()
	{
		final JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** A gold uppercase section label, as the modal sets them. */
	static JLabel sectionLabel(String text)
	{
		final JLabel l = new JLabel(text.toUpperCase());
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ACCENT);
		l.setBorder(BorderFactory.createEmptyBorder(10, PAD - 2, 4, PAD - 2));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	/** A recessed rounded box. Stacks its children vertically. */
	static JPanel well()
	{
		final RoundedPanel p = new RoundedPanel(BG_WELL, BORDER);
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBorder(BorderFactory.createEmptyBorder(6, PAD + 2, 6, PAD + 2));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/**
	 * A button drawn the way {@link #well()} draws a panel: same corner radius, same
	 * fill, so a control and a section read as parts of one surface rather than a
	 * rounded box with a square button sitting on it.
	 *
	 * Swing will not round a JButton for us. The look-and-feel is told to fill
	 * nothing ({@code setContentAreaFilled(false)}) and the component is not opaque,
	 * so the only thing painting a background is the rounded rectangle below;
	 * {@code super.paintComponent} then draws the label over it.
	 *
	 * Colours are read at paint time, not captured here, so a theme change applies
	 * without rebuilding the button.
	 */
	static JButton button(String text, Color foreground)
	{
		final JButton b = new JButton(text)
		{
			@Override
			protected void paintComponent(Graphics graphics)
			{
				final Graphics2D g = (Graphics2D) graphics.create();
				try
				{
					g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

					// Pressed lifts to the tile colour: without it nothing on screen
					// acknowledges the click until the panel has already changed.
					g.setColor(getModel().isPressed() ? BG_TILE : BG_WELL);
					g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);

					// A disabled button keeps the shape but drops out of the accent,
					// so "nothing left to submit" doesn't look like something to press.
					g.setColor(isEnabled() ? ACCENT : BORDER);
					g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
				finally
				{
					g.dispose();
				}
				super.paintComponent(graphics);
			}
		};

		b.setFocusPainted(false);
		b.setContentAreaFilled(false);
		b.setOpaque(false);
		b.setForeground(foreground);
		b.setBorder(BorderFactory.createEmptyBorder(7, 8, 7, 8));
		return b;
	}

	/** A small gold-outlined pill, for the points count and tag chips. */
	static JPanel badge(String text, Color foreground)
	{
		final RoundedPanel p = new RoundedPanel(null, foreground.darker());
		p.setLayout(new BoxLayout(p, BoxLayout.X_AXIS));
		p.setBorder(BorderFactory.createEmptyBorder(1, 5, 1, 5));

		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(foreground);
		p.add(l);

		// Pills must not stretch to the panel width when stacked vertically.
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	/** Mix two colours. {@code amount} 0 gives {@code from}, 1 gives {@code to}. */
	static Color blend(Color from, Color to, float amount)
	{
		final float p = Math.max(0f, Math.min(1f, amount));
		return new Color(
			(int) (from.getRed() + (to.getRed() - from.getRed()) * p),
			(int) (from.getGreen() + (to.getGreen() - from.getGreen()) * p),
			(int) (from.getBlue() + (to.getBlue() - from.getBlue()) * p));
	}

	static Font bold(float size)
	{
		return FontManager.getRunescapeBoldFont().deriveFont(size);
	}

	/**
	 * Centres a component across the full panel width.
	 *
	 * Setting {@code CENTER_ALIGNMENT} on one child of a BoxLayout whose siblings are
	 * left-aligned does not do this — the layout reconciles the mixed alignments and
	 * the component ends up somewhere arbitrary. A full-width wrapper that centres
	 * its own child is unambiguous.
	 */
	static JPanel centered(Component inner)
	{
		final JPanel p = new JPanel(new java.awt.GridBagLayout())
		{
			@Override
			public Dimension getMaximumSize()
			{
				return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
			}
		};
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(inner);
		return p;
	}

	/**
	 * A panel with rounded corners.
	 *
	 * Swing has no rounded background, so the fill and border are painted here and
	 * the component is left non-opaque — otherwise the square default background
	 * paints over the corners.
	 */
	static class RoundedPanel extends JPanel
	{
		private final Color fill;
		private final Color line;

		RoundedPanel(Color fill, Color line)
		{
			this.fill = fill;
			this.line = line;
			setOpaque(false);
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			final Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				if (fill != null)
				{
					g.setColor(fill);
					g.fillRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
				if (line != null)
				{
					g.setColor(line);
					g.drawRoundRect(0, 0, getWidth() - 1, getHeight() - 1, RADIUS, RADIUS);
				}
			}
			finally
			{
				g.dispose();
			}
			super.paintComponent(graphics);
		}
	}

	/**
	 * The modal's progress bar: a dark rounded track with a gold gradient fill.
	 * Swing's JProgressBar can't be talked into rounded ends or a gradient without
	 * a custom UI delegate, which is more code than simply drawing it.
	 */
	static class ProgressBar extends JPanel
	{
		private double percent;
		private boolean complete;

		ProgressBar()
		{
			setOpaque(false);
			setPreferredSize(new Dimension(10, 8));
			setMaximumSize(new Dimension(Integer.MAX_VALUE, 8));
			setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		void setProgress(double pct, boolean isComplete)
		{
			this.percent = Math.max(0, Math.min(100, pct));
			this.complete = isComplete;
			repaint();
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			final Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				final int w = getWidth();
				final int h = getHeight();

				g.setColor(BG_WELL);
				g.fillRect(0, 0, w - 1, h - 1);
				g.setColor(BORDER);
				g.drawRect(0, 0, w - 1, h - 1);

				final int fillWidth = (int) Math.round((w - 2) * (percent / 100.0));
				if (fillWidth <= 0)
				{
					return;
				}

				// Darker gold to bright gold, left to right — the same sweep the site
				// uses, which reads as progress even at eight pixels tall.
				//
				// Square ends, so the fill's width is exactly the percentage. Rounded
				// caps had to be padded to at least the bar's height or they collapsed
				// into a lens shape, which overstated small values.
				g.setPaint(new GradientPaint(
					0, 0, complete ? COMPLETED.darker() : TEXT_MAIN.darker(),
					fillWidth, 0, complete ? TEXT_BRIGHT : ACCENT));
				g.fillRect(1, 1, fillWidth, h - 3);
			}
			finally
			{
				g.dispose();
			}
		}
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import javax.imageio.ImageIO;

/**
 * Turns a captured game frame into the PNG that gets filed as proof.
 *
 * The frame is stamped with the event codeword, the player and the item. The
 * codeword is the point: a reviewer seeing it knows the shot came from the plugin
 * at capture time rather than being an image picked off disk, because only someone
 * holding the event's codeword could have produced it.
 */
final class ProofShot
{
	private static final int MARGIN = 10;
	private static final Color BAR = new Color(0, 0, 0, 190);

	private ProofShot()
	{
	}

	/**
	 * @return PNG bytes, or null if the frame could not be encoded.
	 */
	static byte[] stamp(Image frame, String event, String codeword, String player, String item)
	{
		final BufferedImage img = toBuffered(frame);
		if (img == null)
		{
			return null;
		}

		final Graphics2D g = img.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING,
				RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

			// Three lines: which event this is for, who sent it and what for, then the
			// codeword. A reviewer looking at a folder of screenshots can tell them
			// apart from the first line alone.
			final String title = (event == null || event.trim().isEmpty())
				? "rs-bingo" : event.trim();
			final String who = player + "  -  " + item;
			// An event can still be withholding its codeword. The shot is worth filing
			// either way, so fall back to naming the source rather than stamping
			// "codeword: null" onto a reviewer's evidence.
			final String mark = (codeword == null || codeword.trim().isEmpty())
				? "via rs-bingo RuneLite plugin"
				: ("rs-bingo codeword: " + codeword.trim());

			// Top left: the reviewer's eye lands there first, and it is the one corner
			// the game does not fill with the minimap, inventory or chat.
			final Font heading = new Font(Font.SANS_SERIF, Font.BOLD, 24);
			final Font body = new Font(Font.SANS_SERIF, Font.BOLD, 20);

			g.setFont(heading);
			final int headingHeight = g.getFontMetrics().getHeight();
			final int titleWidth = g.getFontMetrics().stringWidth(title);

			g.setFont(body);
			final int lineHeight = g.getFontMetrics().getHeight();
			final int bodyWidth = Math.max(
				g.getFontMetrics().stringWidth(who),
				g.getFontMetrics().stringWidth(mark));

			final int barHeight = headingHeight + (lineHeight * 2) + MARGIN;

			// A backing bar, so the text stays readable over whatever is on screen.
			final int barWidth = Math.max(titleWidth, bodyWidth) + (MARGIN * 2);
			g.setColor(BAR);
			g.fillRoundRect(MARGIN, MARGIN, Math.min(barWidth, img.getWidth() - (MARGIN * 2)),
				barHeight, 10, 10);

			final int textLeft = MARGIN * 2;
			int baseline = MARGIN + headingHeight;

			g.setFont(heading);
			g.setColor(new Color(0xF0D888));
			g.drawString(title, textLeft, baseline);

			g.setFont(body);
			baseline += lineHeight;
			g.setColor(Color.WHITE);
			g.drawString(who, textLeft, baseline);

			baseline += lineHeight;
			g.setColor(new Color(0xD8A830));
			g.drawString(mark, textLeft, baseline);
		}
		finally
		{
			g.dispose();
		}

		try
		{
			final ByteArrayOutputStream out = new ByteArrayOutputStream();
			ImageIO.write(img, "png", out);
			return out.toByteArray();
		}
		catch (IOException e)
		{
			return null;
		}
	}

	/**
	 * DrawManager hands back an Image, which is usually already a BufferedImage but
	 * isn't guaranteed to be; drawing onto it needs one either way.
	 */
	private static BufferedImage toBuffered(Image frame)
	{
		if (frame == null)
		{
			return null;
		}
		if (frame instanceof BufferedImage)
		{
			return (BufferedImage) frame;
		}

		final int w = frame.getWidth(null);
		final int h = frame.getHeight(null);
		if (w <= 0 || h <= 0)
		{
			return null;
		}

		final BufferedImage copy = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = copy.createGraphics();
		try
		{
			g.drawImage(frame, 0, 0, null);
		}
		finally
		{
			g.dispose();
		}
		return copy;
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.net.ConnectException;
import java.net.UnknownHostException;
import java.net.SocketTimeoutException;
import javax.net.ssl.SSLException;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.MultipartBody;
import okhttp3.OkHttpClient;
import okhttp3.RequestBody;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Fetches board state. Read-only: nothing here writes to the event, and no
 * credentials are sent — the event code alone is what grants a view, exactly as it
 * does for the website's board pages.
 */
@Slf4j
@Singleton
public class RsBingoApi
{
	private final OkHttpClient httpClient;
	private final Gson gson;

	// Package-private rather than private so PanelPreview can build one directly.
	@Inject
	RsBingoApi(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	public void fetchBoard(String baseUrl, String eventCode, String team,
						   Consumer<BoardModels.Board> onOk, Consumer<String> onError)
	{
		fetchBoard(baseUrl, eventCode, team, 0, onOk, onError);
	}

	/**
	 * @param team    null or empty for the event summary and team list only.
	 * @param tilePos board position whose player breakdown is wanted, or 0 for none.
	 *                Asking for it here rather than in a second call keeps a refresh
	 *                to one request whether or not a tile is open.
	 * @param onOk    called off the EDT — callers must marshal to Swing themselves.
	 */
	public void fetchBoard(String baseUrl, String eventCode, String team, int tilePos,
						   Consumer<BoardModels.Board> onOk, Consumer<String> onError)
	{
		final HttpUrl parsed = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_board.php");
		if (parsed == null)
		{
			onError.accept("That site URL doesn't look right.");
			return;
		}

		final HttpUrl.Builder url = parsed.newBuilder().addQueryParameter("eventId", eventCode);
		if (team != null && !team.isEmpty())
		{
			url.addQueryParameter("team", team);
		}
		if (tilePos > 0)
		{
			url.addQueryParameter("tile", Integer.toString(tilePos));
		}

		final Request request = new Request.Builder().url(url.build()).get().build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("rs-bingo board fetch failed: {}", reason(e));
				log.debug("rs-bingo board fetch failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String body = res.body() == null ? "" : res.body().string();

					if (!res.isSuccessful())
					{
						// The endpoint reports its own reasons; surface them rather
						// than a bare status code.
						onError.accept(messageFor(res.code(), body));
						return;
					}

					final BoardModels.Board board = gson.fromJson(body, BoardModels.Board.class);
					if (board == null || board.eventId == null)
					{
						onError.accept("Unexpected response from the site.");
						return;
					}
					onOk.accept(board);
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while loading.");
				}
			}
		});
	}

	/**
	 * The site's colour themes. Failure is not surfaced to the user: the panel keeps
	 * the palette it ships with, which is the site's default anyway.
	 */
	public void fetchThemes(String baseUrl, Consumer<BoardModels.ThemeList> onOk)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_themes.php");
		if (url == null)
		{
			return;
		}

		httpClient.newCall(new Request.Builder().url(url).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.debug("rs-bingo theme fetch failed", e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						return;
					}
					final BoardModels.ThemeList list =
						gson.fromJson(res.body().string(), BoardModels.ThemeList.class);
					if (list != null && !list.themes.isEmpty())
					{
						onOk.accept(list);
					}
				}
				catch (JsonSyntaxException | IOException e)
				{
					log.debug("rs-bingo theme response unreadable", e);
				}
			}
		});
	}

	/**
	 * The events a linked account belongs to.
	 *
	 * The token goes in a header rather than the query string so it stays out of
	 * server access logs and proxy caches.
	 */
	public void fetchMyEvents(String baseUrl, String token,
							  Consumer<BoardModels.EventList> onOk, Consumer<String> onError)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/plugin_events.php");
		if (url == null || token == null || token.trim().isEmpty())
		{
			return;
		}

		final Request request = new Request.Builder()
			.url(url)
			.header("X-Bingo-Token", token.trim())
			.get()
			.build();

		httpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("rs-bingo event list failed: {}", reason(e));
				log.debug("rs-bingo event list failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String body = res.body() == null ? "" : res.body().string();
					if (!res.isSuccessful())
					{
						onError.accept(messageFor(res.code(), body));
						return;
					}
					final BoardModels.EventList list = gson.fromJson(body, BoardModels.EventList.class);
					if (list != null)
					{
						onOk.accept(list);
					}
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while loading events.");
				}
			}
		});
	}

	/**
	 * File a submission. The plugin's only write.
	 *
	 * Authorised by roster membership: the server checks the named player is on the
	 * named team of this event. No codeword or session is sent — see the note at the
	 * top of submit_item.php. Everything files as pending, so this cannot score
	 * anything on its own.
	 */
	public void submitItem(String baseUrl, String eventId, String team,
						   String player, int tilePos, int tileRefId, BoardModels.SubmitOption option,
						   byte[] png, Runnable onOk, Consumer<String> onError)
	{
		final HttpUrl url = HttpUrl.parse(trimTrailingSlash(baseUrl) + "/submit_item.php");
		if (url == null)
		{
			onError.accept("That site URL doesn't look right.");
			return;
		}

		// Matches what game.html posts, indices included, so a plugin submission is
		// indistinguishable from a website one once it lands.
		final String itemData = gson.toJson(new SubmissionItem(option));

		final RequestBody body = new MultipartBody.Builder()
			.setType(MultipartBody.FORM)
			.addFormDataPart("eventId", eventId)
			// Routing, not a credential: it tells the endpoint this is a client
			// submission with no browser session to present.
			.addFormDataPart("source", "plugin")
			.addFormDataPart("team", team)
			.addFormDataPart("player", player)
			.addFormDataPart("tileId", Integer.toString(tilePos))
			.addFormDataPart("tileRefId", Integer.toString(tileRefId))
			.addFormDataPart("itemData", itemData)
			.addFormDataPart("image", "proof.png",
				RequestBody.create(MediaType.parse("image/png"), png))
			.build();

		httpClient.newCall(new Request.Builder().url(url).post(body).build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("rs-bingo submission failed: {}", reason(e));
				log.debug("rs-bingo submission failed", e);
				onError.accept(describe(e));
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					final String text = res.body() == null ? "" : res.body().string();
					final SubmitResult result = gson.fromJson(text, SubmitResult.class);

					if (res.isSuccessful() && result != null && result.success)
					{
						onOk.run();
						return;
					}

					// The endpoint explains itself (wrong codeword, not on the team,
					// event not started); pass that through rather than a status code.
					String message = result == null ? null : (result.message != null ? result.message : result.error);
					if (message == null || message.isEmpty())
					{
						message = "Submission failed (" + res.code() + ").";
					}
					onError.accept(message);
				}
				catch (JsonSyntaxException e)
				{
					onError.accept("Could not read the site's response.");
				}
				catch (IOException e)
				{
					onError.accept("Connection dropped while submitting.");
				}
			}
		});
	}

	/** The itemData payload, shaped exactly as game.html's submission builds it. */
	private static class SubmissionItem
	{
		final String label;
		final int index;
		final String type;
		final int groupIndex;
		final int groupItemIndex;

		SubmissionItem(BoardModels.SubmitOption option)
		{
			this.label = option.label;
			this.index = option.index;
			this.type = option.type;
			this.groupIndex = option.groupIndex;
			this.groupItemIndex = option.itemIndex;
		}
	}

	private static class SubmitResult
	{
		boolean success;
		String message;
		String error;
	}

	/**
	 * Turn a transport failure into something a player can act on.
	 *
	 * Every one of these used to read "Could not reach the site", which is true but
	 * useless: a machine that cannot resolve the name, one behind a captive portal
	 * and one with a broken clock rejecting the certificate all looked identical,
	 * and the only way to tell them apart was to reproduce it yourself.
	 */
	/**
	 * One line naming what actually went wrong, for the client log.
	 *
	 * The panel's wording is for the player; this is for whoever they send their
	 * log to. "PKIX path building failed" and "certificate expired" both read as
	 * "secure connection failed" on screen but mean entirely different fixes, and
	 * at debug level neither was ever seen.
	 */
	private static String reason(IOException e)
	{
		final String message = e.getMessage();
		return e.getClass().getSimpleName() + (message == null ? "" : (": " + message));
	}

	private static String describe(IOException e)
	{
		final String host = HttpUrl.parse(RsBingoConfig.SITE_URL) != null
			? HttpUrl.parse(RsBingoConfig.SITE_URL).host()
			: RsBingoConfig.SITE_URL;

		if (e instanceof UnknownHostException)
		{
			return "Can't find " + host + ". Check your internet connection or DNS.";
		}
		if (e instanceof SocketTimeoutException)
		{
			return host + " timed out. It may be down, or your connection is blocking it.";
		}
		if (e instanceof SSLException)
		{
			// Antivirus first: on a home machine HTTPS scanning is far and away the
			// usual cause. It re-signs traffic with its own certificate, which the
			// browser trusts because the installer added it to Windows, and Java does
			// not because it keeps its own list.
			return "Secure connection to " + host + " failed. Usually antivirus HTTPS "
				+ "scanning, a VPN, or a wrong system clock.";
		}
		if (e instanceof ConnectException)
		{
			return "Connection to " + host + " was refused.";
		}
		return "Could not reach " + host + ".";
	}

	private String messageFor(int code, String body)
	{
		try
		{
			final ApiError err = gson.fromJson(body, ApiError.class);
			if (err != null && err.error != null && !err.error.isEmpty())
			{
				return err.error;
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// fall through to the generic wording
		}

		if (code == 401)
		{
			return "Account token not accepted - re-link from the site.";
		}
		if (code == 404)
		{
			return "No event with that code.";
		}
		if (code == 429)
		{
			return "Too many requests - try again shortly.";
		}
		return "Site returned an error (" + code + ").";
	}

	private static String trimTrailingSlash(String s)
	{
		final String v = s == null ? "" : s.trim();
		return v.endsWith("/") ? v.substring(0, v.length() - 1) : v;
	}

	private static class ApiError
	{
		String error;
	}
}

package com.rsbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(RsBingoConfig.GROUP)
public interface RsBingoConfig extends Config
{
	String GROUP = "rsbingo";

	/**
	 * The one address this plugin ever contacts. Deliberately a constant and not a
	 * setting: a plugin may only talk to addresses that are hardcoded or typed by
	 * the user, so there is nothing here for a config value — or a server response —
	 * to redirect.
	 */
	String SITE_URL = "https://rs-bingo.com";

	@ConfigItem(
		keyName = "eventCode",
		name = "Event code",
		description = "The event ID from the organiser, e.g. NSM930. Leave blank to hide the board.",
		position = 1
	)
	default String eventCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "refreshSeconds",
		name = "Refresh (seconds)",
		description = "How often to re-fetch the board. 0 disables automatic refresh.",
		position = 3
	)
	default int refreshSeconds()
	{
		return 60;
	}

	/**
	 * Links this client to a site account so the panel can list the events you are
	 * in. Minted at /plugin_link.php while signed in with Discord.
	 *
	 * Read-only and narrowly scoped by design: it lists your events and nothing
	 * else. Optional — the plugin works without it, given an event code.
	 */
	@ConfigItem(
		keyName = "accountToken",
		name = "Account token",
		description = "Paste from the site's Link RuneLite plugin page to list your events. "
			+ "Optional; leave blank and enter event codes by hand.",
		secret = true,
		position = 1
	)
	default String accountToken()
	{
		return "";
	}

	@ConfigItem(
		keyName = "chatTeamIcons",
		name = "Team icons in chat",
		description = "Mark event participants in chat with their team's colour.",
		position = 5
	)
	default boolean chatTeamIcons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "dropTeamIcons",
		name = "Team icons on drops",
		description = "Mark participants named in drop and loot broadcasts.",
		position = 6
	)
	default boolean dropTeamIcons()
	{
		return true;
	}

	@ConfigItem(
		keyName = "overheadTeamIcons",
		name = "Team icons above players",
		description = "Draw a participant's team colour over their head in game.",
		position = 7
	)
	default boolean overheadTeamIcons()
	{
		return true;
	}

	/**
	 * Off by default: you already know which team you are on, and the space over
	 * your own character is the most crowded on screen.
	 */
	@ConfigItem(
		keyName = "overheadOwnPlayer",
		name = "...including yourself",
		description = "Draw the team colour over your own character too.",
		position = 8
	)
	default boolean overheadOwnPlayer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showTileImages",
		name = "Show tile images",
		description = "Draw each tile's artwork. Turn off to save bandwidth - a board's "
			+ "art can run to several MB the first time it loads.",
		position = 4
	)
	default boolean showTileImages()
	{
		return true;
	}

	/**
	 * Written by the panel's theme dropdown. The list itself comes from the site, so
	 * this is a key rather than an enum — adding a theme to js/themes.js is enough to
	 * make it selectable here, with no plugin change.
	 */
	@ConfigItem(
		keyName = "theme",
		name = "Theme",
		description = "Remembers the colour theme picked in the panel.",
		hidden = true,
		position = 6
	)
	default String theme()
	{
		return "";
	}

	/**
	 * Written by the panel's dropdown, not typed by hand — it exists so reopening
	 * the client returns to the team you were watching rather than whichever one is
	 * top of the table that day.
	 */
	@ConfigItem(
		keyName = "selectedTeam",
		name = "Selected team",
		description = "Remembers the team picked in the panel.",
		hidden = true,
		position = 5
	)
	default String selectedTeam()
	{
		return "";
	}
}

