/**
 * Side panel: event code, team dropdown, the board grid, and — swapped in over it —
 * a tile's detail view.
 */
class RsBingoPanel extends PluginPanel
{
	private static final String CARD_BOARD = "board";
	private static final String CARD_TILE = "tile";

	private static final int CELL_GAP = 3;
	/** Panel width less this class's insets and the scrollbar. */
	private static final int GRID_WIDTH = PANEL_WIDTH - (Brand.PAD * 2) - Brand.SCROLLBAR;

	private final RsBingoApi api;
	private final RsBingoConfig config;

	/** Hardcoded in the client; see the constructor. */
	private final String siteUrl;
	private final Runnable onEventCodeChanged;
	private final Consumer<String> onTeamSelected;
	private final Consumer<BoardModels.Theme> onThemeSelected;
	private final Consumer<String> onEventSelected;

	/** Told about every board that arrives, whichever request fetched it. */
	private final Consumer<BoardModels.Board> onBoardLoaded;
	private final ScreenshotSource screenshots;

	/** Grabs the next rendered game frame. Supplied by the plugin, which has DrawManager. */
	interface ScreenshotSource
	{
		void capture(Consumer<java.awt.Image> onFrame);
	}
	private final TileImageCache images;

	private final JComboBox<BoardModels.TeamSummary> teamBox = new JComboBox<>();
	/**
	 * Wraps rather than clips. This line doubles as the error channel, and a
	 * JLabel cut "Secure connection to rs-bingo.com failed. Check your system
	 * clock..." off at "Ch...", hiding every part that said what to do.
	 */
	private final JTextArea statusLabel = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
	/** Wraps rather than clips: event names are organiser-supplied and can be long. */
	private final JTextArea headerLabel = new JTextArea();
	/**
	 * The board. Paints each region's perimeter itself, after its cells have drawn.
	 *
	 * It has to be done here rather than in TileCell because the outline goes *around*
	 * the tiles, in the gutter between them — space that belongs to this panel and
	 * that no cell can paint into. Drawing it inside the cells instead put the line on
	 * top of the artwork and made two adjacent regions share one doubled edge.
	 */
	private final JPanel grid = new JPanel()
	{
		@Override
		protected void paintChildren(Graphics g)
		{
			super.paintChildren(g);
			paintRegionOutlines(g);
		}

		/**
		 * Height derived from the width this actually got, not from a constant.
		 *
		 * GRID_WIDTH assumes the panel's full 225px less padding and a scrollbar, but
		 * the width handed out depends on whether that scrollbar is showing. Pinning
		 * the grid to the assumption left it narrower than the wells beneath it, with
		 * the shortfall showing as dead space down the right-hand side. GridLayout
		 * already divides whatever width it is given; only the height has to follow,
		 * or the cells stop being square.
		 */
		@Override
		public Dimension getPreferredSize()
		{
			final int w = getWidth() > 0 ? getWidth() : GRID_WIDTH;
			return new Dimension(w, gridHeightFor(w));
		}

		@Override
		public Dimension getMaximumSize()
		{
			// Unbounded width so BoxLayout stretches it to the viewport instead of
			// leaving it at its preferred size and aligning it left.
			return gridCols <= 0
				? super.getMaximumSize()
				: new Dimension(Integer.MAX_VALUE, gridHeightFor(getWidth() > 0 ? getWidth() : GRID_WIDTH));
		}
	};

	/** Board shape currently laid out, for the sizing above. 0 when empty. */
	private int gridCols;
	private int gridRows;

	/** The square-cell height implied by a given grid width. */
	private int gridHeightFor(int width)
	{
		if (gridCols <= 0 || gridRows <= 0)
		{
			return 0;
		}
		final int inner = width - (REGION_PAD * 2);
		final int cell = Math.max(8, (inner - (gridCols - 1) * CELL_GAP) / gridCols);
		return cell * gridRows + (gridRows - 1) * CELL_GAP + (REGION_PAD * 2);
	}

	/** The board currently drawn in {@link #grid}, for its region painting. */
	private BoardModels.Board gridBoard;

	/**
	 * Empty the board and let it collapse again.
	 *
	 * buildBoard() pins the grid's size to keep its cells square, so clearing it
	 * without releasing that would leave an empty grid still holding a board's worth
	 * of space. Dropping the board reference with it also stops the region painter
	 * drawing against a layout that is no longer there.
	 */
	private void clearGrid()
	{
		gridBoard = null;
		gridCols = 0;
		gridRows = 0;
		grid.removeAll();
		grid.setPreferredSize(null);
		grid.setMaximumSize(null);
		grid.setBorder(null);
	}

	/**
	 * Region perimeter stroke. One pixel, because two of them have to fit side by
	 * side in a {@link #CELL_GAP}-wide gutter without touching.
	 */
	private static final int REGION_EDGE = 1;

	/**
	 * How far outside its own cells a region draws its perimeter.
	 *
	 * Each region hugs its own tiles rather than centring the line in the shared
	 * gutter. Centred, two neighbouring regions computed the same coordinates and
	 * painted over each other: only the second colour survived, and at 2px the
	 * stroke bled onto both cells so the boundary looked like one thick line of
	 * indeterminate owner. Hugging leaves a clear pixel between them, so a shared
	 * border reads as two lines — one per region, each in its own colour.
	 */
	private static final int REGION_INSET = 1;

	/** Margin around the grid so an edge tile's outline has somewhere to sit. */
	private static final int REGION_PAD = 3;

	/**
	 * Each region's perimeter, drawn in the gutters around its tiles.
	 *
	 * A side is drawn only where the neighbouring square holds a different region, so
	 * a group of tiles reads as one enclosed area rather than a set of boxed ones. The
	 * line sits in the gap just outside its own cells, which is why it surrounds the
	 * tiles instead of sitting on their artwork — and why adjacent cells of the same
	 * region produce no line at all between them.
	 */
	private void paintRegionOutlines(Graphics graphics)
	{
		final BoardModels.Board b = gridBoard;
		if (b == null || !b.hasRegions())
		{
			return;
		}

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			// Off: these are axis-aligned hairlines, and antialiasing only blurs them.
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
			g.setStroke(new java.awt.BasicStroke(REGION_EDGE));

			final int cols = Math.max(1, b.cols);
			final int rows = Math.max(1, b.rows);
			final int o = REGION_INSET;

			for (int i = 0; i < grid.getComponentCount(); i++)
			{
				final java.awt.Component comp = grid.getComponent(i);
				if (!(comp instanceof TileCell))
				{
					continue;
				}
				final BoardModels.BoardTile t = ((TileCell) comp).tile();
				final int idx = b.regionIndex(t.region);
				if (idx < 0)
				{
					continue;
				}

				final java.awt.Rectangle r = comp.getBounds();
				final int row = (t.pos - 1) / cols;
				final int col = (t.pos - 1) % cols;
				final int x1 = r.x - o;
				final int y1 = r.y - o;
				final int x2 = r.x + r.width + o - 1;
				final int y2 = r.y + r.height + o - 1;

				final boolean up = sameRegion(b, t.region, row - 1, col, rows, cols);
				final boolean down = sameRegion(b, t.region, row + 1, col, rows, cols);
				final boolean left = sameRegion(b, t.region, row, col - 1, rows, cols);
				final boolean right = sameRegion(b, t.region, row, col + 1, rows, cols);

				// Reach across the gutter towards neighbours in the same region, and
				// stop short of ones in another. Hugging its own cells leaves each edge
				// ending REGION_INSET short of the gutter's far side, so two tiles in
				// one region left an unpainted pixel between their edges and the
				// perimeter came out dashed. Extending only towards its own kind keeps
				// that pixel from being claimed where two regions meet.
				final int reach = Math.max(0, CELL_GAP - (REGION_INSET * 2));
				final int ex1 = x1 - (left ? reach : 0);
				final int ex2 = x2 + (right ? reach : 0);
				final int ey1 = y1 - (up ? reach : 0);
				final int ey2 = y2 + (down ? reach : 0);

				g.setColor(Brand.regionColor(idx));
				if (!up) g.drawLine(ex1, y1, ex2, y1);
				if (!down) g.drawLine(ex1, y2, ex2, y2);
				if (!left) g.drawLine(x1, ey1, x1, ey2);
				if (!right) g.drawLine(x2, ey1, x2, ey2);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/** Whether the square at this row/col carries the region named. */
	private static boolean sameRegion(BoardModels.Board b, String region, int row, int col,
		int rows, int cols)
	{
		if (row < 0 || row >= rows || col < 0 || col >= cols)
		{
			return false;
		}
		return region != null && !region.isEmpty()
			&& region.equals(b.regionAt(row * cols + col + 1));
	}
	private final JLabel countdown = new JLabel();
	/**
	 * Shown next to the event name, but only when the site itself would show it —
	 * plugin_board.php applies event.html's own hide/release rules before sending it,
	 * so an event still withholding its codeword sends nothing and this stays hidden.
	 */
	private final JLabel codewordLabel = new JLabel();

	/** Says why a board has no tiles on it, when that is deliberate. */
	private final JLabel hiddenNotice = new JLabel();

	/**
	 * Everything below is rebuilt by {@link #buildUi()} on a theme change: these
	 * components bake the palette in when they are created, so they are recreated
	 * rather than recoloured. The panel object itself never changes, which is what
	 * keeps the sidebar open.
	 */
	private JLabel standingsHeading;
	private JPanel standings;
	private JLabel rosterHeading;
	private JLabel pointsHeading;
	private JPanel pointsWell;
	private JPanel pointsBreakdown;
	private JPanel rosterWell;
	private JPanel roster;
	private JLabel themeHeading;

	/** Populated from the site, so a theme added there needs no plugin change. */
	private final JComboBox<BoardModels.Theme> themeBox = new JComboBox<>();

	/**
	 * The events a linked account belongs to. Hidden entirely until an account token
	 * is set, because without one the plugin has no idea who is playing and the event
	 * code in settings is the only way in.
	 */
	private JLabel eventHeading;
	private final JComboBox<BoardModels.EventSummary> eventBox = new JComboBox<>();

	/**
	 * The logged-in character, once the client reports one. Used to pick the team you
	 * are actually on and to mark you in the roster — the one thing the panel knows
	 * that the website cannot.
	 */
	private String localPlayer;
	private final CardLayout cards = new CardLayout();
	private JPanel deck;
	private TileDetailPanel detail;
	/** Held so opening a tile can rewind it to the top. */
	private JScrollPane detailScroll;

	private BoardModels.Board current;
	/** Guards the team dropdown's listener while we repopulate it. */
	private boolean populating;
	/**
	 * Which tile the detail view is showing, or null when the grid is up. The
	 * refresh timer uses this to redraw an open tile in place instead of throwing
	 * the reader back to the board every minute.
	 */
	private Integer openTilePos;

	/**
	 * @param siteUrl the address every request goes to. Always
	 *                {@link RsBingoConfig#SITE_URL} in the client; a parameter only so
	 *                the preview harness can render against a local copy of the site.
	 */
	RsBingoPanel(RsBingoApi api, TileImageCache images, RsBingoConfig config, String siteUrl,
				 Runnable onEventCodeChanged, Consumer<String> onTeamSelected,
				 Consumer<BoardModels.Theme> onThemeSelected, Consumer<String> onEventSelected,
				 Consumer<BoardModels.Board> onBoardLoaded,
				 ScreenshotSource screenshots)
	{
		super(false);
		this.api = api;
		this.images = images;
		this.config = config;
		this.siteUrl = siteUrl;
		this.onEventCodeChanged = onEventCodeChanged;
		this.onTeamSelected = onTeamSelected;
		this.onThemeSelected = onThemeSelected;
		this.onEventSelected = onEventSelected;
		this.onBoardLoaded = onBoardLoaded;
		this.screenshots = screenshots;

		// Listeners are attached once, here. buildUi() runs again on every theme
		// change and must not add a second copy of any of them.
		teamBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.TeamSummary sel = (BoardModels.TeamSummary) teamBox.getSelectedItem();
			if (sel != null && sel.name != null)
			{
				// A deliberate team switch starts at the board, not on whichever tile
				// happened to be open for the previous team.
				openTilePos = null;
				onTeamSelected.accept(sel.name);
				loadTeam(sel.name);
			}
		});

		eventBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.EventSummary sel = (BoardModels.EventSummary) eventBox.getSelectedItem();
			if (sel != null && sel.eventId != null && !sel.eventId.equalsIgnoreCase(eventCode()))
			{
				// Switching events invalidates the team saved for the previous one;
				// preferredTeam() falls back to the player's own team or the leader.
				openTilePos = null;
				onEventSelected.accept(sel.eventId);
			}
		});

		themeBox.addActionListener(e ->
		{
			if (populating)
			{
				return;
			}
			final BoardModels.Theme sel = (BoardModels.Theme) themeBox.getSelectedItem();
			if (sel != null && sel.key != null && !sel.key.equals(config.theme()))
			{
				onThemeSelected.accept(sel);
			}
		});

		buildUi();
	}

	/**
	 * Builds the panel's contents from the current palette.
	 *
	 * Called again whenever the theme changes. Swapping the whole panel out from
	 * under the navigation button worked, but collapsed the sidebar every time —
	 * rebuilding in place keeps the button, and the panel, exactly where they are.
	 */
	private void buildUi()
	{
		removeAll();

		setLayout(new BorderLayout());
		setBackground(Brand.BG_TILE);
		setBorder(BorderFactory.createEmptyBorder(6, Brand.PAD, 6, Brand.PAD));

		// ── controls ────────────────────────────────────────────────────────
		final JPanel controls = new JPanel();
		controls.setLayout(new BoxLayout(controls, BoxLayout.Y_AXIS));
		controls.setBackground(Brand.BG_TILE);

		// Your own events first: this is the fastest way in when an account is linked.
		eventHeading = Brand.sectionLabel("Event");
		styleCombo(eventBox);
		final boolean haveEvents = eventBox.getItemCount() > 0;
		eventHeading.setVisible(haveEvents);
		eventBox.setVisible(haveEvents);

		// Theme second: it is the one control that changes everything below it.
		themeHeading = Brand.sectionLabel("Theme");
		styleCombo(themeBox);
		final boolean haveThemes = themeBox.getItemCount() > 0;
		themeHeading.setVisible(haveThemes);
		themeBox.setVisible(haveThemes);

		final JLabel teamLabel = Brand.sectionLabel("Team");
		styleCombo(teamBox);

		headerLabel.setFont(Brand.bold(14f));
		headerLabel.setForeground(Brand.TEXT_BRIGHT);
		headerLabel.setBorder(BorderFactory.createEmptyBorder(12, 0, 0, 0));
		headerLabel.setLineWrap(true);
		headerLabel.setWrapStyleWord(true);
		headerLabel.setEditable(false);
		headerLabel.setFocusable(false);
		headerLabel.setOpaque(false);

		statusLabel.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));

		countdown.setFont(FontManager.getRunescapeSmallFont());
		countdown.setForeground(Brand.TEXT_MAIN);
		countdown.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));

		codewordLabel.setFont(FontManager.getRunescapeSmallFont());
		codewordLabel.setForeground(Brand.ACCENT);
		codewordLabel.setBorder(BorderFactory.createEmptyBorder(2, 0, 8, 0));

		hiddenNotice.setFont(FontManager.getRunescapeSmallFont());
		hiddenNotice.setForeground(Brand.TEXT_DIM);
		hiddenNotice.setBorder(BorderFactory.createEmptyBorder(2, 0, 6, 0));

		// BoxLayout lays children out around a shared alignment axis, so a mix of
		// LEFT and the JComponent default (CENTRE) makes it reserve space on both
		// sides and squeeze components. They all have to agree.
		for (JComponent c : new JComponent[]{eventHeading, eventBox, themeHeading, themeBox,
			teamLabel, teamBox, headerLabel, statusLabel, countdown, codewordLabel,
			hiddenNotice})
		{
			c.setAlignmentX(LEFT_ALIGNMENT);
			controls.add(c);
		}

		// ── board grid, then what the site shows around it ──────────────────
		grid.setBackground(Brand.BG_TILE);

		standingsHeading = Brand.sectionLabel("Standings");
		standings = Brand.section();
		rosterHeading = Brand.sectionLabel("Team");
		rosterWell = Brand.well();
		roster = Brand.section();
		rosterWell.add(roster);

		pointsHeading = Brand.sectionLabel("Points");
		pointsWell = Brand.well();
		pointsBreakdown = Brand.section();
		pointsWell.add(pointsBreakdown);

		final JPanel boardCard = new JPanel();
		boardCard.setLayout(new BoxLayout(boardCard, BoxLayout.Y_AXIS));
		boardCard.setBackground(Brand.BG_TILE);

		for (JComponent c : new JComponent[]{grid, standingsHeading, standings,
			rosterHeading, rosterWell, pointsHeading, pointsWell})
		{
			c.setAlignmentX(LEFT_ALIGNMENT);
			boardCard.add(c);
		}

		detail = new TileDetailPanel(images, config, siteUrl, submitter, this::closeTile);
		detailScroll = scrolling(detail);

		deck = new JPanel(cards);
		deck.setBackground(Brand.BG_TILE);
		// Both cards scroll: a 7x7 board and a long item checklist each outrun the
		// panel's height, and PluginPanel(false) provides no scrolling of its own.
		deck.add(scrolling(boardCard), CARD_BOARD);
		deck.add(detailScroll, CARD_TILE);

		add(controls, BorderLayout.NORTH);
		add(deck, BorderLayout.CENTER);

		cards.show(deck, CARD_BOARD);
	}

	/**
	 * Files submissions on behalf of the tile view.
	 *
	 * Gating lives here because this is what knows the roster: the logged-in
	 * character must be on the team currently being viewed. Viewing another team's
	 * board offers no submit controls at all, since a submission is recorded against
	 * a team and filing one for a team you are not on would simply be wrong.
	 */
	private final TileDetailPanel.Submitter submitter = new TileDetailPanel.Submitter()
	{
		@Override
		public String submittingAs()
		{
			if (localPlayer == null || current == null || current.team == null)
			{
				return null;
			}
			final BoardModels.TeamSummary team = teamNamed(current, current.team);
			if (team == null)
			{
				return null;
			}
			for (String player : team.players)
			{
				if (localPlayer.equalsIgnoreCase(player))
				{
					// Return the roster's spelling: submit_item.php matches it exactly.
					return player;
				}
			}
			return null;
		}

		@Override
		public boolean canSubmit()
		{
			// Being on the team is the whole authorisation. The codeword is only
			// stamped onto the screenshot, so a withheld one must not block anyone.
			return submittingAs() != null;
		}

		@Override
		public void submit(BoardModels.BoardTile tile, BoardModels.SubmitOption option,
						   Consumer<String> onStatus)
		{
			final String as = submittingAs();
			if (as == null || current == null)
			{
				onStatus.accept("You are not on this team.");
				return;
			}

			// The frame arrives on the client thread; everything after it is network
			// work, and the status callback has to land back on the EDT.
			screenshots.capture(frame ->
			{
				final byte[] png = ProofShot.stamp(frame, current.name, codeword(), as, option.label);
				if (png == null)
				{
					SwingUtilities.invokeLater(() -> onStatus.accept("Could not capture the screen."));
					return;
				}

				SwingUtilities.invokeLater(() -> onStatus.accept("Uploading…"));
				api.submitItem(siteUrl, current.eventId,
					current.team, as, tile.pos, tile.id, option, png,
					() -> SwingUtilities.invokeLater(() ->
					{
						onStatus.accept("Submitted - awaiting review.");
						// Pull the board back so the item shows its pending "?" at once.
						refreshCurrentTeam();
					}),
					error -> SwingUtilities.invokeLater(() -> onStatus.accept(error)));
			});
		}
	};

	/** The event's codeword, once the site has released it. */
	private String codeword()
	{
		if (current == null || current.codeword == null || current.codeword.trim().isEmpty())
		{
			return null;
		}
		return current.codeword.trim();
	}

	private static void styleCombo(JComboBox<?> box)
	{
		box.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		box.setBackground(Brand.BG_WELL);
		box.setForeground(Brand.TEXT_BRIGHT);
		box.setFont(FontManager.getRunescapeSmallFont());
	}

	/**
	 * Repaints the panel in the newly applied palette and redraws whatever it was
	 * showing, so a theme change costs no network round trip.
	 */
	void reskin()
	{
		SwingUtilities.invokeLater(() ->
		{
			final BoardModels.Board showing = current;
			buildUi();
			revalidate();
			repaint();

			if (showing == null)
			{
				return;
			}

			// A board with no team is the event summary: teams and standings, no
			// tiles. Redrawing that through showBoard paints an empty grid and
			// "0/0 tiles" over whatever was there. It happens on first open, where
			// the themes arrive between the summary and the team's board, and it
			// used to stick, because the refresh timer had no team to re-fetch.
			// Going back through showEvent picks a team and asks for its board.
			if (showing.team == null)
			{
				showEvent(showing);
				return;
			}

			showBoard(showing);
		});
	}

	private static JScrollPane scrolling(JComponent content)
	{
		final JScrollPane sp = new JScrollPane(new VerticalContent(content),
			ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED,
			ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		sp.setBorder(BorderFactory.createEmptyBorder());
		sp.getViewport().setBackground(Brand.BG_TILE);
		sp.setBackground(Brand.BG_TILE);
		sp.getVerticalScrollBar().setUnitIncrement(16);
		sp.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return sp;
	}

	/**
	 * Scrolled content that takes the viewport's width instead of its own preferred
	 * width.
	 *
	 * Without this a plain panel keeps whatever width its widest child asked for,
	 * and since there is no horizontal scrollbar the overflow is simply cut off —
	 * tag lists and descriptions lost their right-hand edge mid-word.
	 */
	private static class VerticalContent extends JPanel implements Scrollable
	{
		VerticalContent(JComponent view)
		{
			setLayout(new BorderLayout());
			setBackground(Brand.BG_TILE);
			// NORTH, so content keeps its natural height and scrolls rather than
			// being stretched down the panel.
			add(view, BorderLayout.NORTH);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visible, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visible, int orientation, int direction)
		{
			return visible.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}

	/**
	 * The event being viewed. Read from the config rather than a field in the panel:
	 * the code is a setting, not board data, and having it in both places meant the
	 * panel's copy could overwrite one typed into RuneLite's settings.
	 */
	private String eventCode()
	{
		final String code = config.eventCode();
		return code == null ? "" : code.trim().toUpperCase();
	}

	void setStatus(String text)
	{
		SwingUtilities.invokeLater(() -> Brand.setWrapped(statusLabel, text == null ? "" : text));
	}

	/** Event summary + team list; selects a team and loads its board. */
	void showEvent(BoardModels.Board board)
	{
		SwingUtilities.invokeLater(() ->
		{
			current = board;
			openTilePos = null;
			onBoardLoaded.accept(board);
			headerLabel.setText(board.name == null ? "" : board.name);
			Brand.setWrapped(statusLabel, board.teams.size() + (board.teams.size() == 1 ? " team" : " teams"));

			populating = true;
			teamBox.removeAllItems();
			for (BoardModels.TeamSummary t : board.teams)
			{
				teamBox.addItem(t);
			}

			// Prefer the team last viewed, so reopening the client lands where you
			// left off rather than on whoever is top of the table today.
			final BoardModels.TeamSummary preferred = preferredTeam(board);
			if (preferred != null)
			{
				teamBox.setSelectedItem(preferred);
			}
			populating = false;

			buildStandings(board, preferred == null ? null : preferred.name);
			buildRoster(preferred);
			buildPoints(null);
			applyCountdown(board);

			clearGrid();
			grid.revalidate();
			grid.repaint();
			cards.show(deck, CARD_BOARD);

			if (preferred != null && preferred.name != null)
			{
				loadTeam(preferred.name);
			}
		});
	}

	/** Every team, ranked, with the one being viewed picked out. */
	private void buildStandings(BoardModels.Board board, String viewing)
	{
		standings.removeAll();
		final boolean any = !board.teams.isEmpty();
		standingsHeading.setVisible(any);
		standings.setVisible(any);

		int rank = 0;
		for (BoardModels.TeamSummary team : board.teams)
		{
			rank++;
			final boolean mine = team.name != null && team.name.equalsIgnoreCase(viewing);
			standings.add(Brand.valueRow(
				rank + ". " + (team.name == null ? "" : team.name),
				String.valueOf(team.points),
				mine ? Brand.TEXT_BRIGHT : Brand.TEXT_DIM,
				mine ? Brand.ACCENT : Brand.TEXT_MAIN,
				mine ? Brand.BG_COMPLETED_WELL : Brand.BG_WELL));
			standings.add(Box.createVerticalStrut(2));
		}
	}

	/**
	 * Where the team's total came from, itemised as the website's points tooltip
	 * does it: tile points, each line bonus that applies, the collection-log bonus,
	 * a total, then the per-tile contributions.
	 *
	 * The server sends this already summed and sorted, so nothing here re-derives a
	 * number that appears elsewhere in the panel.
	 */
	private void buildPoints(BoardModels.Points points)
	{
		pointsBreakdown.removeAll();

		final boolean any = points != null;
		pointsHeading.setVisible(any);
		pointsWell.setVisible(any);
		if (!any)
		{
			return;
		}

		pointsBreakdown.add(pointsRow("Tile pts", Text.thousands(points.tilePts), false));

		// Off Showdown the site names the count of completed lines rather than a flat
		// bonus, because two completed rows pay twice.
		if (points.rowPts != 0)
		{
			pointsBreakdown.add(pointsRow(points.isShowdown ? "Row bonus" : "Rows (x" + points.rows + ")",
				"+" + Text.thousands(points.rowPts), false));
		}
		if (points.colPts != 0)
		{
			pointsBreakdown.add(pointsRow(points.isShowdown ? "Col bonus" : "Cols (x" + points.cols + ")",
				"+" + Text.thousands(points.colPts), false));
		}
		if (points.diagPts != 0)
		{
			pointsBreakdown.add(pointsRow(points.isShowdown ? "Diag bonus" : "Diags (x" + points.diags + ")",
				"+" + Text.thousands(points.diagPts), false));
		}
		if (points.clogPts != 0)
		{
			pointsBreakdown.add(pointsRow("Coll. Log", "+" + Text.thousands(points.clogPts), false));
		}

		// The site prints a total only when something was added to the tile points;
		// otherwise the total is the line above it and says nothing new.
		if (points.hasBonuses())
		{
			pointsBreakdown.add(Box.createVerticalStrut(2));
			pointsBreakdown.add(pointsRow("Total", Text.thousands(points.total), true));
		}

		if (!points.tiles.isEmpty())
		{
			pointsBreakdown.add(Box.createVerticalStrut(6));
			final JLabel caption = new JLabel("Tile breakdown");
			caption.setFont(FontManager.getRunescapeSmallFont());
			caption.setForeground(Brand.TEXT_DIM);
			caption.setAlignmentX(LEFT_ALIGNMENT);
			caption.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
			pointsBreakdown.add(caption);

			for (BoardModels.PointsTile tile : points.tiles)
			{
				pointsBreakdown.add(Brand.valueRow(
					tile.label == null ? "" : tile.label,
					Text.thousands(tile.pts),
					Brand.TEXT_DIM, Brand.TEXT_MAIN, null));
			}
		}
	}

	private JPanel pointsRow(String label, String value, boolean total)
	{
		return Brand.valueRow(label, value,
			total ? Brand.TEXT_BRIGHT : Brand.TEXT_MAIN,
			total ? Brand.TEXT_BRIGHT : Brand.ACCENT,
			null);
	}

	/** Who is on the selected team, with the logged-in character marked. */
	private void buildRoster(BoardModels.TeamSummary team)
	{
		roster.removeAll();
		final boolean any = team != null && !team.players.isEmpty();
		rosterHeading.setVisible(any);
		rosterWell.setVisible(any);

		if (!any)
		{
			return;
		}

		rosterHeading.setText(("Team (" + team.players.size() + ")").toUpperCase());

		for (String player : team.players)
		{
			final boolean isMe = localPlayer != null && localPlayer.equalsIgnoreCase(player);

			// Marked with a filled row rather than by colour alone. The accent is not
			// reliably brighter than the body text: on Slate the text is near-white
			// (#dcddde) and the accent is a mid blue (#7289da), so the highlighted
			// name came out *dimmer* than everyone else's. A background reads as
			// "this one" whatever hue a theme picks.
			final JTextArea row = Brand.wrapping(FontManager.getRunescapeSmallFont(),
				isMe ? Brand.TEXT_BRIGHT : Brand.TEXT_MAIN);
			Brand.setWrapped(row, isMe ? (player + "  (you)") : player);

			// Same padding on every row, so the highlighted one does not shift.
			row.setBorder(BorderFactory.createEmptyBorder(2, 4, 2, 4));
			if (isMe)
			{
				row.setOpaque(true);
				row.setBackground(Brand.blend(Brand.BG_WELL, Brand.ACCENT, 0.28f));
			}
			roster.add(row);
		}
	}

	private void applyCountdown(BoardModels.Board board)
	{
		final String text = Text.eventCountdown(board.startDate, board.endDate, java.time.Instant.now());
		countdown.setVisible(text != null);
		countdown.setText(text == null ? "" : text);

		final boolean hasCodeword = board.codeword != null && !board.codeword.trim().isEmpty();
		codewordLabel.setVisible(hasCodeword);
		codewordLabel.setText(hasCodeword ? ("Codeword: " + board.codeword.trim()) : "");

		applyHiddenNotice(board);
	}

	/**
	 * Says a blank board is blank on purpose.
	 *
	 * An event can withhold tile names, artwork and checklists until shortly before
	 * it starts. Left unexplained that looks exactly like a board that failed to
	 * load, which is how it was first reported.
	 */
	private void applyHiddenNotice(BoardModels.Board board)
	{
		if (!board.hiddenTiles)
		{
			hiddenNotice.setVisible(false);
			hiddenNotice.setText("");
			return;
		}

		final String when = Text.untilRelease(board.tilesReleaseAt, java.time.Instant.now());
		hiddenNotice.setVisible(true);
		hiddenNotice.setText(when == null
			? "Tiles hidden by the organiser"
			: ("Tiles hidden - revealed in " + when));
	}

	private static BoardModels.TeamSummary teamNamed(BoardModels.Board board, String name)
	{
		for (BoardModels.TeamSummary t : board.teams)
		{
			if (t.name != null && t.name.equalsIgnoreCase(name))
			{
				return t;
			}
		}
		return null;
	}

	/**
	 * Offers the linked account's events in the panel's dropdown, selecting whichever
	 * one is currently loaded. Hidden when the account has no events, rather than
	 * showing an empty control.
	 */
	void setMyEvents(BoardModels.EventList list)
	{
		SwingUtilities.invokeLater(() ->
		{
			populating = true;
			eventBox.removeAllItems();

			final String loaded = eventCode();
			for (BoardModels.EventSummary event : list.events)
			{
				eventBox.addItem(event);
				if (event.eventId != null && event.eventId.equalsIgnoreCase(loaded))
				{
					eventBox.setSelectedItem(event);
				}
			}
			// Nothing loaded yet: open the first event rather than asking for a code
			// the dropdown is already holding. Linking an account is meant to replace
			// typing codes, and an empty board next to a full list of your own events
			// is the plugin withholding something it plainly has.
			BoardModels.EventSummary autoSelect = null;
			if ((loaded == null || loaded.trim().isEmpty()) && !list.events.isEmpty())
			{
				autoSelect = list.events.get(0);
				eventBox.setSelectedItem(autoSelect);
			}
			populating = false;

			final boolean any = eventBox.getItemCount() > 0;
			eventHeading.setVisible(any);
			eventBox.setVisible(any);
			revalidate();
			repaint();

			// Outside the populating guard: this writes the code to the config, which
			// is what actually loads the board.
			if (autoSelect != null && autoSelect.eventId != null)
			{
				onEventSelected.accept(autoSelect.eventId);
			}
		});
	}

	/**
	 * Offers the site's themes in the panel's dropdown, selecting the saved one.
	 * Called once the list arrives; until then the switcher stays hidden rather than
	 * showing an empty control.
	 */
	void setThemes(BoardModels.ThemeList list)
	{
		SwingUtilities.invokeLater(() ->
		{
			populating = true;
			themeBox.removeAllItems();

			final String saved = config.theme() == null || config.theme().isEmpty()
				? list.defaultKey
				: config.theme();

			for (BoardModels.Theme theme : list.themes)
			{
				themeBox.addItem(theme);
				if (theme.key != null && theme.key.equals(saved))
				{
					themeBox.setSelectedItem(theme);
				}
			}
			populating = false;

			final boolean any = themeBox.getItemCount() > 0;
			themeHeading.setVisible(any);
			themeBox.setVisible(any);
		});
	}

	/**
	 * Tells the panel which character is logged in, so it can pick that player's team
	 * and mark them in the roster. Safe to call before a board has loaded.
	 */
	void setLocalPlayer(String name)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (name == null || name.equals(localPlayer))
			{
				return;
			}
			localPlayer = name;

			// Redraw everything this feeds, not just the roster: the name decides
			// whether the open tile offers submit controls, and it usually arrives a
			// tick or two after a board is already on screen. No refetch — this
			// redraws the board already held.
			if (current != null)
			{
				showBoard(current);
			}
		});
	}

	private BoardModels.TeamSummary preferredTeam(BoardModels.Board board)
	{
		if (board.teams.isEmpty())
		{
			return null;
		}

		// An explicit choice wins; it is the one thing the user actually asked for.
		final String saved = config.selectedTeam() == null ? "" : config.selectedTeam().trim();
		if (!saved.isEmpty())
		{
			final BoardModels.TeamSummary chosen = teamNamed(board, saved);
			if (chosen != null)
			{
				return chosen;
			}
		}

		// Otherwise the team the logged-in character is actually on, which is almost
		// always the one they want and saves them hunting through the dropdown.
		if (localPlayer != null)
		{
			for (BoardModels.TeamSummary t : board.teams)
			{
				for (String player : t.players)
				{
					if (localPlayer.equalsIgnoreCase(player))
					{
						return t;
					}
				}
			}
		}

		return board.teams.get(0);
	}

	/** A team's board. */
	void showBoard(BoardModels.Board board)
	{
		SwingUtilities.invokeLater(() ->
		{
			current = board;
			onBoardLoaded.accept(board);

			int pts = 0;
			for (BoardModels.TeamSummary t : board.teams)
			{
				if (t.name != null && t.name.equals(board.team))
				{
					pts = t.points;
					break;
				}
			}

			int done = 0;
			int placed = 0;
			for (BoardModels.BoardTile t : board.board)
			{
				if (t.empty)
				{
					continue;
				}
				placed++;
				if (t.done)
				{
					done++;
				}
			}
			Brand.setWrapped(statusLabel, pts + " pts  ·  " + done + "/" + placed + " tiles");
			applyCountdown(board);
			buildStandings(board, board.team);
			buildRoster(teamNamed(board, board.team));
			buildPoints(board.points);

			final int cols = Math.max(1, board.cols);
			final int rows = Math.max(1, board.rows);

			// Square cells at any board size.
			//
			// GridLayout ignores a child's preferred size and simply divides the space
			// it is given, so a cell is only square if the panel's height matches what
			// its width implies. That used to be left to chance: the cell size carried a
			// 24px floor, and on a 9x9 board the floor made the grid want 240px of
			// height inside 209px of width, which GridLayout resolved as 20x24 cells.
			// Deriving the height from the width that will actually be used keeps every
			// board square, at the cost of small cells on the largest ones — which is
			// unavoidable in a 225px panel.
			gridBoard = board;
			gridCols = cols;
			gridRows = rows;
			grid.removeAll();
			grid.setLayout(new GridLayout(0, cols, CELL_GAP, CELL_GAP));
			// Room for a region outline on an edge tile, which sits outside the cell.
			grid.setBorder(BorderFactory.createEmptyBorder(REGION_PAD, REGION_PAD, REGION_PAD, REGION_PAD));
			// Sizes come from the overrides on the field; setting them here would pin
			// the grid to a width it may not be given.
			grid.setPreferredSize(null);
			grid.setMaximumSize(null);

			// Only a hint for the cells' preferred size — GridLayout divides the real
			// width among them regardless, which is what lets the grid stretch.
			final int cell = Math.max(8,
				((GRID_WIDTH - (REGION_PAD * 2)) - (cols - 1) * CELL_GAP) / cols);
			for (BoardModels.BoardTile tile : board.board)
			{
				grid.add(new TileCell(tile, board, images, config, siteUrl, cell,
					() -> openTile(tile, board)));
			}
			grid.revalidate();
			grid.repaint();

			// A refresh landing while a tile is open should update that tile, not
			// yank the reader back to the grid.
			final BoardModels.BoardTile open = findTile(board, openTilePos);
			if (open != null)
			{
				detail.show(open, board);

				// Show the card as well as filling it. On a refresh the tile card is
				// already up so this changes nothing, but a theme change rebuilds the
				// deck from scratch and it comes back showing the board — the detail
				// was being updated behind a grid the reader had not asked for.
				cards.show(deck, CARD_TILE);
			}
			else
			{
				openTilePos = null;
				cards.show(deck, CARD_BOARD);
			}
		});
	}

	private static BoardModels.BoardTile findTile(BoardModels.Board board, Integer pos)
	{
		if (pos == null)
		{
			return null;
		}
		for (BoardModels.BoardTile t : board.board)
		{
			if (t.pos == pos && !t.empty)
			{
				return t;
			}
		}
		return null;
	}

	private void openTile(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		openTilePos = tile.pos;
		detail.show(tile, board);
		cards.show(deck, CARD_TILE);

		// A newly opened tile starts at its title, not wherever the last one was left.
		// Deferred so it runs after the swapped-in card has been laid out.
		SwingUtilities.invokeLater(() -> detailScroll.getVerticalScrollBar().setValue(0));

		// The board fetch carries no per-player breakdown, so ask for this tile's now
		// that it is open. showBoard() redraws the open tile in place when it lands,
		// which is the same path the refresh timer uses.
		if (board.team != null && !tile.rates.isEmpty() && tile.players.isEmpty())
		{
			loadTeam(board.team);
		}
	}

	private void closeTile()
	{
		openTilePos = null;
		cards.show(deck, CARD_BOARD);
	}

	private void loadTeam(String team)
	{
		final String code = eventCode();
		if (code.isEmpty())
		{
			return;
		}
		setStatus("Loading " + team + "…");
		// Ask for the open tile's player breakdown in the same request. The server
		// only sends it for this one tile, which is what keeps the response small.
		api.fetchBoard(siteUrl, code, team, openTilePos == null ? 0 : openTilePos,
			this::showBoard, this::setStatus);
	}

	/** Re-fetch the team currently selected, if any. Used by the refresh timer. */
	void refreshCurrentTeam()
	{
		if (current == null)
		{
			return;
		}

		// Falls back to the dropdown when what is loaded is the event summary, which
		// carries no team. Without this the timer gave up on exactly the state it
		// most needed to repair, and the panel sat empty until a team was picked by
		// hand.
		String team = current.team;
		if (team == null)
		{
			final BoardModels.TeamSummary selected = (BoardModels.TeamSummary) teamBox.getSelectedItem();
			team = selected == null ? null : selected.name;
		}

		if (team != null && !team.isEmpty())
		{
			loadTeam(team);
		}
	}

	void clearBoard()
	{
		SwingUtilities.invokeLater(() ->
		{
			current = null;
			openTilePos = null;
			headerLabel.setText("");
			populating = true;
			teamBox.removeAllItems();
			populating = false;
			clearGrid();
			grid.revalidate();
			grid.repaint();
			cards.show(deck, CARD_BOARD);
		});
	}
}

package com.rsbingo;

import com.google.inject.Provides;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.api.ChatMessageType;
import net.runelite.api.MessageNode;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import java.awt.image.BufferedImage;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import javax.swing.SwingUtilities;

@Slf4j
@PluginDescriptor(
	name = "RS-Bingo",
	description = "Follow an rs-bingo.com bingo event: your team's board, tile progress and standings, with optional in-client submissions",
	tags = {"bingo", "clan", "event", "board"}
)
public class RsBingoPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private RsBingoConfig config;

	@Inject
	private RsBingoApi api;

	@Inject
	private TileImageCache images;

	@Inject
	private TeamChatIcons chatIcons;

	@Inject
	private TeamOverheadOverlay overheadOverlay;

	@Inject
	private net.runelite.client.ui.overlay.OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private net.runelite.client.ui.DrawManager drawManager;

	/** Message types that carry another player's name. */
	/**
	 * Message types where a participant is named inside the text rather than in the
	 * name field — drop and loot broadcasts, and the clan's own announcements.
	 */
	private static final java.util.Set<ChatMessageType> BROADCASTS =
		java.util.Collections.unmodifiableSet(java.util.EnumSet.of(
			ChatMessageType.CLAN_MESSAGE,
			ChatMessageType.CLAN_GUEST_MESSAGE,
			ChatMessageType.CLAN_GIM_MESSAGE,
			ChatMessageType.FRIENDSCHATNOTIFICATION,
			ChatMessageType.BROADCAST));

	private static final java.util.Set<ChatMessageType> PLAYER_CHAT =
		java.util.Collections.unmodifiableSet(java.util.EnumSet.of(
			ChatMessageType.PUBLICCHAT,
			ChatMessageType.MODCHAT,
			ChatMessageType.AUTOTYPER,
			ChatMessageType.MODAUTOTYPER,
			ChatMessageType.FRIENDSCHAT,
			ChatMessageType.CLAN_CHAT,
			ChatMessageType.CLAN_GUEST_CHAT,
			ChatMessageType.CLAN_GIM_CHAT,
			ChatMessageType.PRIVATECHAT,
			ChatMessageType.MODPRIVATECHAT));

	private RsBingoPanel panel;
	private NavigationButton navButton;
	/** Kept so a rebuilt panel can be handed these again without re-fetching. */
	private BoardModels.ThemeList themes;
	private BoardModels.EventList myEvents;
	/** The character already reported to the panel, so ticks don't re-report it. */
	private String knownPlayer;
	private ScheduledFuture<?> refreshTask;

	@Provides
	RsBingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RsBingoConfig.class);
	}

	@Override
	protected void startUp()
	{
		buildPanel();

		final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("RS-Bingo")
			.icon(icon)
			// Sidebar order: NavigationButton.COMPARATOR sorts on priority ascending
			// (then tooltip), so a lower number sits higher up.
			.priority(1)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navButton);
		overlayManager.add(overheadOverlay);

		loadThemes();
		loadMyEvents();

		if (!config.eventCode().trim().isEmpty())
		{
			loadEvent();
		}

		scheduleRefresh();
	}

	private void buildPanel()
	{
		panel = new RsBingoPanel(api, images, config, RsBingoConfig.SITE_URL,
			this::loadEvent, this::rememberTeam,
			this::applyTheme, this::switchEvent, chatIcons::setRoster,
			drawManager::requestNextFrameListener);
	}

	/**
	 * List the linked account's events in the panel. Silent when no token is set:
	 * linking is optional, and an event code alone still works.
	 */
	private void loadMyEvents()
	{
		final String token = config.accountToken();
		if (token == null || token.trim().isEmpty())
		{
			return;
		}

		api.fetchMyEvents(RsBingoConfig.SITE_URL, token,
			list ->
			{
				myEvents = list;
				if (panel != null)
				{
					panel.setMyEvents(list);
				}
			},
			error -> log.debug("rs-bingo event list: {}", error));
	}

	/** Load an event picked from the panel's dropdown, remembering it as the current one. */
	private void switchEvent(String eventId)
	{
		if (eventId == null || eventId.trim().isEmpty())
		{
			return;
		}
		// Writing the config is what makes the choice stick; the change handler then
		// loads it, so there is one path into "show me this event".
		configManager.setConfiguration(RsBingoConfig.GROUP, "eventCode", eventId.trim().toUpperCase());
	}

	/** Offer the site's themes in the panel, and re-apply the one already chosen. */
	private void loadThemes()
	{
		api.fetchThemes(RsBingoConfig.SITE_URL, list ->
		{
			themes = list;

			final String saved = config.theme();
			if (saved != null && !saved.isEmpty())
			{
				for (BoardModels.Theme theme : list.themes)
				{
					if (saved.equals(theme.key))
					{
						SwingUtilities.invokeLater(() -> repaintWithTheme(theme));
						break;
					}
				}
			}

			if (panel != null)
			{
				panel.setThemes(list);
			}
		});
	}

	/**
	 * Switch the panel to a theme and remember it.
	 *
	 * Components read the palette when they are created, so the panel rebuilds its
	 * contents rather than trying to recolour them in place: miss one and it keeps
	 * the old theme's colours, which looks like a bug rather than a stale pixel.
	 */
	private void applyTheme(BoardModels.Theme theme)
	{
		if (theme == null || theme.key == null)
		{
			return;
		}
		configManager.setConfiguration(RsBingoConfig.GROUP, "theme", theme.key);
		repaintWithTheme(theme);
	}

	private void repaintWithTheme(BoardModels.Theme theme)
	{
		Brand.applyPalette(theme.vars);

		// Rebuild the panel's contents, not the panel. Replacing it meant removing and
		// re-adding the navigation button, which collapsed the sidebar every time —
		// and re-opening it programmatically did not reliably put it back.
		if (panel != null)
		{
			panel.reskin();
		}
	}

	@Override
	protected void shutDown()
	{
		cancelRefresh();
		overlayManager.remove(overheadOverlay);
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	/**
	 * Forget the character on the way out, so switching accounts is picked up rather
	 * than leaving the previous one's name in place.
	 */
	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() != GameState.LOGGED_IN)
		{
			knownPlayer = null;
		}
	}

	/**
	 * Pick up the logged-in character, which decides whether the submit controls
	 * appear at all.
	 *
	 * Read on a tick rather than on GameState.LOGGED_IN: at the moment that event
	 * fires getLocalPlayer() is usually still null, so reading it there silently
	 * missed the name and left the panel thinking nobody was logged in. Guarded on
	 * knownPlayer so this costs one reference comparison per tick once settled.
	 */
	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (panel == null)
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			return;
		}

		final String name = local.getName();
		if (name == null || name.equals(knownPlayer))
		{
			return;
		}

		knownPlayer = name;
		panel.setLocalPlayer(name);
	}

	/**
	 * Marks event participants in chat with their team's colour.
	 *
	 * Two cases, and they differ in where the name is. A line someone types carries
	 * it in the message's name field; a drop or loot broadcast carries it inside the
	 * text instead, so the icon has to be placed in the message body.
	 *
	 * Both live in one method because RuneLite's event bus derives the event type
	 * from the method name — two subscribers for ChatMessage would both have to be
	 * called onChatMessage, and the plugin refuses to start.
	 *
	 * The client's own icons are kept either way: an ironman badge stays where it
	 * was and ours goes beside it.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		final MessageNode node = event.getMessageNode();
		if (node == null)
		{
			return;
		}

		boolean changed = false;

		if (config.chatTeamIcons() && PLAYER_CHAT.contains(event.getType()))
		{
			final String name = chatIcons.decorate(node.getName());
			if (name != null)
			{
				node.setName(name);
				changed = true;
			}
		}

		if (config.dropTeamIcons() && BROADCASTS.contains(event.getType()))
		{
			final String text = chatIcons.decorateBroadcast(node.getValue());
			if (text != null)
			{
				node.setValue(text);
				changed = true;
			}
		}

		if (changed)
		{
			// The line has already been laid out by the time this runs, so it has to
			// be redrawn for the change to appear.
			client.refreshChat();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!RsBingoConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("refreshSeconds".equals(event.getKey()))
		{
			scheduleRefresh();
			return;
		}

		if ("eventCode".equals(event.getKey()))
		{
			loadEvent();
			return;
		}

		// Pasting a token has to take effect immediately: the event list is the whole
		// point of linking, and making someone restart the client to see it reads as
		// the link having silently failed.
		if ("accountToken".equals(event.getKey()))
		{
			loadMyEvents();
			return;
		}

		// Toggling artwork only changes how the board draws, so redraw it rather than
		// starting the whole event over.
		if ("showTileImages".equals(event.getKey()) && panel != null)
		{
			panel.refreshCurrentTeam();
		}
	}

	/**
	 * Fetch the event summary and team list. The panel picks a team and asks for its
	 * board, so this is the single entry point for "start over".
	 *
	 * The code comes from the config, which is now the only place it lives — the
	 * panel used to carry its own copy and write it back, which fought with edits
	 * made in the settings pane.
	 */
	private void loadEvent()
	{
		if (panel == null)
		{
			return;
		}

		final String code = config.eventCode() == null ? "" : config.eventCode().trim();
		if (code.isEmpty())
		{
			panel.clearBoard();

			// With an account linked the code is optional: the event list picks one as
			// soon as it lands, so asking for a code here would be telling the player
			// to do something the plugin is about to do for them.
			final String token = config.accountToken();
			final boolean linked = token != null && !token.trim().isEmpty();
			panel.setStatus(linked
				? "Loading your events…"
				: "Set an event code in the plugin settings, or link your account.");
			return;
		}

		panel.setStatus("Loading…");
		api.fetchBoard(RsBingoConfig.SITE_URL, code.toUpperCase(), null, panel::showEvent, panel::setStatus);
	}

	/**
	 * Persist the panel's team choice. A code pointing at a different event simply
	 * won't match this name, and the panel falls back to the leading team.
	 */
	private void rememberTeam(String team)
	{
		if (team != null && !team.equals(config.selectedTeam()))
		{
			configManager.setConfiguration(RsBingoConfig.GROUP, "selectedTeam", team);
		}
	}

	private void scheduleRefresh()
	{
		cancelRefresh();

		final int seconds = config.refreshSeconds();
		if (seconds <= 0)
		{
			return;
		}

		// Floor at 15s so a mistyped config can't hammer the site.
		final long period = Math.max(15, seconds);
		refreshTask = executor.scheduleWithFixedDelay(
			() ->
			{
				if (panel != null)
				{
					panel.refreshCurrentTeam();
				}
			},
			period, period, TimeUnit.SECONDS);
	}

	private void cancelRefresh()
	{
		if (refreshTask != null)
		{
			refreshTask.cancel(false);
			refreshTask = null;
		}
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.game.ChatIconManager;

/**
 * Team colours beside the names of event participants in chat.
 *
 * Who is on which team is otherwise invisible in game: the panel knows the roster,
 * but a line of clan chat does not say whether the person speaking is on your team
 * or racing you. This marks every participant's name with their team's colour,
 * using the same rotation the board uses for regions so a colour means the same
 * thing in both places.
 */
@Singleton
class TeamChatIcons
{
	/**
	 * The event's team colours, taken from the organiser's team badges.
	 *
	 * Fixed rather than rotated off the theme accent like the board's regions are:
	 * a team's colour is the same for everyone in the event, so it cannot depend on
	 * which theme each player happens to have chosen. Teams beyond the eighth wrap
	 * round, which is also what the badges do.
	 */
	private static final Color[] TEAM_COLOURS = {
		new Color(0x417CD5), // 1 blue
		new Color(0xD83D63), // 2 crimson
		new Color(0xFFAF52), // 3 amber
		new Color(0x4BC78B), // 4 green
		new Color(0xF96D42), // 5 orange
		new Color(0x9265E7), // 6 purple
		new Color(0x89585A), // 7 maroon
		new Color(0xEBDBF6), // 8 lavender
	};

	/** Chat lines are short; anything larger than this crowds the text. */
	private static final int SIZE = 10;

	/** Above a head there is room, and it is read at a glance rather than up close. */
	private static final int OVERHEAD_SIZE = 14;

	private final ChatIconManager chatIconManager;

	/** Team name -> the id ChatIconManager gave us. Registered once, recoloured in place. */
	private final Map<String, Integer> iconIds = new HashMap<>();

	/** Team name -> its position in the stable ordering, which decides its colour. */
	private final Map<String, Integer> teamOrder = new HashMap<>();

	/** Team name -> the larger swatch drawn over a player, built on first use. */
	private final Map<String, BufferedImage> overheads = new HashMap<>();

	/** Normalised player name -> team name. */
	private volatile Map<String, String> players = Collections.emptyMap();

	@Inject
	TeamChatIcons(ChatIconManager chatIconManager)
	{
		this.chatIconManager = chatIconManager;
	}

	/**
	 * Take the rosters from a board response.
	 *
	 * A team's colour is its own team number — the 1-8 the event assigns, which is
	 * what names the organiser's badges, so Team 1 is the Team 1 colour wherever it
	 * sits in the table. The list arrives sorted by points, so position in it says
	 * nothing; ordering by that would have recoloured both teams the moment one
	 * overtook the other.
	 *
	 * Teams on an older event with no number fall back to name order, which is at
	 * least stable, rather than to the order they arrived in.
	 */
	void setRoster(BoardModels.Board board)
	{
		if (board == null || board.teams.isEmpty())
		{
			return;
		}

		final Map<String, Integer> numbered = new LinkedHashMap<>();
		final List<String> unnumbered = new ArrayList<>();
		for (BoardModels.TeamSummary team : board.teams)
		{
			if (team.name == null || team.name.trim().isEmpty())
			{
				continue;
			}
			final String name = team.name.trim();
			if (team.number >= 1)
			{
				numbered.put(name, team.number - 1);
			}
			else
			{
				unnumbered.add(name);
			}
		}
		unnumbered.sort(String.CASE_INSENSITIVE_ORDER);

		final Map<String, String> byPlayer = new LinkedHashMap<>();
		for (BoardModels.TeamSummary team : board.teams)
		{
			if (team.name == null)
			{
				continue;
			}
			final String teamName = team.name.trim();
			for (String player : team.players)
			{
				final String key = normalise(player);
				if (!key.isEmpty())
				{
					byPlayer.put(key, teamName);
				}
			}
		}

		synchronized (this)
		{
			teamOrder.clear();
			overheads.clear();
			teamOrder.putAll(numbered);
			for (int i = 0; i < unnumbered.size(); i++)
			{
				teamOrder.put(unnumbered.get(i), i);
			}
			applyColours();
		}

		players = byPlayer;
	}

	/** Registers what is missing and recolours what is not, for the current theme. */
	private void applyColours()
	{
		for (Map.Entry<String, Integer> entry : teamOrder.entrySet())
		{
			final BufferedImage image = swatch(teamColour(entry.getValue()));
			final Integer existing = iconIds.get(entry.getKey());
			if (existing == null)
			{
				iconIds.put(entry.getKey(), chatIconManager.registerChatIcon(image));
			}
			else
			{
				// Reusing the id rather than registering again: every registration is
				// permanent for the session, so re-registering on each theme change
				// would grow the client's icon table for as long as the client runs.
				chatIconManager.updateChatIcon(existing, image);
			}
		}
	}

	/**
	 * The name with the sender's team icon added, or null when they are not in the
	 * event and the name should be left exactly as it is.
	 */
	String decorate(String name)
	{
		if (name == null || name.isEmpty())
		{
			return null;
		}

		final String team = players.get(normalise(stripTags(name)));
		if (team == null)
		{
			return null;
		}

		final Integer id;
		synchronized (this)
		{
			id = iconIds.get(team);
		}
		if (id == null)
		{
			return null;
		}

		return insertIcon(name, chatIconManager.chatIconIndex(id));
	}

	/**
	 * Puts the icon after any the client has already put there, so an ironman badge
	 * keeps its place and ours sits between it and the name rather than replacing it.
	 */
	static String insertIcon(String name, int iconIndex)
	{
		int at = 0;
		while (at < name.length() && name.charAt(at) == '<')
		{
			final int close = name.indexOf('>', at);
			if (close < 0)
			{
				break;
			}
			at = close + 1;
		}
		return name.substring(0, at) + "<img=" + iconIndex + ">" + name.substring(at);
	}

	/**
	 * A broadcast with the subject's team icon added, or null to leave it alone.
	 *
	 * A drop broadcast names the player inside the message rather than in the name
	 * field — "Hurt Dark received a drop: Twisted bow" — so the icon has to be
	 * placed in the text. Only a name standing on its own counts, so an item or a
	 * boss that happens to contain someone's name is not marked.
	 */
	String decorateBroadcast(String message)
	{
		if (message == null || message.isEmpty() || players.isEmpty())
		{
			return null;
		}

		// Case and non-breaking spaces are folded without changing any character's
		// position, so an index into this is an index into the original.
		final String haystack = message.replace(' ', ' ').toLowerCase(java.util.Locale.ROOT);

		String bestTeam = null;
		int bestAt = -1;
		int bestLength = 0;

		for (Map.Entry<String, String> entry : players.entrySet())
		{
			final String name = entry.getKey();
			int at = haystack.indexOf(name);
			while (at >= 0)
			{
				if (standsAlone(haystack, at, name.length())
					&& (bestAt < 0 || at < bestAt || (at == bestAt && name.length() > bestLength)))
				{
					bestTeam = entry.getValue();
					bestAt = at;
					bestLength = name.length();
				}
				at = haystack.indexOf(name, at + 1);
			}
		}

		if (bestTeam == null)
		{
			return null;
		}

		final Integer id;
		synchronized (this)
		{
			id = iconIds.get(bestTeam);
		}
		if (id == null)
		{
			return null;
		}

		return message.substring(0, bestAt)
			+ "<img=" + chatIconManager.chatIconIndex(id) + ">"
			+ message.substring(bestAt);
	}

	/**
	 * Whether the match is a whole name rather than part of a longer word. The
	 * character before may also be '>', which is where a colour tag ends.
	 */
	static boolean standsAlone(String text, int at, int length)
	{
		if (at > 0)
		{
			final char before = text.charAt(at - 1);
			if (before != '>' && !Character.isWhitespace(before))
			{
				return false;
			}
		}
		final int after = at + length;
		if (after < text.length())
		{
			final char c = text.charAt(after);
			return !Character.isLetterOrDigit(c);
		}
		return true;
	}

	/**
	 * The swatch to draw above a player's head, or null when they are not in the
	 * event. Larger than the chat one, which is sized to sit inside a line of text.
	 */
	BufferedImage overheadSwatch(String playerName)
	{
		final String team = players.get(normalise(stripTags(playerName == null ? "" : playerName)));
		if (team == null)
		{
			return null;
		}

		synchronized (this)
		{
			final Integer order = teamOrder.get(team);
			if (order == null)
			{
				return null;
			}
			return overheads.computeIfAbsent(team,
				t -> swatch(teamColour(order), OVERHEAD_SIZE));
		}
	}

	/** Drops the client's markup, leaving the name itself. */
	static String stripTags(String name)
	{
		return name.replaceAll("<[^>]*>", "");
	}

	/**
	 * Names are compared case-insensitively and with the client's non-breaking
	 * spaces turned back into ordinary ones — the website stores "Hurt Dark" where
	 * the client reports "Hurt Dark", and they are the same player.
	 */
	static String normalise(String name)
	{
		return name == null ? "" : name.replace(' ', ' ').trim().toLowerCase();
	}

	private static BufferedImage swatch(Color colour)
	{
		return swatch(colour, SIZE);
	}

	/** The badge colour for a team's position in the ordering, wrapping past the eighth. */
	static Color teamColour(int order)
	{
		return TEAM_COLOURS[Math.floorMod(order, TEAM_COLOURS.length)];
	}

	/** A rounded square in the team's colour, outlined so it reads on any background. */
	private static BufferedImage swatch(Color colour, int size)
	{
		final BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			// An outline, because the same colour has to carry over a bright chat
			// background and a dark scene without picking a second palette.
			g.setColor(new Color(0, 0, 0, 170));
			g.fillRoundRect(0, 0, size - 1, size - 1, size / 3, size / 3);
			g.setColor(colour);
			g.fillRoundRect(1, 1, size - 3, size - 3, size / 4, size / 4);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}
}

package com.rsbingo;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A team colour over the head of every event participant on screen.
 *
 * The chat marks say who is on which team when they speak; this says it while
 * they are standing in front of you, which is the other half of the same
 * question during an event.
 */
class TeamOverheadOverlay extends Overlay
{
	/**
	 * Clearance above the model, in the same units as {@link Player#getLogicalHeight()}.
	 * Enough to clear a player's name and the client's own overhead icons rather
	 * than landing on top of them.
	 */
	private static final int CLEARANCE = 40;

	/** Space between the swatch and the first letter of the name. */
	private static final int GAP = 2;

	/**
	 * Nudges the swatch off the baseline so it sits centred on the letters rather
	 * than hanging below them — text baselines sit above the glyph bottoms.
	 */
	private static final int BASELINE_LIFT = 2;

	private final Client client;
	private final TeamChatIcons teams;
	private final RsBingoConfig config;

	@Inject
	TeamOverheadOverlay(Client client, TeamChatIcons teams, RsBingoConfig config)
	{
		this.client = client;
		this.teams = teams;
		this.config = config;

		setPosition(OverlayPosition.DYNAMIC);
		// With the scene rather than over the interface, so the marks are hidden by
		// an open bank or inventory tab exactly as the players under them are.
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.overheadTeamIcons())
		{
			return null;
		}

		// Through the world view rather than Client.getPlayers(), which is deprecated
		// and which the hub's packager reports as such.
		for (Player player : client.getTopLevelWorldView().players())
		{
			if (player == null)
			{
				continue;
			}

			if (!config.overheadOwnPlayer() && player == client.getLocalPlayer())
			{
				continue;
			}

			final BufferedImage swatch = teams.overheadSwatch(player.getName());
			if (swatch == null)
			{
				continue;
			}

			final String name = player.getName();
			if (name == null)
			{
				continue;
			}

			// Positioned against where the name is drawn, not against the model.
			// getCanvasImageLocation centres an image on the height it is given, while
			// a name is placed by its baseline, so asking both for the same height put
			// the swatch above the name rather than beside it.
			//
			// Null off-screen, and for a player the client has not placed yet.
			final Point at = player.getCanvasTextLocation(graphics, name,
				player.getLogicalHeight() + CLEARANCE);
			if (at == null)
			{
				continue;
			}

			// Left of the first letter, sitting on the same baseline.
			graphics.drawImage(swatch,
				at.getX() - swatch.getWidth() - GAP,
				at.getY() - swatch.getHeight() + BASELINE_LIFT,
				null);
		}

		return null;
	}
}

package com.rsbingo;

/**
 * Formatting shared by the board and the tile view.
 *
 * Tile titles, descriptions and item names are typed by event organisers and get
 * rendered through Swing's HTML labels, so they are escaped in exactly one place
 * rather than in each panel that happens to display them.
 */
final class Text
{
	private Text()
	{
	}

	static String escape(String s)
	{
		if (s == null)
		{
			return "";
		}
		return s.replace("&", "&amp;")
			.replace("<", "&lt;")
			.replace(">", "&gt;")
			.replace("\"", "&quot;")
			.replace("'", "&#39;");
	}

	/**
	 * How long an event has left, from the ISO timestamps the site stores
	 * ({@code 2026-08-05T17:00:00.000Z}). Returns null when the dates are missing or
	 * unparseable, which is the signal to hide the line rather than show "Ended".
	 */
	static String eventCountdown(String startIso, String endIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		final java.time.Instant end = parseInstant(endIso);

		if (start != null && now.isBefore(start))
		{
			return "Starts in " + duration(start.toEpochMilli() - now.toEpochMilli());
		}
		if (end == null)
		{
			return null;
		}
		if (now.isAfter(end))
		{
			return "Ended";
		}
		return "Ends in " + duration(end.toEpochMilli() - now.toEpochMilli());
	}

	/**
	 * Whether now sits inside the event's window. Missing or unparseable dates are
	 * treated as "no limit at that end" — the same reading eventCountdown takes, and
	 * the server enforces the real answer regardless.
	 */
	static boolean withinEventWindow(String startIso, String endIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		if (start != null && now.isBefore(start))
		{
			return false;
		}
		final java.time.Instant end = parseInstant(endIso);
		return end == null || !now.isAfter(end);
	}

	/** True when the event's start is still ahead of us. */
	static boolean startsAfter(String startIso, java.time.Instant now)
	{
		final java.time.Instant start = parseInstant(startIso);
		return start != null && now.isBefore(start);
	}

	/** Two units at most: "2d 14h", "3h 20m", "12m", "<1m". */
	/**
	 * How long until an ISO 8601 instant, or null when there is none, it cannot be
	 * read, or it has already passed — in which case the caller has nothing to count
	 * down to and should say something else.
	 */
	static String untilRelease(String iso, java.time.Instant now)
	{
		if (iso == null || iso.trim().isEmpty())
		{
			return null;
		}
		try
		{
			final long millis = java.time.Instant.parse(iso.trim()).toEpochMilli() - now.toEpochMilli();
			return millis > 0 ? duration(millis) : null;
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}

	static String duration(long millis)
	{
		if (millis < 60_000)
		{
			return "<1m";
		}

		final long minutes = millis / 60_000;
		final long days = minutes / 1440;
		final long hours = (minutes % 1440) / 60;
		final long mins = minutes % 60;

		if (days > 0)
		{
			return hours > 0 ? (days + "d " + hours + "h") : (days + "d");
		}
		if (hours > 0)
		{
			return mins > 0 ? (hours + "h " + mins + "m") : (hours + "h");
		}
		return mins + "m";
	}

	private static java.time.Instant parseInstant(String iso)
	{
		if (iso == null || iso.trim().isEmpty())
		{
			return null;
		}
		try
		{
			return java.time.Instant.parse(iso.trim());
		}
		catch (java.time.format.DateTimeParseException e)
		{
			return null;
		}
	}

	/**
	 * Compact numbers, matching game.html's modal: 1.2M, 4.5K, 850. Showdown scores
	 * run into the millions and the panel is 225px wide.
	 */
	/**
	 * Grouped digits, as the site's toLocaleString() renders them: 2542 -> "2,542".
	 * Points are compared between teams, and separators are what make a four figure
	 * total readable at a glance next to a three figure one.
	 */
	static String thousands(long n)
	{
		return GROUPED.format(n);
	}

	private static final java.text.NumberFormat GROUPED =
		java.text.NumberFormat.getIntegerInstance(java.util.Locale.US);

	static String compact(double n)
	{
		final double abs = Math.abs(n);
		if (abs >= 1_000_000)
		{
			return trimZero(n / 1_000_000) + "M";
		}
		if (abs >= 1_000)
		{
			return trimZero(n / 1_000) + "K";
		}
		return String.valueOf(Math.round(n));
	}

	private static String trimZero(double v)
	{
		final String s = String.format("%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package com.rsbingo;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import javax.swing.BorderFactory;
import javax.swing.JPanel;
import net.runelite.client.ui.ColorScheme;

/**
 * One square of the board: the tile's artwork, with its tier (Showdown) or points
 * (everything else) in the bottom corner.
 *
 * Progress is carried by the border alone — graded from neutral to gold — so the
 * artwork is always drawn at full brightness and stays recognisable at 50px.
 */
class TileCell extends JPanel
{
	// Colours are read from Brand at paint time, never cached in a field. A
	// `static final Color = Brand.COMPLETED` snapshots the palette at class load, so
	// it survived even a full panel rebuild and left tile borders on the old theme
	// while everything else changed.
	private static final int RADIUS = 6;
	private static final int BAR_HEIGHT = 3;
	/** Dark enough to read as an empty track over any artwork. */
	private static final Color BAR_TRACK = new Color(0, 0, 0, 170);


	private final BoardModels.BoardTile tile;
	private final boolean showdown;

	/** Tile details withheld by the event; drawn as a lock, opens nothing. */
	private final boolean locked;
	/** Kept so the tooltip can ask what this tile's counts are measured in — a Hybrid
	 *  board answers that per tile, not per board. */
	private final BoardModels.Board board;

	/** The tile this cell draws. The grid reads it to paint region perimeters in the
	 *  gutters between cells, which no single cell can reach. */
	BoardModels.BoardTile tile()
	{
		return tile;
	}

	/** Set once the artwork arrives; until then the cell paints its plain state. */
	private BufferedImage image;

	TileCell(BoardModels.BoardTile tile, BoardModels.Board board, TileImageCache images,
			 RsBingoConfig config, String siteUrl, int size, Runnable onClick)
	{
		this.tile = tile;
		this.board = board;
		this.showdown = board.isShowdown();
		this.locked = board.hiddenTiles && !tile.empty;

		setPreferredSize(new Dimension(size, size));
		setOpaque(false);
		setBackground(Brand.BG_WELL);
		setToolTipText(tooltip());

		if (tile.empty)
		{
			return;
		}

		final String url = config.showTileImages()
			? TileImageCache.resolve(siteUrl, tile.img)
			: null;
		if (url != null)
		{
			images.get(url, img ->
			{
				this.image = img;
				repaint();
			});
		}

		// A withheld tile opens nothing. The server sends no name, artwork or
		// checklist for one, so the detail view would be an empty panel — and the
		// website refuses the same click rather than showing it.
		if (locked)
		{
			return;
		}

		setCursor(new Cursor(Cursor.HAND_CURSOR));
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onClick.run();
			}
		});
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		super.paintComponent(graphics);

		final Graphics2D g = (Graphics2D) graphics.create();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);

			final int w = getWidth();
			final int h = getHeight();

			// Rounded, like the site's tiles. The artwork is clipped to the same shape
			// so it can't paint over the corners.
			//
			// The fill carries progress the way the site's does: a tile lifts from the
			// plain background towards the completed one as it climbs, so a Showdown
			// board's spread of tiers is visible without reading a single badge, and a
			// finished tile is lit rather than merely outlined.
			g.setColor(Brand.BG_WELL);
			g.fillRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);

			if (tile.empty)
			{
				g.setColor(Brand.BORDER.darker());
				g.drawRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
				return;
			}

			// Withheld: a lock and nothing else. The points badge is deliberately left
			// off — the site replaces the whole cell with its padlock, so showing what
			// a tile is worth here would give away more than the website does.
			if (locked)
			{
				g.setColor(Brand.BORDER);
				g.drawRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
				paintLock(g, w, h);
				return;
			}

			g.setClip(new java.awt.geom.RoundRectangle2D.Float(0, 0, w - 1, h - 1, RADIUS, RADIUS));

			final float progress = progress();

			// Painted under the artwork, never over it, so the art keeps its own
			// colours — the same order the site uses, where the item sprite sits on
			// the tinted tile rather than being washed by it.
			paintTierWash(g, w, h, progress);

			if (image != null)
			{
				// Contain rather than crop: tile art is often a full item sprite and
				// cropping it makes tiles hard to tell apart at 50px.
				final double scale = Math.min(w / (double) image.getWidth(), h / (double) image.getHeight());
				final int dw = Math.max(1, (int) Math.round(image.getWidth() * scale));
				final int dh = Math.max(1, (int) Math.round(image.getHeight() * scale));
				g.drawImage(image, (w - dw) / 2, (h - dh) / 2, dw, dh, null);
			}
			else
			{
				// No artwork — either still loading, unavailable, or switched off. Fall
				// back to a graded fill so the board still reads at a glance.
				g.setColor(shade(progress));
				g.fillRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
			}

			drawProgressBar(g, w, h);

			g.setClip(null);
			g.setColor(borderColor());
			g.drawRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);



			g.setFont(getFont().deriveFont(Font.BOLD, 10f));

			// Bottom right: the tier on a Showdown board, the tile's points elsewhere.
			// The border already carries completion, so the corner is free to say what
			// the tile is worth.
			final String badge = badgeText(g);
			if (badge != null)
			{
				final int tw = g.getFontMetrics().stringWidth(badge);
				// Sits above the progress bar rather than through it.
				drawOutlined(g, badge, w - tw - 3, h - BAR_HEIGHT - 4,
					badgeIsFinished() ? Brand.COMPLETED : Color.WHITE);
			}
		}
		finally
		{
			g.dispose();
		}
	}

	/**
	 * A bar across the bottom of the cell, so you can see which tiles are nearly
	 * there without opening each one.
	 *
	 * Drawn inside the rounded clip, so it takes the cell's corners with it. The
	 * track is always painted, even at zero, so a row of tiles can be compared
	 * against a common baseline rather than by the presence of a bar.
	 */
	private void drawProgressBar(Graphics2D g, int w, int h)
	{
		final int y = h - BAR_HEIGHT - 1;

		g.setColor(BAR_TRACK);
		g.fillRect(1, y, w - 2, BAR_HEIGHT);

		final int filled = (int) Math.round((w - 2) * (barPercent() / 100.0));
		if (filled > 0)
		{
			g.setColor(barIsFull() ? Brand.COMPLETED : Brand.TEXT_MAIN);
			g.fillRect(1, y, filled, BAR_HEIGHT);
		}
	}

	/**
	 * How full the cell's bar is, 0..100.
	 *
	 * On a Showdown tile that means progress toward the *next* tier, which is what
	 * "close to completion" means there — the tier reached is already in the badge
	 * and the border. Everywhere else it is the server's collected/required.
	 */
	private double barPercent()
	{
		if (showdown && tile.hasTierProgress())
		{
			return tile.tierMaxed() ? 100 : tile.pctToNextTier();
		}
		return tile.itemsPercent();
	}

	private boolean barIsFull()
	{
		return showdown && tile.hasTierProgress() ? tile.tierMaxed() : tile.done;
	}

	/**
	 * Whether the corner badge should read as finished, in gold.
	 *
	 * On a Showdown board that means every tier is banked — *not* {@code done}, which
	 * there reports the tile's item checklist and moves independently of the tier.
	 * Colouring a tier badge by {@code done} put gold on T3 tiles whose items happened
	 * to be complete, and left genuinely maxed T5 tiles white.
	 */
	private boolean badgeIsFinished()
	{
		return showdown ? tile.tierMaxed() : tile.done;
	}

	/**
	 * What goes in the bottom-right corner, or null when nothing fits or applies.
	 *
	 * Points are written "5p" so they can't be misread as a Showdown tier, falling
	 * back to the bare number on a board packed tight enough that even that one
	 * character would overrun the cell.
	 */
	private String badgeText(Graphics2D g)
	{
		if (showdown)
		{
			return (tile.tier != null && tile.tier > 0) ? ("T" + tile.tier) : null;
		}
		if (tile.points <= 0)
		{
			return null;
		}

		final String withSuffix = tile.points + "p";
		final int room = getWidth() - 6;
		return g.getFontMetrics().stringWidth(withSuffix) <= room
			? withSuffix
			: String.valueOf(tile.points);
	}

	/** Text sits on top of artwork, so it needs its own contrast. */
	private static void drawOutlined(Graphics2D g, String text, int x, int y, Color colour)
	{
		g.setColor(Color.BLACK);
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx != 0 || dy != 0)
				{
					g.drawString(text, x + dx, y + dy);
				}
			}
		}
		g.setColor(colour);
		g.drawString(text, x, y);
	}

	/** 0..1 — tier fraction on Showdown, done/not-done everywhere else. */
	private float progress()
	{
		if (showdown && tile.tier != null && tile.maxTier != null && tile.maxTier > 0)
		{
			return Math.max(0f, Math.min(1f, tile.tier / (float) tile.maxTier));
		}
		return tile.done ? 1f : 0f;
	}

	/**
	 * A padlock, centred.
	 *
	 * Proportions matter more than detail at this size: a 7x7 board gives each cell
	 * about 26px. Two things decide whether it reads as a lock — the shackle is
	 * clearly narrower than the body, and it is a true semicircle on short stems.
	 * Drawn from a bounding box taller than it is wide, the arc comes out as a
	 * pointed arch and the whole thing looks like a handbag.
	 */
	private static void paintLock(Graphics2D g, int w, int h)
	{
		final int min = Math.min(w, h);

		final int bodyW = Math.max(7, Math.round(min * 0.44f));
		final int bodyH = Math.max(5, Math.round(min * 0.30f));
		final int stem = Math.max(1, Math.round(min * 0.06f));

		// Widths are kept the same parity so that halving the difference is exact.
		// Centring the two independently leaves the shackle half a pixel off the
		// body whenever the cell width makes their parities differ, which at 26px is
		// plainly visible as a lopsided lock.
		int shackleW = Math.max(4, Math.round(bodyW * 0.62f));
		if (((bodyW - shackleW) & 1) != 0)
		{
			shackleW++;
		}

		// Semicircle: a bounding box as tall as it is wide, swept 0-180, is a half
		// circle of height shackleW/2.
		final int arcH = shackleW;
		final int shackleTotal = (arcH / 2) + stem;

		final int totalH = bodyH + shackleTotal;
		final int bodyY = (h - totalH) / 2 + shackleTotal;
		final int bodyX = (w - bodyW) / 2;
		// Derived from the body, not from the cell, so the two always share a centre.
		final int shackleX = bodyX + ((bodyW - shackleW) / 2);
		final int arcTop = bodyY - shackleTotal;

		g.setColor(Brand.TEXT_DIM);

		final java.awt.Stroke previous = g.getStroke();
		g.setStroke(new java.awt.BasicStroke(Math.max(1f, min / 16f),
			java.awt.BasicStroke.CAP_BUTT, java.awt.BasicStroke.JOIN_MITER));
		g.drawArc(shackleX, arcTop, shackleW, arcH, 0, 180);
		// Stems from the arc's ends down onto the body.
		final int stemTop = arcTop + arcH / 2;
		g.drawLine(shackleX, stemTop, shackleX, bodyY);
		g.drawLine(shackleX + shackleW, stemTop, shackleX + shackleW, bodyY);
		g.setStroke(previous);

		g.fillRoundRect(bodyX, bodyY, bodyW, bodyH, 2, 2);
	}

	/**
	 * The diagonal tint a tile carries as it climbs its tiers, so a finished tile is
	 * lit rather than merely outlined and a Showdown board's spread is readable
	 * without checking a single badge.
	 *
	 * This mirrors the site's rule for {@code .tile.completed}, which washes the tile
	 * with the completion colour at 35% down to 12% alpha across the diagonal — not
	 * with the {@code --bg-completed} token, which is a much darker colour used for
	 * panels behind the board. Scaling the alpha by progress turns the site's on/off
	 * state into the gradient across tiers.
	 */
	private static void paintTierWash(Graphics2D g, int w, int h, float progress)
	{
		if (progress <= 0f)
		{
			return;
		}

		final Color c = Brand.COMPLETED;
		final int near = Math.round(255 * 0.35f * progress);
		final int far = Math.round(255 * 0.12f * progress);

		g.setPaint(new java.awt.GradientPaint(
			0, 0, new Color(c.getRed(), c.getGreen(), c.getBlue(), near),
			w, h, new Color(c.getRed(), c.getGreen(), c.getBlue(), far)));
		g.fillRoundRect(0, 0, w - 1, h - 1, RADIUS, RADIUS);
	}

	/** Cold-to-warm fill used when there is no artwork to draw. */
	private static Color shade(float progress)
	{
		return Brand.blend(Brand.BG_WELL, Brand.COMPLETED.darker(), progress);
	}

	private Color borderColor()
	{
		if (tile.empty)
		{
			return Brand.BORDER.darker();
		}
		final float p = progress();
		if (p >= 1f)
		{
			return Brand.COMPLETED;
		}
		if (p <= 0f)
		{
			return Brand.BORDER;
		}
		// Part-way tiles get a border between neutral and complete, so a Showdown
		// board's spread of tiers is visible without reading every badge.
		return Brand.blend(Brand.BORDER, Brand.COMPLETED, p);
	}

	private String tooltip()
	{
		if (tile.empty)
		{
			return null;
		}

		final StringBuilder tip = new StringBuilder("<html><b>")
			.append(Text.escape(tile.displayTitle())).append("</b>");

		if (locked)
		{
			tip.append("<br>Hidden until the organiser releases the board");
			final String when = Text.untilRelease(board.tilesReleaseAt, java.time.Instant.now());
			if (when != null)
			{
				tip.append("<br>Revealed in ").append(when);
			}
			return tip.append("</html>").toString();
		}

		if (showdown && tile.tier != null)
		{
			tip.append("<br>Tier ").append(tile.tier).append(" of ").append(tile.maxTier);
		}
		else
		{
			tip.append("<br>").append(tile.done ? "Complete" : "Not complete");
		}

		// Not on Showdown: the tier above is what the tile is judged on, and an item
		// count there reads as progress towards something that is not being measured.
		if (!showdown && tile.xp == null && (tile.hasCounts() || tile.neededCount() > 0))
		{
			// Unit-aware: on a Hybrid board these counts are points toward a threshold
			// for a showdown tile, and items for a blackout one, on the same grid.
			tip.append("<br>").append(tile.progressTextWithUnit(board));
		}

		return tip.append("</html>").toString();
	}
}

