/**
 * The tile "modal". A RuneLite side panel is ~225px wide, so a floating dialog
 * would be unusable — this is a full-panel view swapped in over the grid with a
 * back button, which is the idiomatic equivalent.
 *
 * It shows what game.html's modal shows: title, artwork, points, a progress bar,
 * the Showdown tier line, the description, and the checklist or breakdowns.
 *
 * The one thing it leaves out is the tag list. Tags name the bosses and skills that
 * Point Rates already lists *with* their values, and on a 225px panel that
 * duplicate ran to several lines.
 *
 * Anything that can wrap is a read-only {@link JTextArea} rather than an HTML
 * {@link JLabel}. Swing's {@code width:Npx} style is a hint, not a constraint — it
 * let long tag lists and descriptions render past the panel and lose their right
 * edge mid-word. A text area wraps to the width it is actually given, and as plain
 * text it also can't be tripped up by markup in an organiser's tile description.
 */
class TileDetailPanel extends JPanel
{
		/** XP figures run to millions; the site groups them and so do we. */
	private static final java.text.NumberFormat THOUSANDS =
		java.text.NumberFormat.getIntegerInstance(java.util.Locale.US);

	private final TileImageCache images;
	private final RsBingoConfig config;
	private final String siteUrl;
	private final Submitter submitter;

	/**
	 * How the tile view files a submission. Implemented by the panel, which knows the
	 * event, the team and the logged-in character.
	 */
	interface Submitter
	{
		/** The character to submit as, or null when they are not on the viewed team. */
		String submittingAs();

		/** False while the event is still withholding the codeword submissions carry. */
		boolean canSubmit();

		void submit(BoardModels.BoardTile tile, BoardModels.SubmitOption option, Consumer<String> onStatus);
	}

	private final JLabel imageLabel = new JLabel();
	private final javax.swing.JTextPane title;
	private final JLabel status = new JLabel();
	private final JLabel meta = new JLabel();
	private final Brand.ProgressBar progress = new Brand.ProgressBar();
	private final JLabel tierLine = new JLabel();

	/**
	 * The named board area this tile belongs to, with a swatch in that region's
	 * colour. Without the name the outline on the board is just a colour; without the
	 * swatch the name does not tie to the outline the player is looking at.
	 */
	private final JPanel regionSwatch = new JPanel();
	private final JLabel regionLabel = new JLabel();
	private final JPanel regionRow = new JPanel();
	private final JTextArea description;
	private final JPanel checklist = Brand.section();

	private final JLabel xpTotal = new JLabel();
	private final JLabel xpGoal = new JLabel();
	private final JLabel xpHeading = Brand.sectionLabel("Team XP Breakdown");
	private final JPanel xpPlayers = Brand.section();

	private final JLabel descriptionHeading = Brand.sectionLabel("Description");
	private final JLabel ratesHeading = Brand.sectionLabel("Point Rates");
	private final JPanel rates = Brand.section();
	private final JLabel progressHeading = Brand.sectionLabel("Player Progress");
	private final JPanel playerProgress = Brand.section();
	private final JLabel checklistHeading = Brand.sectionLabel("Checklist");

	private final JLabel submitHeading = Brand.sectionLabel("Submit");
	private final JPanel submitWell = Brand.well();
	private final JComboBox<BoardModels.SubmitOption> submitBox = new JComboBox<>();
	private final JButton submitButton = Brand.button("Take screenshot & submit", Brand.ACCENT);
	private final JLabel submitAs = new JLabel();
	/** Breathing room so the button doesn't sit flush against the picker. */
	private final JPanel submitGap = spacer(6);
	private final JTextArea submitStatus = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_MAIN);

	/** Wells wrapping the sections above, held so they can be hidden with them. */
	private final JPanel descriptionWell = Brand.well();
	private final JPanel xpWell = Brand.well();
	private final JPanel checklistWell = Brand.well();

	TileDetailPanel(TileImageCache images, RsBingoConfig config, String siteUrl,
					Submitter submitter, Runnable onBack)
	{
		this.images = images;
		this.config = config;
		this.siteUrl = siteUrl;
		this.submitter = submitter;

		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBackground(Brand.BG_TILE);
		setBorder(BorderFactory.createEmptyBorder(6, Brand.PAD, 10, Brand.PAD));

		// Outlined in the accent rather than the border colour: this is the only way
		// out of a tile, and against BG_WELL a border-coloured outline is nearly the
		// same value as the panel behind it, so the control read as a caption strip
		// rather than something to press.
		final JButton back = Brand.button("< Back to board", Brand.TEXT_BRIGHT);
		back.setFont(Brand.bold(14f));
		back.setMaximumSize(new Dimension(Integer.MAX_VALUE, 32));
		back.addActionListener(e -> onBack.run());

		// The artwork is the tile's identity — the site centres it and gives it room.
		imageLabel.setHorizontalAlignment(SwingConstants.CENTER);
		imageLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
		imageLabel.setBorder(BorderFactory.createEmptyBorder(4, 0, 8, 0));

		title = centeredPane(Brand.bold(15f), Brand.TEXT_BRIGHT);

		status.setFont(FontManager.getRunescapeSmallFont());
		meta.setFont(FontManager.getRunescapeSmallFont());
		meta.setForeground(Brand.TEXT_DIM);

		tierLine.setFont(FontManager.getRunescapeSmallFont());
		tierLine.setForeground(Brand.TEXT_MAIN);
		tierLine.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

		// The site gives the XP figure its own oversized readout, centred in a well;
		// it is the whole point of the tile, so it gets the same emphasis here.
		xpTotal.setFont(Brand.bold(22f));
		xpTotal.setForeground(Brand.TEXT_BRIGHT);
		xpTotal.setAlignmentX(Component.CENTER_ALIGNMENT);
		xpGoal.setFont(FontManager.getRunescapeSmallFont());
		xpGoal.setForeground(Brand.TEXT_DIM);
		xpGoal.setAlignmentX(Component.CENTER_ALIGNMENT);

		description = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_MAIN);

		for (Component c : new Component[]{back, title, status, meta,
			progress, tierLine, description, checklist})
		{
			((JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
		}

		descriptionWell.add(description);
		xpWell.add(Brand.centered(xpTotal));
		xpWell.add(Brand.centered(xpGoal));
		checklistWell.add(checklist);

		add(back);
		// The title sat directly against the button, which made the two read as one
		// block instead of a control and a heading.
		add(Box.createVerticalStrut(12));
		add(title);
		add(Brand.centered(imageLabel));
		add(Brand.centered(status));
		add(Brand.centered(meta));

		regionRow.setLayout(new java.awt.FlowLayout(java.awt.FlowLayout.CENTER, 6, 0));
		regionRow.setOpaque(false);
		regionSwatch.setPreferredSize(new Dimension(9, 9));
		regionSwatch.setBorder(BorderFactory.createLineBorder(new Color(0, 0, 0, 140)));
		regionLabel.setFont(FontManager.getRunescapeSmallFont());
		regionLabel.setForeground(Brand.TEXT_DIM);
		regionRow.add(regionSwatch);
		regionRow.add(regionLabel);
		regionRow.setVisible(false);
		add(Brand.centered(regionRow));

		add(Box.createVerticalStrut(8));
		add(progress);
		add(tierLine);
		add(Box.createVerticalStrut(2));
		add(xpWell);
		add(descriptionHeading);
		add(descriptionWell);
		add(ratesHeading);
		add(rates);
		add(progressHeading);
		add(playerProgress);
		add(xpHeading);
		add(xpPlayers);
		submitAs.setFont(FontManager.getRunescapeSmallFont());
		submitAs.setForeground(Brand.TEXT_DIM);

		submitBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 24));
		submitBox.setBackground(Brand.BG_WELL);
		submitBox.setForeground(Brand.TEXT_BRIGHT);
		submitBox.setFont(FontManager.getRunescapeSmallFont());

		submitButton.setFont(FontManager.getRunescapeSmallFont());
		submitButton.setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));
		submitButton.addActionListener(e -> onSubmitClicked());

		for (Component c : new Component[]{submitAs, submitBox, submitGap, submitButton, submitStatus})
		{
			((JComponent) c).setAlignmentX(Component.LEFT_ALIGNMENT);
			submitWell.add(c);
		}

		add(checklistHeading);
		add(checklistWell);
		add(submitHeading);
		add(submitWell);
	}

	/** The tile currently shown, so the submit button knows what it is filing against. */
	private BoardModels.BoardTile showing;

	private void onSubmitClicked()
	{
		final BoardModels.SubmitOption option = (BoardModels.SubmitOption) submitBox.getSelectedItem();
		if (showing == null || option == null)
		{
			return;
		}

		submitButton.setEnabled(false);
		Brand.setWrapped(submitStatus, "Capturing…");
		submitter.submit(showing, option, message ->
		{
			Brand.setWrapped(submitStatus, message);
			submitButton.setEnabled(true);
		});
	}

	/**
	 * The submit controls, shown only when this character can actually use them:
	 * the tile has to take submissions, a codeword has to be configured, and the
	 * logged-in account has to be on the team being viewed. Anything else and the
	 * whole section stays hidden rather than offering a button that will fail.
	 */
	private void buildSubmit(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		final String as = submitter.submittingAs();

		// No section at all when there is nothing to act on: not on this team, the
		// tile takes no submissions, or the tile is already finished. A tile can be
		// complete with items still unclaimed — "any 1 of 5" needs one — so the
		// remaining options are real but pointless, and offering them just invites
		// evidence a reviewer has to reject.
		final boolean eligible = as != null && !tile.done && !tile.submitItems.isEmpty();
		submitHeading.setVisible(eligible);
		submitWell.setVisible(eligible);
		if (!eligible)
		{
			return;
		}

		submitAs.setText("as " + as);
		submitButton.setEnabled(true);

		// Outside the event's window there is nothing to offer. The server rejects
		// these anyway; saying so here beats letting someone take a screenshot and
		// upload it only to be told no.
		final String closed = board.submissionsClosedReason();
		if (closed != null)
		{
			submitBox.setVisible(false);
			submitGap.setVisible(false);
			submitButton.setVisible(false);
			Brand.setWrapped(submitStatus, closed);
			return;
		}

		// Anything approved or already awaiting review is left out: offering it again
		// only produces a duplicate for a reviewer to reject.
		submitBox.removeAllItems();
		for (BoardModels.SubmitOption option : tile.submitItems)
		{
			if (!option.alreadySubmitted())
			{
				submitBox.addItem(option);
			}
		}

		final boolean anythingLeft = submitBox.getItemCount() > 0;
		submitBox.setVisible(anythingLeft);
		submitGap.setVisible(anythingLeft);
		submitButton.setVisible(anythingLeft);
		Brand.setWrapped(submitStatus, anythingLeft
			? ""
			: "Everything on this tile is already submitted or approved.");
	}

	void show(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		// Two different questions, and conflating them is what broke Hybrid tiles.
		// `showdown` means "this board climbs tiers", which drives the tier badge and
		// the tier line. `showdownScored` means "this tile is judged on a score rather
		// than a checklist", which a Hybrid board answers per tile — those tiles have
		// no tiers but their progress is still counted in points, not items.
		final boolean showdown = board.isShowdown();
		final boolean showdownScored = tile.scoredByShowdownRules(board);

		// Header: the site writes "3 | Prison Break", dropping the position on
		// Showdown tiles where the tier matters more than the square.
		setCentered(title, showdown && tile.hasTierProgress()
			? tile.displayTitle()
			: tile.pos + " | " + tile.displayTitle());

		imageLabel.setIcon(null);
		final String url = config.showTileImages()
			? TileImageCache.resolve(siteUrl, tile.img)
			: null;
		if (url != null)
		{
			images.get(url, img -> imageLabel.setIcon(new ImageIcon(fit(img, 165, 110))));
		}

		if (showdown && tile.tier != null)
		{
			final int max = tile.maxTier == null ? 0 : tile.maxTier;
			status.setText("Tier " + tile.tier + " of " + max);
			status.setForeground(tile.tierMaxed() ? Brand.COMPLETED : Brand.TEXT_DIM);
		}
		else
		{
			status.setText(tile.done ? "Complete" : "Not complete");
			status.setForeground(tile.done ? Brand.COMPLETED : Brand.TEXT_DIM);
		}

		// A Showdown tile scores by tier, not by a flat value or a checklist, so it
		// gets neither figure: the tile's "points" field is not what it pays, and the
		// item count is not what it is judged on. Printing "10 PTS · 0/1 items" under
		// "Tier 4 of 5" described a tile that does not exist. The tier line below
		// carries what actually matters.
		// A Hybrid showdown tile keeps this line: unlike a Showdown tile it does pay a
		// flat value, so "120 PTS" is the truth. What it must not claim is a count of
		// items — its collected/required are points toward a threshold, and printing
		// "600/500 items" described a tile needing six hundred drops.
		meta.setVisible(!showdown);
		if (!showdown)
		{
			final StringBuilder m = new StringBuilder();
			m.append(tile.points).append(" PTS");
			if (tile.xp == null && !showdownScored && (tile.hasCounts() || tile.neededCount() > 0))
			{
				m.append("  ·  ").append(tile.progressTextWithUnit(board));
			}
			meta.setText(m.toString());
		}

		// Tags are deliberately not shown: they name the same bosses and skills that
		// Point Rates lists with their values attached, and on a 225px panel the
		// duplicate list cost several lines without adding anything.
		final boolean hasRates = !tile.rates.isEmpty();

		applyRegion(tile, board);
		applyProgress(tile, showdown, showdownScored, board);

		final boolean hasDescription = tile.description != null && !tile.description.isEmpty();
		descriptionHeading.setVisible(hasDescription);
		descriptionWell.setVisible(hasDescription);
		if (hasDescription)
		{
			Brand.setWrapped(description, tile.description);
		}

		showing = tile;
		buildSubmit(tile, board);
		buildRates(tile);
		buildPlayerProgress(tile, hasRates);
		buildXp(tile);
		// A Showdown tile's items already appear in both sections above, priced and
		// attributed; the site drops the plain checklist there for the same reason.
		// An XP tile has no items at all — its breakdown replaces the checklist.
		buildChecklist(tile, board, !hasRates && tile.xp == null);

		revalidate();
		repaint();
	}

	/**
	 * Name the area this tile sits in, in that area's own colour.
	 *
	 * The index comes from the board's region list rather than from anything derived
	 * here — that list is ordered by the event's tile definitions, which is what makes
	 * the swatch match the outline the website draws around the same tiles.
	 */
	private void applyRegion(BoardModels.BoardTile tile, BoardModels.Board board)
	{
		final int idx = board.regionIndex(tile.region);
		if (idx < 0)
		{
			regionRow.setVisible(false);
			return;
		}
		regionRow.setVisible(true);
		regionSwatch.setBackground(Brand.regionColor(idx));
		regionLabel.setText("Region: " + tile.region);
		regionLabel.setForeground(Brand.TEXT_DIM);
	}

	private void applyProgress(BoardModels.BoardTile tile, boolean showdown,
		boolean showdownScored, BoardModels.Board board)
	{
		// A Hybrid showdown tile: one threshold, no ladder. It still deserves the score
		// line — the bar alone does not say what the numbers are — but worded for
		// completion rather than for a next tier it can never reach.
		if (!showdown && showdownScored)
		{
			progress.setVisible(true);
			tierLine.setVisible(true);
			progress.setProgress(tile.itemsPercent(), tile.done);

			final String have = tile.hasTierProgress()
				? Text.compact(tile.score)
				: Text.compact(tile.collected == null ? 0 : tile.collected);
			final String need = tile.hasTierProgress()
				? Text.compact(tile.tierThreshold)
				: Text.compact(tile.required == null ? 0 : tile.required);

			tierLine.setText(tile.done
				? have + " / " + need + " pts - complete"
				: String.format("%s / %s pts - %.1f%% complete", have, need, tile.itemsPercent()));
			return;
		}

		if (showdown && tile.hasTierProgress())
		{
			progress.setVisible(true);
			tierLine.setVisible(true);

			if (tile.tierMaxed())
			{
				progress.setProgress(100, true);
				tierLine.setText("T" + tile.tier + " - " + Text.compact(tile.score) + " pts - MAX");
				return;
			}

			progress.setProgress(tile.pctToNextTier(), false);

			final String reached = (tile.tier == null || tile.tier == 0) ? "No tier" : ("T" + tile.tier);
			tierLine.setText(String.format("%s - %s / %s - %.1f%% to T%d",
				reached,
				Text.compact(tile.score),
				Text.compact(tile.nextTierAt()),
				tile.pctToNextTier(),
				(tile.tier == null ? 0 : tile.tier) + 1));
			return;
		}

		tierLine.setVisible(false);

		// An XP tile's bar tracks XP toward the goal; it has no items to count.
		if (tile.xp != null)
		{
			progress.setVisible(true);
			progress.setProgress(tile.xp.percent(), tile.done);
			return;
		}

		if (tile.done || tile.hasCounts() || tile.neededCount() > 0)
		{
			progress.setVisible(true);
			progress.setProgress(tile.itemsPercent(), tile.done);
		}
		else
		{
			progress.setVisible(false);
		}
	}

	/**
	 * An XP tile's readout: the team's total against the goal, then who earned it.
	 * These tiles carry no items, so this is all there is to show — previously the
	 * panel said "No item checklist on this tile" and left it at that.
	 */
	private void buildXp(BoardModels.BoardTile tile)
	{
		final BoardModels.XpProgress xp = tile.xp;
		final boolean present = xp != null;

		xpWell.setVisible(present);
		xpHeading.setVisible(present);
		xpPlayers.setVisible(present);
		xpPlayers.removeAll();

		if (!present)
		{
			return;
		}

		xpTotal.setText(THOUSANDS.format(Math.round(xp.collected)));
		xpTotal.setForeground(tile.done ? Brand.COMPLETED : Brand.TEXT_BRIGHT);
		xpGoal.setText("/ " + THOUSANDS.format(Math.round(xp.required)) + " XP");

		if (xp.players.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, "No XP gained on this tile yet.");
			xpPlayers.add(none);
			return;
		}

		for (BoardModels.XpPlayer player : xp.players)
		{
			xpPlayers.add(Brand.valueRow(
				player.name == null ? "" : player.name,
				THOUSANDS.format(Math.round(player.xp)) + " XP",
				Brand.TEXT_BRIGHT,
				Brand.ACCENT,
				Brand.BG_WELL));
			xpPlayers.add(Box.createVerticalStrut(2));
		}
	}

	/** "Point Rates": what one kill / one XP / one drop is worth on this tile. */
	private void buildRates(BoardModels.BoardTile tile)
	{
		rates.removeAll();
		ratesHeading.setVisible(!tile.rates.isEmpty());
		rates.setVisible(!tile.rates.isEmpty());

		for (BoardModels.Rate rate : tile.rates)
		{
			rates.add(Brand.valueRow(
				rate.label == null ? "" : rate.label,
				rate.rate == null ? "" : rate.rate,
				Brand.TEXT_MAIN,
				Brand.TEXT_BRIGHT,
				Brand.BG_WELL));
			rates.add(Box.createVerticalStrut(2));
		}
	}

	/**
	 * "Player Progress": each teammate's total on this tile, then the kills, XP and
	 * drops that made it up.
	 *
	 * @param expected whether this tile should have a breakdown at all — the server
	 *                 only sends one for the tile that was asked for, so an empty
	 *                 list on a rates-bearing tile means "still loading", not "nobody
	 *                 has done anything".
	 */
	private void buildPlayerProgress(BoardModels.BoardTile tile, boolean expected)
	{
		playerProgress.removeAll();
		progressHeading.setVisible(expected);
		playerProgress.setVisible(expected);

		if (!expected)
		{
			return;
		}

		if (tile.players.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, "No progress on this tile yet.");
			playerProgress.add(none);
			return;
		}

		for (BoardModels.PlayerProgress player : tile.players)
		{
			playerProgress.add(Brand.valueRow(
				player.name == null ? "" : player.name,
				Text.compact(player.points) + " pts",
				Brand.TEXT_BRIGHT,
				Brand.ACCENT,
				Brand.BG_WELL));

			for (BoardModels.ProgressLine line : player.lines)
			{
				playerProgress.add(Brand.valueRow(
					(line.label == null ? "" : line.label) + ": " + line.gainText(),
					Text.compact(line.points) + " pts",
					Brand.TEXT_DIM,
					Brand.TEXT_MAIN,
					Brand.BG_TILE));
			}

			playerProgress.add(Box.createVerticalStrut(6));
		}
	}

	private void buildChecklist(BoardModels.BoardTile tile, BoardModels.Board board, boolean show)
	{
		checklist.removeAll();
		checklistHeading.setVisible(show);
		checklistWell.setVisible(show);

		if (!show)
		{
			return;
		}

		for (BoardModels.TileItem item : tile.items)
		{
			final boolean done = item.approved >= item.need;
			checklist.add(row(
				item.label + (item.need > 1 ? (" (" + item.approved + "/" + item.need + ")") : ""),
				done,
				!done && item.pending > 0,
				item.player));
		}

		for (BoardModels.TileGroup group : tile.groups)
		{
			if (group.name != null && !group.name.isEmpty())
			{
				final JTextArea header = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.ACCENT);
				Brand.setWrapped(header, group.name + logicSuffix(group.logic));
				header.setBorder(BorderFactory.createEmptyBorder(8, 0, 2, 0));
				checklist.add(header);
			}
			for (BoardModels.TileGroupItem gi : group.items)
			{
				checklist.add(row(gi.label, gi.approved, gi.pending, gi.player));
			}
		}

		if (tile.items.isEmpty() && tile.groups.isEmpty())
		{
			final JTextArea none = Brand.wrapping(FontManager.getRunescapeSmallFont(), Brand.TEXT_DIM);
			Brand.setWrapped(none, board.hiddenTiles
				? "Tiles are hidden on this event."
				: "No item checklist on this tile.");
			checklist.add(none);
		}
	}

	private static String logicSuffix(String logic)
	{
		if (logic == null)
		{
			return "";
		}
		switch (logic)
		{
			case "any1":
				return " (any 1)";
			case "any2":
				return " (any 2)";
			case "any3":
				return " (any 3)";
			case "any4":
				return " (any 4)";
			default:
				return "";
		}
	}

	/**
	 * A checklist line in one of three states, as the site draws them: approved,
	 * awaiting review, or untouched. Without the middle one an item someone has
	 * already submitted proof for looks identical to one nobody has attempted.
	 */
	/** A fixed-height transparent strut that BoxLayout will not stretch. */
	private static JPanel spacer(int height)
	{
		final JPanel p = new JPanel();
		p.setOpaque(false);
		p.setPreferredSize(new Dimension(1, height));
		p.setMinimumSize(new Dimension(1, height));
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return p;
	}

	private static JTextArea row(String label, boolean approved, boolean pending, String player)
	{
		final Color colour;
		final String mark;
		if (approved)
		{
			colour = Brand.COMPLETED;
			mark = "✓  ";
		}
		else if (pending)
		{
			colour = Brand.ACCENT;
			mark = "?  ";
		}
		else
		{
			colour = Brand.TEXT_DIM;
			mark = "○  ";
		}

		// The site names the submitter next to the item, which is how a team sees at a
		// glance who already covered something.
		final String who = (player == null || player.trim().isEmpty()) ? "" : (" (" + player.trim() + ")");

		final JTextArea ta = Brand.wrapping(FontManager.getRunescapeSmallFont(), colour);
		Brand.setWrapped(ta, mark + label + who);
		ta.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		return ta;
	}

	/**
	 * Centre-aligned wrapping text. A JTextArea can't centre its lines, and an HTML
	 * JLabel brings back the width-hint clipping, so the tile title uses a text pane
	 * with a centred paragraph style.
	 */
	private static javax.swing.JTextPane centeredPane(Font font, Color foreground)
	{
		final javax.swing.JTextPane pane = new javax.swing.JTextPane();
		pane.setEditable(false);
		pane.setFocusable(false);
		pane.setOpaque(false);
		pane.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		pane.setFont(font);
		pane.setForeground(foreground);
		pane.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (pane.getCaret() instanceof DefaultCaret)
		{
			((DefaultCaret) pane.getCaret()).setUpdatePolicy(DefaultCaret.NEVER_UPDATE);
		}
		return pane;
	}

	/** Sets a centred pane's text; alignment has to be re-applied after each change. */
	private static void setCentered(javax.swing.JTextPane pane, String text)
	{
		pane.setText(text);

		final javax.swing.text.SimpleAttributeSet centre = new javax.swing.text.SimpleAttributeSet();
		javax.swing.text.StyleConstants.setAlignment(centre, javax.swing.text.StyleConstants.ALIGN_CENTER);
		pane.getStyledDocument().setParagraphAttributes(0, pane.getDocument().getLength(), centre, false);

		pane.setSize(Brand.CONTENT_WIDTH, Short.MAX_VALUE);
	}

	/**
	 * Scales art to fill the detail view's box, up as well as down.
	 *
	 * This used to return anything already small enough untouched, which meant a
	 * 56px icon sat at 56px beside a 165px one and the header looked ragged from
	 * tile to tile. The aspect ratio is kept, so "fill" means the longer side meets
	 * the box; nothing is cropped or stretched.
	 */
	private static BufferedImage fit(BufferedImage src, int maxW, int maxH)
	{
		final double scale = Math.min(maxW / (double) src.getWidth(), maxH / (double) src.getHeight());
		if (scale == 1)
		{
			return src;
		}
		final int w = Math.max(1, (int) Math.round(src.getWidth() * scale));
		final int h = Math.max(1, (int) Math.round(src.getHeight() * scale));
		final BufferedImage out = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.drawImage(src, 0, 0, w, h, null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}
}

package com.rsbingo;

import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.UnsupportedEncodingException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Tile artwork, fetched once and kept.
 *
 * The board re-renders on every refresh and every card switch, so the two things
 * that matter here are that a repaint never triggers a second fetch of the same
 * image, and that a board full of art can't grow without bound. Images are scaled
 * down at decode time to the largest size anything draws them at, which caps a
 * full cache near 15MB rather than the hundreds of megabytes the originals would
 * take.
 */
@Slf4j
@Singleton
class TileImageCache
{
	/**
	 * Nothing is drawn bigger than this, so nothing is kept bigger than this. Sized
	 * for the largest consumer, which is the tile detail view's 165x110 box — not the
	 * ~50px board cell. At 96 the detail view was handed art already reduced past the
	 * size it needed and had no way to get it back.
	 */
	private static final int MAX_DIM = 176;

	/**
	 * Lowered as MAX_DIM rose to keep the worst case in the same territory: 176px
	 * ARGB is roughly 124KB an entry, so this caps the cache near 15MB for a board
	 * with more distinct pictures than any real one has.
	 */
	private static final int MAX_ENTRIES = 120;

	/** Access-ordered LRU. Synchronized: fetches complete on OkHttp's threads. */
	private final Map<String, BufferedImage> cache = Collections.synchronizedMap(
		new LinkedHashMap<String, BufferedImage>(32, 0.75f, true)
		{
			@Override
			protected boolean removeEldestEntry(Map.Entry<String, BufferedImage> eldest)
			{
				return size() > MAX_ENTRIES;
			}
		});

	/** In-flight and permanently-failed URLs: both stop repaints re-queueing work. */
	private final Set<String> inFlight = ConcurrentHashMap.newKeySet();
	private final Set<String> failed = ConcurrentHashMap.newKeySet();

	private final OkHttpClient httpClient;

	// Package-private rather than private so PanelPreview can build one directly.
	@Inject
	TileImageCache(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	/**
	 * @param onLoad run on the EDT if and when the image is available — immediately
	 *               for a cache hit, later for a fetch, never on failure.
	 */
	void get(String url, Consumer<BufferedImage> onLoad)
	{
		if (url == null || url.isEmpty() || failed.contains(url))
		{
			return;
		}

		final BufferedImage hit = cache.get(url);
		if (hit != null)
		{
			onLoad.accept(hit);
			return;
		}

		// A board of 100 cells paints repeatedly; only the first paint should fetch.
		if (!inFlight.add(url))
		{
			return;
		}

		final HttpUrl parsed = HttpUrl.parse(url);
		if (parsed == null)
		{
			inFlight.remove(url);
			failed.add(url);
			return;
		}

		httpClient.newCall(new Request.Builder().url(parsed).get().build()).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				inFlight.remove(url);
				log.debug("rs-bingo tile image failed: {}", url, e);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (Response res = response)
				{
					if (!res.isSuccessful() || res.body() == null)
					{
						// A missing image stays missing; don't ask again.
						failed.add(url);
						return;
					}

					final BufferedImage decoded = decodeScaled(res.body().byteStream());
					if (decoded == null)
					{
						failed.add(url);
						return;
					}

					cache.put(url, decoded);
					SwingUtilities.invokeLater(() -> onLoad.accept(decoded));
				}
				catch (IOException e)
				{
					log.debug("rs-bingo tile image unreadable: {}", url, e);
				}
				finally
				{
					inFlight.remove(url);
				}
			}
		});
	}

	private static BufferedImage decodeScaled(InputStream in) throws IOException
	{
		final BufferedImage src = ImageIO.read(in);
		if (src == null)
		{
			return null;
		}

		final int w = src.getWidth();
		final int h = src.getHeight();
		if (w <= 0 || h <= 0)
		{
			return null;
		}
		if (w <= MAX_DIM && h <= MAX_DIM)
		{
			return src;
		}

		final double scale = Math.min(MAX_DIM / (double) w, MAX_DIM / (double) h);
		final int tw = Math.max(1, (int) Math.round(w * scale));
		final int th = Math.max(1, (int) Math.round(h * scale));

		final BufferedImage out = new BufferedImage(tw, th, BufferedImage.TYPE_INT_ARGB);
		final Graphics2D g = out.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
			g.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			g.drawImage(src, 0, 0, tw, th, null);
		}
		finally
		{
			g.dispose();
		}
		return out;
	}

	/**
	 * Turns a tile's stored image reference into a URL, following the same rule the
	 * website uses (game.html's {@code safeImgSrc}). There are three shapes and they
	 * are not interchangeable:
	 *
	 * <ul>
	 *   <li>an absolute URL — an organiser pasted a link; <b>refused</b>, see below</li>
	 *   <li>{@code events/<id>/images/x.png} — a per-event upload, already a full
	 *       path from the site root</li>
	 *   <li>anything else ({@code OFM055/x.png}, {@code default/x.png}) — a shared
	 *       gallery image, which lives under {@code images/}</li>
	 * </ul>
	 *
	 * Treating that third case as root-relative is what left most of a board blank:
	 * the paths 404 and the cells fall back to a plain fill.
	 *
	 * WebP is sent the long way round, through the site's converter — see
	 * {@link #CONVERTER}.
	 */
	static String resolve(String baseUrl, String img)
	{
		if (img == null || img.trim().isEmpty())
		{
			return null;
		}

		final String path = img.trim();
		if (path.contains("://") || path.startsWith("//"))
		{
			// An organiser can paste an absolute link into the tile editor, and the
			// website renders it. The plugin will not: this string arrives in an API
			// response, and a plugin may only contact addresses that are hardcoded or
			// entered by the user, never ones a server hands it. The tile keeps its
			// colour fill instead. Anything else here is a path on the site.
			//
			// "//host/x.png" is included: it currently resolves onto our own host
			// rather than off-site, but it is written as an absolute reference and
			// the rule is easier to trust when it has no exceptions.
			return null;
		}

		String base = baseUrl == null ? "" : baseUrl.trim();
		while (base.endsWith("/"))
		{
			base = base.substring(0, base.length() - 1);
		}

		if (path.startsWith("events/"))
		{
			return isWebp(path) ? convert(base, path) : base + "/" + path;
		}

		// Gallery images: the stored reference is relative to images/, and the
		// segments are rebuilt rather than concatenated because the filenames
		// contain spaces and quotes.
		final StringBuilder plain = new StringBuilder("images");
		final StringBuilder encoded = new StringBuilder(base).append("/images");
		for (String segment : path.replace('\\', '/').split("/"))
		{
			if (segment.isEmpty() || ".".equals(segment) || "..".equals(segment))
			{
				continue;
			}
			plain.append('/').append(segment);
			encoded.append('/').append(encodeSegment(segment));
		}

		return isWebp(path) ? convert(base, plain.toString()) : encoded.toString();
	}

	/**
	 * The site endpoint that re-encodes WebP as PNG.
	 *
	 * The JDK has no WebP reader, so those tiles decoded to null and drew as empty
	 * cells. Carrying a Java decoder meant shipping a third-party dependency, which
	 * the Plugin Hub bundles, hash-verifies and explicitly asks submitters to avoid;
	 * converting on the server keeps this plugin dependency-free. If the site cannot
	 * convert either, it returns the original and the tile is blank as it was before.
	 */
	private static final String CONVERTER = "/plugin_img.php?src=";

	private static boolean isWebp(String path)
	{
		return path.length() > 5 && path.regionMatches(true, path.length() - 5, ".webp", 0, 5);
	}

	/** Whole path in one query value, so the slashes are encoded along with it. */
	private static String convert(String base, String sitePath)
	{
		return base + CONVERTER + encodeSegment(sitePath);
	}

	/** Percent-encodes one path segment; gallery filenames contain spaces and quotes. */
	private static String encodeSegment(String segment)
	{
		try
		{
			return URLEncoder.encode(segment, StandardCharsets.UTF_8.name()).replace("+", "%20");
		}
		catch (UnsupportedEncodingException e)
		{
			return segment;
		}
	}
}

package com.rsbingo;

import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin deliberately does no scoring — the server does that. What it does do
 * is derive display values from the server's numbers, and those are worth pinning:
 * a wrong "% to next tier" is the kind of thing nobody notices until an event is
 * live and a team is arguing about it.
 *
 * Figures below are real ones from event NSM930.
 */
public class BoardLogicTest
{
	private static BoardModels.BoardTile showdownTile(int tier, int maxTier, double score, int threshold)
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.pos = 1;
		t.tier = tier;
		t.maxTier = maxTier;
		t.score = score;
		t.tierThreshold = threshold;
		return t;
	}

	@Test
	public void tierProgressMatchesTheServersTier()
	{
		// pos 1: 3,076,134.4 pts at 1M per tier -> tier 3, 76.9% of the way to T4.
		final BoardModels.BoardTile t = showdownTile(3, 5, 3_076_134.4, 1_000_000);

		assertTrue(t.hasTierProgress());
		assertFalse(t.tierMaxed());
		assertEquals(4_000_000.0, t.nextTierAt(), 0.001);
		assertEquals(76.9, t.pctToNextTier(), 0.05);
	}

	@Test
	public void maxedTileIsFlaggedRatherThanShowingAnUnreachableTarget()
	{
		// pos 6: 6.17M with 5 tiers of 1M all banked. The next threshold would be
		// 6M, which it has passed — so the panel must say MAX, not "102% to T6".
		final BoardModels.BoardTile t = showdownTile(5, 5, 6_165_465.2, 1_000_000);

		assertTrue(t.tierMaxed());
	}

	/**
	 * On a Showdown board {@code done} reports the tile's item checklist, which moves
	 * independently of the tier. Real NSM930 tiles sit on both sides of this: Demonic
	 * is T3 with done=true, while Multi Mayhem is a maxed T5 with done=false. Anything
	 * that treats one as the other mislabels both.
	 */
	@Test
	public void tierCompletionIsIndependentOfItemCompletion()
	{
		final BoardModels.BoardTile demonic = showdownTile(3, 5, 3_055_031, 1_000_000);
		demonic.done = true;
		assertFalse("done items must not imply a maxed tier", demonic.tierMaxed());

		final BoardModels.BoardTile multiMayhem = showdownTile(5, 5, 6_165_465, 1_000_000);
		multiMayhem.done = false;
		assertTrue("a maxed tier must not depend on the item checklist", multiMayhem.tierMaxed());
	}

	@Test
	public void percentIsClampedAndNeverExceedsFull()
	{
		final BoardModels.BoardTile over = showdownTile(2, 5, 9_999_999, 1_000_000);
		assertEquals(100.0, over.pctToNextTier(), 0.001);

		final BoardModels.BoardTile none = showdownTile(0, 5, 0, 1_000_000);
		assertEquals(0.0, none.pctToNextTier(), 0.001);
	}

	@Test
	public void nonShowdownTilesHaveNoTierProgress()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.done = true;

		assertFalse(t.hasTierProgress());
		assertFalse(t.tierMaxed());
		assertEquals(0.0, t.pctToNextTier(), 0.001);
	}

	/**
	 * A Godsword needs three shards plus any one of five hilts — four things. The
	 * checklist lists eight rows, so summing it reports 1/8 (12.5%) for a tile that
	 * is really 1/4 (25%) done. The server caps a group by its logic and sends the
	 * counts it judged completion on; the panel must use those.
	 */
	@Test
	public void groupedTilesUseTheServersCountsNotTheChecklistLength()
	{
		final BoardModels.BoardTile godsword = new BoardModels.BoardTile();
		for (String shard : new String[]{"Godsword Shard 1", "Godsword Shard 2", "Godsword Shard 3"})
		{
			final BoardModels.TileItem item = new BoardModels.TileItem();
			item.label = shard;
			item.need = 1;
			godsword.items.add(item);
		}
		final BoardModels.TileGroup hilts = new BoardModels.TileGroup();
		hilts.name = "Hilt";
		hilts.logic = "any1";
		for (String hilt : new String[]{"Armadyl", "Bandos", "Saradomin", "Zamorak", "Zaros"})
		{
			final BoardModels.TileGroupItem gi = new BoardModels.TileGroupItem();
			gi.label = hilt;
			gi.approved = "Bandos".equals(hilt);
			hilts.items.add(gi);
		}
		godsword.groups.add(hilts);

		// What summing the checklist would have said, and why it is wrong.
		assertEquals(8, godsword.neededCount());
		assertEquals(1, godsword.approvedCount());

		godsword.collected = 1;
		godsword.required = 4;

		assertTrue(godsword.hasCounts());
		assertEquals("1/4", godsword.progressText());
		assertEquals(25.0, godsword.itemsPercent(), 0.001);
	}

	@Test
	public void tilesFallBackToTheChecklistWhenTheServerSendsNoCounts()
	{
		// An older deployment omits these fields; the panel still has to draw a bar.
		final BoardModels.BoardTile tile = new BoardModels.BoardTile();
		final BoardModels.TileItem item = new BoardModels.TileItem();
		item.label = "Twisted Bow";
		item.need = 4;
		item.approved = 1;
		tile.items.add(item);

		assertFalse(tile.hasCounts());
		assertEquals("1/4", tile.progressText());
		assertEquals(25.0, tile.itemsPercent(), 0.001);
	}

	@Test
	public void completedTilesReadAsFullRegardlessOfCounts()
	{
		final BoardModels.BoardTile tile = new BoardModels.BoardTile();
		tile.done = true;
		assertEquals(100.0, tile.itemsPercent(), 0.001);
	}

	@Test
	public void itemCountsSpanFlatItemsAndGroups()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();

		final BoardModels.TileItem dwh = new BoardModels.TileItem();
		dwh.label = "Dragon Warhammer";
		dwh.need = 2;
		dwh.approved = 1;
		t.items.add(dwh);

		final BoardModels.TileGroup g = new BoardModels.TileGroup();
		g.name = "Barrows";
		final BoardModels.TileGroupItem a = new BoardModels.TileGroupItem();
		a.approved = true;
		final BoardModels.TileGroupItem b = new BoardModels.TileGroupItem();
		b.approved = false;
		g.items.add(a);
		g.items.add(b);
		t.groups.add(g);

		assertEquals(2, t.approvedCount());
		assertEquals(4, t.neededCount());
	}

	@Test
	public void hiddenTilesFallBackToTheirPosition()
	{
		final BoardModels.BoardTile t = new BoardModels.BoardTile();
		t.pos = 7;
		t.title = "";

		assertEquals("Tile 7", t.displayTitle());
	}

	@Test
	public void perEventUploadsResolveFromTheSiteRoot()
	{
		assertEquals("https://rs-bingo.com/events/NSM930/images/x.png",
			TileImageCache.resolve("https://rs-bingo.com", "events/NSM930/images/x.png"));

		// A trailing slash on the configured site URL must not double up.
		assertEquals("https://rs-bingo.com/events/NSM930/images/x.png",
			TileImageCache.resolve("https://rs-bingo.com/", "events/NSM930/images/x.png"));
	}

	/**
	 * Anything that isn't an events/ upload is a shared gallery image living under
	 * images/. Resolving these from the site root instead left most of OFM055's
	 * board blank — every path 404'd.
	 */
	@Test
	public void galleryImagesResolveUnderTheImagesDirectory()
	{
		assertEquals("https://rs-bingo.com/images/OFM055/Champion_s_cape.png",
			TileImageCache.resolve("https://rs-bingo.com", "OFM055/Champion_s_cape.png"));

		assertEquals("https://rs-bingo.com/images/default/raids_fit.png",
			TileImageCache.resolve("https://rs-bingo.com", "default/raids_fit.png"));

		// Filenames really do contain spaces; a raw space is not a valid URL.
		assertEquals("https://rs-bingo.com/images/gallery/Abyssal%20whip.png",
			TileImageCache.resolve("https://rs-bingo.com", "gallery/Abyssal whip.png"));

		assertEquals("https://rs-bingo.com/images/a/b.png",
			TileImageCache.resolve("https://rs-bingo.com", "a\\b.png"));

		// "." and ".." are stripped, not resolved — so a path can never climb out of
		// images/. Matches the site, which filters those segments the same way.
		assertEquals("https://rs-bingo.com/images/a/a/b.png",
			TileImageCache.resolve("https://rs-bingo.com", "./a/../a/b.png"));
	}

	/**
	 * WebP has no reader in the JDK, so those tiles are fetched through the site's
	 * converter instead. The whole path goes in one query value — encoded slashes
	 * included — because it is a parameter, not a path.
	 */
	@Test
	public void webpIsRoutedThroughTheConverter()
	{
		assertEquals("https://rs-bingo.com/plugin_img.php?src=events%2FNSM930%2Fimages%2Fx.webp",
			TileImageCache.resolve("https://rs-bingo.com", "events/NSM930/images/x.webp"));

		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fdefault%2Fraids_fit.webp",
			TileImageCache.resolve("https://rs-bingo.com", "default/raids_fit.webp"));

		// The converter is told the cleaned path, so "." and ".." cannot reach it.
		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fa%2Fa%2Fb.webp",
			TileImageCache.resolve("https://rs-bingo.com", "./a/../a/b.webp"));

		// Case is the file system's business, not ours.
		assertEquals("https://rs-bingo.com/plugin_img.php?src=images%2Fg%2FA.WEBP",
			TileImageCache.resolve("https://rs-bingo.com", "g/A.WEBP"));

		// Formats the client can already decode keep going straight to the file.
		assertEquals("https://rs-bingo.com/images/g/a.png",
			TileImageCache.resolve("https://rs-bingo.com", "g/a.png"));

		// Off-site art is refused outright rather than converted — see
		// absoluteImageReferencesAreRefused().
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "https://i.imgur.com/abc.webp"));
	}

	/**
	 * An organiser can paste an absolute link into the tile editor and the website
	 * renders it, but the plugin must not fetch it: the address arrives in an API
	 * response, and a plugin may only contact addresses that are hardcoded or entered
	 * by the user. Returning null leaves the cell on its colour fill.
	 */
	@Test
	public void absoluteImageReferencesAreRefused()
	{
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "https://i.imgur.com/abc.png"));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "http://i.imgur.com/abc.png"));

		// Not just http(s): any scheme is a way out of the site.
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "file:///etc/passwd"));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", "//evil.example.com/x.png"));

		assertNull(TileImageCache.resolve("https://rs-bingo.com", ""));
		assertNull(TileImageCache.resolve("https://rs-bingo.com", null));
	}

	@Test
	public void scoresAreCompactedTheWayTheSiteDoes()
	{
		assertEquals("3.1M", Text.compact(3_076_134.4));
		assertEquals("5M", Text.compact(5_006_500));
		assertEquals("4.5K", Text.compact(4_500));
		assertEquals("850", Text.compact(850));
		assertEquals("0", Text.compact(0));
	}

	@Test
	public void progressLinesReadAsGainsOrCounts()
	{
		final BoardModels.ProgressLine kc = new BoardModels.ProgressLine();
		kc.label = "Nex";
		kc.gain = 163;
		kc.unit = "KC";
		assertEquals("+163 KC", kc.gainText());

		final BoardModels.ProgressLine xp = new BoardModels.ProgressLine();
		xp.gain = 259408;
		xp.unit = "XP";
		assertEquals("+259.4K XP", xp.gainText());

		// Drops are a count, not a gain — the site writes them as a multiplier.
		final BoardModels.ProgressLine drop = new BoardModels.ProgressLine();
		drop.gain = 1;
		drop.unit = "item";
		assertEquals("x1", drop.gainText());
	}

	@Test
	public void countdownReadsFromTheEventsOwnTimestamps()
	{
		// NSM930's real window.
		final String start = "2026-07-22T17:00:00.000Z";
		final String end = "2026-08-05T17:00:00.000Z";

		assertEquals("Starts in 2d 3h",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-07-20T14:00:00Z")));
		assertEquals("Ends in 3d 7h",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-08-02T10:00:00Z")));
		assertEquals("Ended",
			Text.eventCountdown(start, end, java.time.Instant.parse("2026-08-06T10:00:00Z")));

		// Missing or unparseable dates hide the line rather than claiming "Ended".
		assertNull(Text.eventCountdown(null, null, java.time.Instant.now()));
		assertNull(Text.eventCountdown("", "not a date", java.time.Instant.now()));
	}

	/**
	 * Submissions are only open between the two dates. The server enforces this too,
	 * but the panel must not offer a button that is guaranteed to be refused.
	 */
	@Test
	public void submissionsOnlyOpenInsideTheEventWindow()
	{
		final String start = "2026-07-22T17:00:00.000Z";
		final String end = "2026-08-05T17:00:00.000Z";

		assertFalse("before the start",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-07-20T14:00:00Z")));
		assertTrue("during",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-08-01T10:00:00Z")));
		assertFalse("after the end",
			Text.withinEventWindow(start, end, java.time.Instant.parse("2026-08-06T10:00:00Z")));

		// An event with no dates set is not thereby closed forever.
		assertTrue(Text.withinEventWindow(null, null, java.time.Instant.now()));
	}

	@Test
	public void closedSubmissionsSayWhichEndTheyAreOn()
	{
		final BoardModels.Board board = new BoardModels.Board();
		board.startDate = "2099-01-01T00:00:00.000Z";
		assertEquals("This event has not started yet.", board.submissionsClosedReason());

		board.startDate = "2020-01-01T00:00:00.000Z";
		board.endDate = "2020-02-01T00:00:00.000Z";
		assertEquals("This event has ended.", board.submissionsClosedReason());

		board.endDate = "2099-02-01T00:00:00.000Z";
		assertNull("open events give no reason", board.submissionsClosedReason());
	}

	@Test
	public void durationsCollapseToTwoUnits()
	{
		assertEquals("2d 14h", Text.duration(((2 * 24) + 14) * 3_600_000L));
		assertEquals("2d", Text.duration(2 * 24 * 3_600_000L));
		assertEquals("3h 20m", Text.duration((3 * 3_600_000L) + (20 * 60_000L)));
		assertEquals("12m", Text.duration(12 * 60_000L));
		assertEquals("<1m", Text.duration(30_000L));
	}

	/**
	 * The stamped frame is the whole point of the plugin's submission flow: it is
	 * what a reviewer looks at. It must come back as a decodable PNG the same size as
	 * the captured frame, never a null that silently drops the evidence.
	 */
	@Test
	public void proofScreenshotsEncodeAsPng() throws Exception
	{
		final java.awt.image.BufferedImage frame =
			new java.awt.image.BufferedImage(765, 503, java.awt.image.BufferedImage.TYPE_INT_RGB);

		final byte[] png = ProofShot.stamp(frame, "Hurt Summer Bingo 2026", "codeword123", "NewrockkuOS", "Twisted Bow");

		assertNotNull("a captured frame must always produce proof bytes", png);
		assertTrue(png.length > 0);

		// PNG magic, so this is a real image and not some other encoding.
		assertEquals((byte) 0x89, png[0]);
		assertEquals('P', png[1]);
		assertEquals('N', png[2]);
		assertEquals('G', png[3]);

		final java.awt.image.BufferedImage decoded =
			javax.imageio.ImageIO.read(new java.io.ByteArrayInputStream(png));
		assertNotNull(decoded);
		assertEquals(765, decoded.getWidth());
		assertEquals(503, decoded.getHeight());
	}

	@Test
	public void proofScreenshotsSurviveAMissingFrame()
	{
		// requestNextFrameListener can hand back nothing if the client is not drawing.
		assertNull(ProofShot.stamp(null, "Hurt Summer Bingo 2026", "codeword123", "NewrockkuOS", "Twisted Bow"));
	}

	@Test
	public void organiserSuppliedTitlesCannotInjectMarkupIntoHtmlTooltips()
	{
		// Tile titles reach the board's tooltips, which really are HTML.
		assertEquals("&lt;b&gt;bold&lt;/b&gt;", Text.escape("<b>bold</b>"));
		assertEquals("Tom &amp; Jerry", Text.escape("Tom & Jerry"));
		assertEquals("", Text.escape(null));
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the contract with plugin_board.php.
 *
 * The fixture is a real response from event NSM930, trimmed to three tiles. Gson
 * maps this by field name with no annotations, so a rename on the PHP side fails
 * silently at runtime — every field would simply be null and the panel would draw
 * an empty board. This test is what makes that break loudly instead.
 */
public class BoardParsingTest
{
	private static BoardModels.Board sample()
	{
		final InputStream in = BoardParsingTest.class.getResourceAsStream("/board_sample.json");
		assertNotNull("board_sample.json missing from test resources", in);
		return new Gson().fromJson(
			new InputStreamReader(in, StandardCharsets.UTF_8), BoardModels.Board.class);
	}

	@Test
	public void eventAndTeamHeaderParse()
	{
		final BoardModels.Board b = sample();

		assertEquals("NSM930", b.eventId);
		assertEquals("Hurt Summer Bingo 2026", b.name);
		assertEquals("Showdown", b.format);
		assertTrue(b.isShowdown());
		assertEquals(4, b.cols);
		assertEquals(4, b.rows);
		assertEquals("The Dark Knights", b.team);
		assertFalse(b.hiddenTiles);
	}

	@Test
	public void teamsCarryPointsAndPlayers()
	{
		final BoardModels.Board b = sample();

		final BoardModels.TeamSummary top = b.teams.get(0);
		assertEquals("The Dark Knights", top.name);
		assertEquals(3429, top.points);
		assertTrue(top.players.contains("Hurt Dark"));

		// The dropdown renders the summary directly, so toString is load-bearing.
		assertEquals("The Dark Knights", top.toString());
	}

	@Test
	public void tilesCarryEverythingThePanelDraws()
	{
		final BoardModels.Board b = sample();
		final BoardModels.BoardTile first = b.board.get(0);

		assertEquals(1, first.pos);
		assertEquals("Stop all the yelling!", first.title);
		assertEquals("events/NSM930/images/hidyboy.png", first.img);
		assertEquals(10, first.points);
		assertTrue(first.tags.contains("Combat"));

		// The Showdown fields the tier line depends on.
		assertEquals(Integer.valueOf(3), first.tier);
		assertEquals(Integer.valueOf(5), first.maxTier);
		assertTrue(first.hasTierProgress());
		assertEquals(4_000_000.0, first.nextTierAt(), 0.001);
	}

	@Test
	public void pointRatesParseForEveryEarningOnTheTile()
	{
		final BoardModels.BoardTile prisonBreak = sample().board.get(2);

		// Three bosses, one skill, two items — what the site's "Point Rates" lists.
		assertEquals(6, prisonBreak.rates.size());
		assertEquals("Boss: Corrupted Gauntlet", prisonBreak.rates.get(0).label);
		assertEquals("12000 pts/KC", prisonBreak.rates.get(0).rate);
		assertEquals("Skill: Herblore", prisonBreak.rates.get(3).label);
		assertEquals("0.3125 pts/XP", prisonBreak.rates.get(3).rate);
		assertEquals("Dragon Warhammer", prisonBreak.rates.get(4).label);
		assertEquals("450000 pts/item", prisonBreak.rates.get(4).rate);
	}

	@Test
	public void playerProgressParsesAndAddsUp()
	{
		final BoardModels.BoardTile prisonBreak = sample().board.get(2);

		final BoardModels.PlayerProgress top = prisonBreak.players.get(0);
		assertEquals("Tw1st3d1ron", top.name);
		assertEquals(999195.0, top.points, 0.001);
		assertEquals(3, top.lines.size());

		// Each line must sum to the player's total, or the card contradicts itself.
		double sum = 0;
		for (BoardModels.ProgressLine line : top.lines)
		{
			sum += line.points;
		}
		assertEquals(top.points, sum, 0.01);

		final BoardModels.ProgressLine first = top.lines.get(0);
		assertEquals("Corrupted Gauntlet", first.label);
		assertEquals("+70 KC", first.gainText());
		assertEquals(840000.0, first.points, 0.001);
	}

	@Test
	public void playerProgressIsOnlySentForTheRequestedTile()
	{
		final BoardModels.Board b = sample();

		// The fixture asked for tile 3, so only that tile carries a breakdown —
		// this is what keeps a board refresh small.
		assertTrue(b.board.get(2).players.size() > 0);
		assertTrue(b.board.get(0).players.isEmpty());
		assertTrue(b.board.get(1).players.isEmpty());

		// Rates, being small and static, ride along on every tile.
		assertFalse(b.board.get(0).rates.isEmpty());
		assertFalse(b.board.get(1).rates.isEmpty());
	}

	@Test
	public void itemChecklistParsesWithApprovedCounts()
	{
		final BoardModels.Board b = sample();

		// pos 3 is "Prison Break": two items, one of them approved.
		final BoardModels.BoardTile prisonBreak = b.board.get(2);
		assertEquals("Prison Break", prisonBreak.title);
		assertTrue(prisonBreak.done);
		assertEquals(2, prisonBreak.items.size());
		assertEquals("Dragon Warhammer", prisonBreak.items.get(0).label);
		assertEquals(1, prisonBreak.items.get(0).need);
		assertEquals(1, prisonBreak.items.get(0).approved);
		assertEquals(1, prisonBreak.approvedCount());
		assertEquals(2, prisonBreak.neededCount());
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the contract for the Hybrid format, where one board carries both kinds of
 * tile.
 *
 * The fixture is a real plugin_board.php response for a 2x2 Hybrid event:
 *   sq1 Drops    blackout, 1 of 2 items collected
 *   sq2 Zulrah   showdown, 600 pts against a 500 threshold - complete
 *   sq3 Pet Hunt showdown built from item values alone, 60 of 100 - not complete
 *   sq4 Mining   blackout XP tile, 50k of 100k
 *
 * The thing worth guarding here is that a Hybrid board is NOT a Showdown board.
 * Its showdown tiles have no tier ladder, so isShowdown() is false and the tile/tier
 * fields are absent - but those tiles are still judged on a score, so their
 * collected/required are points and must never be labelled as items.
 */
public class HybridBoardTest
{
	private static BoardModels.Board sample()
	{
		final InputStream in = HybridBoardTest.class.getResourceAsStream("/board_hybrid_sample.json");
		assertNotNull("board_hybrid_sample.json missing from test resources", in);
		return new Gson().fromJson(
			new InputStreamReader(in, StandardCharsets.UTF_8), BoardModels.Board.class);
	}

	private static BoardModels.BoardTile at(BoardModels.Board b, int pos)
	{
		for (BoardModels.BoardTile t : b.board)
		{
			if (t.pos == pos)
			{
				return t;
			}
		}
		throw new AssertionError("no tile at position " + pos);
	}

	@Test
	public void hybridIsNotScoredAsShowdown()
	{
		final BoardModels.Board b = sample();

		assertEquals("Hybrid", b.format);
		assertTrue(b.isHybrid());
		// The whole point: a Hybrid board pays flat points per tile and a line bonus
		// once, exactly like Blackout. Treating it as Showdown would draw tier badges
		// on tiles that cannot tier.
		assertFalse("Hybrid must not report itself as a Showdown board", b.isShowdown());
		assertEquals("no tier ladder, so no tier count", 0, b.numTiers);
		assertFalse("points breakdown is the flat kind", b.points.isShowdown);
	}

	@Test
	public void everyTileSaysWhichRulesScoreIt()
	{
		final BoardModels.Board b = sample();

		assertEquals("blackout", at(b, 1).tileType);
		assertEquals("showdown", at(b, 2).tileType);
		assertEquals("showdown", at(b, 3).tileType);
		assertEquals("blackout", at(b, 4).tileType);

		assertFalse(at(b, 1).scoredByShowdownRules(b));
		assertTrue(at(b, 2).scoredByShowdownRules(b));
		assertTrue(at(b, 3).scoredByShowdownRules(b));
		assertFalse(at(b, 4).scoredByShowdownRules(b));
	}

	@Test
	public void showdownTilesOnHybridCarryNoTierFields()
	{
		final BoardModels.Board b = sample();
		final BoardModels.BoardTile zulrah = at(b, 2);

		// Sending a tier here would give the tile a ladder it can never climb.
		assertNull("Hybrid showdown tiles must not carry a tier", zulrah.tier);
		assertNull("Hybrid showdown tiles must not carry a maxTier", zulrah.maxTier);
		assertFalse("so nothing can read them as maxed", zulrah.tierMaxed());

		// The score and its threshold are still sent - that is what the tile is judged on.
		assertTrue(zulrah.hasTierProgress());
		assertEquals(600.0, zulrah.score, 0.001);
		assertEquals(Integer.valueOf(500), zulrah.tierThreshold);
	}

	@Test
	public void progressCountsAreLabelledInTheirOwnUnit()
	{
		final BoardModels.Board b = sample();

		// The defect this guards: a showdown tile's counts are points toward a
		// threshold. Labelled "items" they read as a tile needing six hundred drops.
		assertEquals("600/500 pts", at(b, 2).progressTextWithUnit(b));
		assertEquals("60/100 pts", at(b, 3).progressTextWithUnit(b));

		// Blackout tiles on the same board still count items.
		assertEquals("1/2 items", at(b, 1).progressTextWithUnit(b));
	}

	@Test
	public void completionComesFromTheServerNotFromTheChecklist()
	{
		final BoardModels.Board b = sample();

		// sq2 is complete on score alone and has no items at all; anything deriving
		// completion from a checklist would call it unfinished.
		assertTrue(at(b, 2).done);
		assertTrue(at(b, 2).items.isEmpty());
		assertEquals(100.0, at(b, 2).itemsPercent(), 0.001);

		// sq3 has one approved item but is only 60 of 100 points, so it is not done.
		assertFalse(at(b, 3).done);
		assertEquals(60.0, at(b, 3).itemsPercent(), 0.001);

		// A blackout tile is still judged on its items.
		assertFalse(at(b, 1).done);
		assertEquals(50.0, at(b, 1).itemsPercent(), 0.001);
	}

	@Test
	public void onlyCompleteTilesPayAndTheyPayTheirOwnFlatPoints()
	{
		final BoardModels.Board b = sample();

		// Zulrah is the only complete tile, and a Hybrid showdown tile pays its own
		// points value rather than a tier reward.
		assertEquals(120, at(b, 2).points);
		assertEquals(120, b.points.tilePts);
		assertEquals(120, b.points.total);
		assertEquals(1, b.points.tiles.size());
		assertEquals("Zulrah", b.points.tiles.get(0).label);
		assertEquals(120, b.points.tiles.get(0).pts);
	}

	@Test
	public void showdownTilesKeepTheirRatesAndRemainSubmittable()
	{
		final BoardModels.Board b = sample();

		// Rates drive the "Point Rates" card, and their presence is what hides the
		// plain checklist for these tiles.
		assertFalse(at(b, 2).rates.isEmpty());
		assertFalse(at(b, 3).rates.isEmpty());

		// An items-only showdown tile still offers its item for submission, and the
		// item stays submittable after approval because each copy is worth points.
		assertEquals(1, at(b, 3).submitItems.size());
		assertEquals("Pet Snakeling", at(b, 3).submitItems.get(0).label);
	}

	@Test
	public void blackoutTilesOnAHybridBoardAreUntouched()
	{
		final BoardModels.Board b = sample();
		final BoardModels.BoardTile drops = at(b, 1);
		final BoardModels.BoardTile mining = at(b, 4);

		assertEquals(2, drops.items.size());
		assertEquals(2, drops.submitItems.size());
		assertTrue("a blackout tile has no rates card", drops.rates.isEmpty());

		// XP tiles still read their goal off the snapshots, not off items.
		assertNotNull("the XP tile keeps its xp block", mining.xp);
		assertEquals("mining", mining.xp.skill);
		assertEquals(50000.0, mining.xp.collected, 0.001);
		assertEquals(50.0, mining.xp.percent(), 0.001);
	}

	@Test
	public void aShowdownBoardStillReadsAsTiered()
	{
		// Guards the other direction: the per-tile flag must not have quietly turned
		// the Showdown format into something else. Its board still tiers, and a tile
		// with no tileType at all (an older server) is still scored by showdown rules.
		final BoardModels.Board sd = new BoardModels.Board();
		sd.format = "Showdown";
		final BoardModels.BoardTile legacy = new BoardModels.BoardTile();
		legacy.tileType = null;

		assertTrue(sd.isShowdown());
		assertFalse(sd.isHybrid());
		assertTrue("format decides when the tile does not say", legacy.scoredByShowdownRules(sd));

		final BoardModels.Board blackout = new BoardModels.Board();
		blackout.format = "Blackout";
		assertFalse(legacy.scoredByShowdownRules(blackout));
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.Graphics2D;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import okhttp3.OkHttpClient;

/**
 * Renders the side panel to PNG files without launching a RuneLite client.
 *
 * `./gradlew run` needs a full client, a login and a few minutes; this draws the
 * real panel — same components, same fonts, same live data — in a couple of
 * seconds, which is what you want when checking a layout change.
 *
 * <pre>
 *   ./gradlew preview -Pevent=NSM930
 *   ./gradlew preview -Pevent=NSM930 -Purl=http://localhost/bingotest -Ptile=5
 *   ./gradlew preview -Pevent=NSM930 -Pimages=false
 * </pre>
 *
 * Writes {@code board.png} and {@code tile.png} to {@code build/preview}.
 */
public class PanelPreview
{
	/** Enough for the board plus a long checklist; trimmed off in the PNG. */
	private static final int HEIGHT = 1000;

	public static void main(String[] args) throws Exception
	{
		final String url = property("rs.url", "https://rs-bingo.com");
		final String event = property("rs.event", "");
		final String team = property("rs.team", "");
		final boolean showImages = !"false".equalsIgnoreCase(property("rs.images", "true"));
		final int tileIndex = Integer.parseInt(property("rs.tile", "0"));
		final File out = new File(property("rs.out", "build/preview"));

		if (event.isEmpty())
		{
			System.err.println("No event code. Pass one: ./gradlew preview -Pevent=NSM930");
			System.exit(2);
		}

		if (!out.isDirectory() && !out.mkdirs())
		{
			System.err.println("Could not create " + out);
			System.exit(1);
		}

		final OkHttpClient http = new OkHttpClient();
		final RsBingoApi api = new RsBingoApi(http, new Gson());
		final TileImageCache images = new TileImageCache(http);

		final RsBingoConfig config = new RsBingoConfig()
		{
			@Override
			public String eventCode()
			{
				return event;
			}

			@Override
			public int refreshSeconds()
			{
				return 0;
			}

			@Override
			public boolean showTileImages()
			{
				return showImages;
			}

			@Override
			public String accountToken()
			{
				return property("rs.token", "");
			}

			@Override
			public String selectedTeam()
			{
				return team;
			}

		};

		// Palette has to be in place before the panel is built: components read Brand
		// at construction time, which is exactly why a live switch rebuilds the panel.
		final String themeKey = property("rs.theme", "");
		if (!themeKey.isEmpty())
		{
			final java.util.concurrent.CountDownLatch got = new java.util.concurrent.CountDownLatch(1);
			api.fetchThemes(url, list ->
			{
				for (BoardModels.Theme t : list.themes)
				{
					if (themeKey.equalsIgnoreCase(t.key))
					{
						Brand.applyPalette(t.vars);
						System.out.println("  theme: " + t.label + " (" + t.vars.get("--accent") + ")");
					}
				}
				got.countDown();
			});
			got.await(10, java.util.concurrent.TimeUnit.SECONDS);
		}

		final RsBingoPanel[] holder = new RsBingoPanel[1];
		// The client always passes RsBingoConfig.SITE_URL here; this harness is the one
		// caller that passes anything else, so a local copy of the site can be rendered.
		SwingUtilities.invokeAndWait(() -> holder[0] = new RsBingoPanel(
			api, images, config, url, () -> { }, t -> { }, t -> { }, e -> { },
			b -> { }, onFrame -> { }));
		final RsBingoPanel panel = holder[0];

		// There is no game client here, so the logged-in character has to be supplied
		// for the submit controls to appear at all.
		// Linked-account event list, if a token was supplied.
		final String token = property("rs.token", "");
		if (!token.isEmpty())
		{
			api.fetchMyEvents(url, token,
				list -> {
					panel.setMyEvents(list);
					System.out.println("  linked as " + list.username + ", " + list.events.size() + " events");
				},
				err -> System.out.println("  event list: " + err));
			Thread.sleep(1500);
		}

		final String asPlayer = property("rs.player", "");
		if (!asPlayer.isEmpty())
		{
			panel.setLocalPlayer(asPlayer);
		}

		// The panel needs a realised hierarchy for layout and font metrics to match
		// what the client shows. The window is never made visible.
		final JFrame frame = new JFrame("rs-bingo preview");
		SwingUtilities.invokeAndWait(() ->
		{
			// Undecorated, so the content pane is exactly the frame's width and the
			// panel renders at the 225px the client actually gives it.
			frame.setUndecorated(true);
			frame.getContentPane().add(panel);
			// Width is overridable so the panel can be rendered at sidebar widths other
			// than the 225 the plugin assumes — which is where layout that is pinned to
			// a constant rather than to the width it is given shows up.
			frame.setSize(Integer.parseInt(property("rs.width",
				String.valueOf(RsBingoPanel.PANEL_WIDTH))), HEIGHT);
			frame.addNotify();
			frame.validate();
		});

		// The panel reports fetch failures through its status line; here they should
		// end the run rather than leave it polling for a board that isn't coming.
		final AtomicReference<String> failure = new AtomicReference<>();
		api.fetchBoard(url, event, null, panel::showEvent, failure::set);

		if (!awaitTiles(panel, failure))
		{
			System.err.println(failure.get() != null
				? ("Could not load " + event + " from " + url + ": " + failure.get())
				: ("No board arrived from " + url + " for event " + event + "."));
			System.exit(1);
		}
		// Artwork lands asynchronously and there is no completion signal; give it a
		// moment to settle before drawing.
		Thread.sleep(showImages ? 2500 : 250);

		write(frame, panel, new File(out, "board.png"));

		final List<TileCell> cells = tileCells(panel);
		if (tileIndex >= 0 && tileIndex < cells.size())
		{
			final TileCell cell = cells.get(tileIndex);
			SwingUtilities.invokeAndWait(() -> cell.dispatchEvent(new MouseEvent(
				cell, MouseEvent.MOUSE_CLICKED, System.currentTimeMillis(), 0, 5, 5, 1, false)));
			// Opening a tile fetches its player breakdown; wait for that round trip
			// rather than screenshotting a half-filled card.
			Thread.sleep(2000);
			write(frame, panel, new File(out, "tile.png"));
		}

		SwingUtilities.invokeAndWait(frame::dispose);
		System.out.println("Wrote " + out.getAbsolutePath());
		System.exit(0);
	}

	/** Depth-first layout: validate() alone stops at containers already marked valid. */
	private static void layout(Component c)
	{
		if (c instanceof Container)
		{
			final Container container = (Container) c;
			container.doLayout();
			for (Component child : container.getComponents())
			{
				layout(child);
			}
		}
	}

	/** Polls for the board to render, rather than guessing at a fixed delay. */
	private static boolean awaitTiles(RsBingoPanel panel, AtomicReference<String> failure) throws Exception
	{
		for (int i = 0; i < 100; i++)
		{
			if (!tileCells(panel).isEmpty())
			{
				return true;
			}
			if (failure.get() != null)
			{
				return false;
			}
			Thread.sleep(100);
		}
		return false;
	}

	private static List<TileCell> tileCells(RsBingoPanel panel)
	{
		final List<TileCell> found = new ArrayList<>();
		collect(panel, found);
		return found;
	}

	private static void collect(Component c, List<TileCell> found)
	{
		if (c instanceof TileCell)
		{
			found.add((TileCell) c);
			return;
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collect(child, found);
			}
		}
	}

	private static void write(JFrame frame, RsBingoPanel panel, File file) throws Exception
	{
		// The panel calls revalidate() as content arrives, but that only queues a
		// layout pass — and nothing pumps that queue for a frame that is never shown,
		// so the board's cells would keep zero bounds and paint nothing. Lay it out
		// synchronously instead.
		SwingUtilities.invokeAndWait(() -> layout(frame));

		final BufferedImage img = new BufferedImage(
			Math.max(1, panel.getWidth()), Math.max(1, panel.getHeight()), BufferedImage.TYPE_INT_RGB);

		SwingUtilities.invokeAndWait(() ->
		{
			final Graphics2D g = img.createGraphics();
			try
			{
				panel.printAll(g);
			}
			finally
			{
				g.dispose();
			}
		});

		ImageIO.write(img, "png", file);
		System.out.println("  " + file.getName() + "  " + img.getWidth() + "x" + img.getHeight());
	}

	private static String property(String key, String fallback)
	{
		final String v = System.getProperty(key);
		return (v == null || v.isEmpty()) ? fallback : v;
	}
}

package com.rsbingo;

import com.google.gson.Gson;
import java.awt.Color;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Pins the contract for tile regions - named areas outlined on the board.
 *
 * The fixture is a real plugin_board.php response for a 5x5 Hybrid event with
 * three regions:
 *   Varrock     squares 1, 2, 6      (an L)
 *   Wilderness  squares 9, 10, 14, 15 (a 2x2 block)
 *   Zanaris     square 22            (alone)
 *
 * The one thing here that is easy to get wrong, and silently: a region's colour is
 * its index in {@link BoardModels.Board#regions}, and that list is ordered by the
 * event's tile *definitions*. The panel only ever receives tiles by board position,
 * so it cannot rebuild that order itself - which is why the server sends it. Order
 * it any other way and the panel paints a region a different colour from the one the
 * website draws around the same tiles.
 */
public class RegionBoardTest
{
	private static BoardModels.Board sample()
	{
		final InputStream in = RegionBoardTest.class.getResourceAsStream("/board_regions_sample.json");
		assertNotNull("board_regions_sample.json missing from test resources", in);
		return new Gson().fromJson(
			new InputStreamReader(in, StandardCharsets.UTF_8), BoardModels.Board.class);
	}

	@Test
	public void regionsArriveInTheServersOrder()
	{
		final BoardModels.Board b = sample();

		assertTrue(b.hasRegions());
		assertEquals(java.util.Arrays.asList("Varrock", "Wilderness", "Zanaris"), b.regions);

		assertEquals(0, b.regionIndex("Varrock"));
		assertEquals(1, b.regionIndex("Wilderness"));
		assertEquals(2, b.regionIndex("Zanaris"));
		assertEquals("a name that is not a region", -1, b.regionIndex("Lumbridge"));
		assertEquals("no region", -1, b.regionIndex(""));
		assertEquals("null is not a region", -1, b.regionIndex(null));
	}

	@Test
	public void tilesReportTheRegionTheySitIn()
	{
		final BoardModels.Board b = sample();

		assertEquals("Varrock", b.regionAt(1));
		assertEquals("Varrock", b.regionAt(2));
		assertEquals("Varrock", b.regionAt(6));
		assertEquals("Wilderness", b.regionAt(9));
		assertEquals("Wilderness", b.regionAt(15));
		assertEquals("Zanaris", b.regionAt(22));

		// Squares in no region, and squares off the board, both answer "".
		assertEquals("", b.regionAt(3));
		assertEquals("", b.regionAt(25));
		assertEquals("", b.regionAt(999));
	}

	@Test
	public void eachRegionGetsItsOwnColour()
	{
		final BoardModels.Board b = sample();

		final Color varrock = Brand.regionColor(b.regionIndex("Varrock"));
		final Color wilderness = Brand.regionColor(b.regionIndex("Wilderness"));
		final Color zanaris = Brand.regionColor(b.regionIndex("Zanaris"));

		assertNotEquals(varrock, wilderness);
		assertNotEquals(wilderness, zanaris);
		assertNotEquals(varrock, zanaris);

		// Stable: the same region asked twice is the same colour.
		assertEquals(varrock, Brand.regionColor(b.regionIndex("Varrock")));
	}

	@Test
	public void regionColoursMatchTheWebsitesFormula()
	{
		// The website resolves hsl(calc(var(--accent-h) + index * 137.508) 70% 60%) in
		// CSS. These are the values a browser actually computes for that rule, read off
		// the page rather than worked out here - the panel has to match what a player
		// is looking at on the board beside it, and a shade of drift is invisible in
		// code and obvious on screen.
		//
		// Note --accent-h is a whole number: themes.js rounds it, so the panel rounds
		// the accent's hue the same way before rotating. Skipping that put index 1 one
		// step off green.
		Brand.applyPalette(java.util.Collections.singletonMap("--accent", "#d8a830"));

		assertEquals(new Color(224, 184, 82), Brand.regionColor(0));
		assertEquals(new Color(82, 223, 224), Brand.regionColor(1));
		assertEquals(new Color(224, 82, 182), Brand.regionColor(2));
	}

	@Test
	public void regionColoursFollowTheTheme()
	{
		Brand.applyPalette(java.util.Collections.singletonMap("--accent", "#d8a830"));
		final Color gold = Brand.regionColor(0);

		Brand.applyPalette(java.util.Collections.singletonMap("--accent", "#ff6090"));
		final Color berry = Brand.regionColor(0);

		assertNotEquals("a region must re-colour with the theme", gold, berry);
		// Berry's accent hue is 342. Browser-measured, like the values above.
		assertEquals(new Color(224, 82, 124), berry);
		assertEquals(new Color(83, 224, 82), Brand.regionColor(1));
		assertEquals(new Color(122, 82, 224), Brand.regionColor(2));

		// Leave the palette as the rest of the suite expects to find it.
		Brand.applyPalette(java.util.Collections.singletonMap("--accent", "#d8a830"));
	}

	@Test
	public void anUnknownRegionFallsBackRatherThanThrowing()
	{
		// regionIndex returns -1 for a tile with no region, and every caller passes
		// that straight through. It must produce a colour, not an exception.
		assertEquals(Brand.TEXT_DIM, Brand.regionColor(-1));
	}

	@Test
	public void aBoardWithRegionsOffCarriesNone()
	{
		// What the panel receives when the event has regions switched off: an empty
		// list and no region on any tile, which is what stands the feature down without
		// the panel needing to know the setting exists.
		final BoardModels.Board off = new BoardModels.Board();
		assertFalse(off.hasRegions());
		assertEquals(-1, off.regionIndex("Varrock"));
		assertEquals("", off.regionAt(1));
	}

	@Test
	public void regionsAreIndependentOfHowATileScores()
	{
		final BoardModels.Board b = sample();

		// Square 9 is a showdown tile and square 1 a blackout one; both sit in regions.
		// Regions are a layout idea, so they must not track the scoring rules.
		assertEquals("showdown", tileAt(b, 9).tileType);
		assertEquals("Wilderness", tileAt(b, 9).region);
		assertEquals("blackout", tileAt(b, 1).tileType);
		assertEquals("Varrock", tileAt(b, 1).region);
	}

	private static BoardModels.BoardTile tileAt(BoardModels.Board b, int pos)
	{
		for (BoardModels.BoardTile t : b.board)
		{
			if (t.pos == pos)
			{
				return t;
			}
		}
		throw new AssertionError("no tile at position " + pos);
	}
}

package com.rsbingo;

import java.awt.Color;
import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Every theme's region colours must be the colours the website actually paints.
 *
 * The fixture is measured, not calculated: region_colors_web.tsv holds what a browser
 * resolved for {@code hsl(calc(var(--accent-h) + index * 137.508) 70% 60%)} under each
 * of the site's themes, read straight off the page. Recomputing the expectation in
 * Java would only prove this file agrees with itself — the point is that the panel
 * agrees with the board a player has open beside it.
 *
 * Two things that a three-theme spot check missed and this caught:
 *   - --accent-h is published rounded, so the hue has to be rounded before rotating.
 *   - Two themes ship a greyscale accent (#ffffff, #cccccc), where the site falls back
 *     to the default gold while Color.RGBtoHSB reports 0, which is red.
 */
public class RegionColourParityTest
{
	private static class Row
	{
		String theme;
		String accent;
		Color[] regions = new Color[3];
	}

	private static List<Row> fixture() throws Exception
	{
		final InputStream in = RegionColourParityTest.class
			.getResourceAsStream("/region_colors_web.tsv");
		assertNotNull("region_colors_web.tsv missing from test resources", in);

		final List<Row> rows = new ArrayList<>();
		try (BufferedReader r = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = r.readLine()) != null)
			{
				if (line.trim().isEmpty())
				{
					continue;
				}
				final String[] p = line.split("\t");
				final Row row = new Row();
				row.theme = p[0];
				row.accent = p[1];
				for (int i = 0; i < 3; i++)
				{
					final String[] c = p[2 + i].split(",");
					row.regions[i] = new Color(
						Integer.parseInt(c[0].trim()),
						Integer.parseInt(c[1].trim()),
						Integer.parseInt(c[2].trim()));
				}
				rows.add(row);
			}
		}
		return rows;
	}

	@Test
	public void everyThemesRegionColoursMatchTheWebsite() throws Exception
	{
		final List<Row> rows = fixture();
		assertTrue("expected the site's full theme list", rows.size() >= 30);

		final List<String> wrong = new ArrayList<>();
		for (Row row : rows)
		{
			Brand.applyPalette(Collections.singletonMap("--accent", row.accent));
			for (int i = 0; i < 3; i++)
			{
				final Color got = Brand.regionColor(i);
				if (!got.equals(row.regions[i]))
				{
					wrong.add(String.format("%s (accent %s) region %d: website %s, panel %s",
						row.theme, row.accent, i, rgb(row.regions[i]), rgb(got)));
				}
			}
		}

		// Restore the default so test ordering cannot leak a palette into another test.
		Brand.applyPalette(Collections.singletonMap("--accent", "#d8a830"));

		assertEquals("region colours differ from the website:\n  "
			+ String.join("\n  ", wrong) + "\n", 0, wrong.size());
	}

	@Test
	public void aGreyscaleAccentFallsBackTheWayTheSiteDoes()
	{
		// The case that was wrong: an accent with no hue to rotate away from. The site
		// substitutes hue 42; Color.RGBtoHSB reports 0, which is red.
		//
		// Note 42 is the site's stated fallback, NOT Obsidian's own hue, which rounds
		// to 43 - so these land a shade apart and must not be asserted equal. Both
		// values below are what a browser resolved for those accents.
		Brand.applyPalette(Collections.singletonMap("--accent", "#ffffff"));
		assertEquals(new Color(224, 182, 82), Brand.regionColor(0));

		Brand.applyPalette(Collections.singletonMap("--accent", "#cccccc"));
		assertEquals(new Color(224, 182, 82), Brand.regionColor(0));

		Brand.applyPalette(Collections.singletonMap("--accent", "#d8a830"));
		assertEquals(new Color(224, 184, 82), Brand.regionColor(0));
	}

	private static String rgb(Color c)
	{
		return c.getRed() + "," + c.getGreen() + "," + c.getBlue();
	}
}

